-- exposed for the per-asset dialog (DistributionSiloDialog.lua)
SmartDistribution.log            = log
SmartDistribution.cycleNext      = cycleNext
-- Step the ring, skipping any mode with no endpoint for this fill type (so e.g. slurry never lands on a
-- market mode when no market takes slurry). ft is optional: without it the old, ungated ring is used.
-- `role` is OPTIONAL and nil means the building's primary class, so every existing caller is unchanged.
-- The building tabs pass self.selectedRole, which is what gives a SILO half sharing a placeable with a
-- production the STORE-side ring (Move To) instead of the producer-side one (Store).
function SmartDistribution.cycleNextForAsset(asset, m, ft, role)   -- store-aware + pallet-aware (Hold Internal only where the asset spawns pallets)
    local step = function(cur)
        return cycleNext(cur, assetCanStore(asset, role), SmartDistribution.assetHasMarket(asset),
                         palletSpawnerFillTypes(asset) ~= nil and SmartDistribution.palletSpawnAllowed(),
                         assetCanMoveTo(asset, role))
    end
    local nxt = step(m)
    if ft == nil then return nxt end
    for _ = 1, 12 do                                          -- ring is 10 long; the cap is a backstop
        if SmartDistribution.modeHasEndpoint(asset, ft, nxt, role) then return nxt end
        nxt = step(nxt)
        if nxt == m then return m end                         -- full lap: nothing else is valid, stay put
    end
    return nxt
end
-- The VALID modes for this (building, product), in ring order -- i.e. exactly what stepping forward
-- would visit, collected instead of walked.
--
-- DERIVED FROM THE FORWARD RING ON PURPOSE. A hand-written reverse table would be a second source of
-- truth for "what order do modes come in", free to drift from cycleNext the next time a mode is added;
-- this cannot, because it IS cycleNext. Cost is one full lap of a <=12 entry ring, and it is called on
-- a CLICK, never from populate -- modeHasEndpoint scans placeableSystem, which is precisely the shape
-- 5.46 / 5.52 exist to keep off the menu's hot path.
function SmartDistribution.validModeRing(asset, ft, role)
    local out = {}
    if asset == nil or ft == nil then return out end
    local step = function(cur)
        return cycleNext(cur, assetCanStore(asset, role), SmartDistribution.assetHasMarket(asset),
                         palletSpawnerFillTypes(asset) ~= nil and SmartDistribution.palletSpawnAllowed(),
                         assetCanMoveTo(asset, role))
    end
    local m, seen = MODE.DISTRIBUTE, {}
    for _ = 1, 14 do                                           -- ring is <=12; the cap is a backstop
        if seen[m] then break end
        seen[m] = true
        if SmartDistribution.modeHasEndpoint(asset, ft, m, role) then out[#out + 1] = m end
        m = step(m)
    end
    return out
end

-- One step BACKWARD, the mirror of cycleNextForAsset.
-- If the current mode is not in the ring at all -- which 5.48 makes possible and legitimate, since a
-- player's mode is never rewritten when its endpoint disappears -- fall back to the last valid entry
-- rather than refusing to move, so the arrow is never dead.
function SmartDistribution.cyclePrevForAsset(asset, m, ft, role)
    local ring = SmartDistribution.validModeRing(asset, ft, role)
    local n = #ring
    if n == 0 then return m end
    for i = 1, n do
        if ring[i] == m then
            return ring[i > 1 and (i - 1) or n]                -- wraps to the end
        end
    end
    return ring[n]
end

SmartDistribution.siloFillTypes  = siloFillTypes
SmartDistribution.assetFillTypes = assetConfigFillTypes        -- allocator view (sheds: stored only)

-- "Cycle all" target: if every current mode is identical, advance it one step;
-- if they differ, unify to the anchor (first) mode WITHOUT stepping. So the first
-- click makes a mixed group uniform, and the next click steps them together.
local function bulkCycleTarget(modes, anchor, step)
    if #modes == 0 then return anchor end
    for i = 2, #modes do if modes[i] ~= modes[1] then return anchor end end
    return step(modes[1])
end

-- ---- productions: point accessor + class check + whole-plant on/off state ----
-- (output MODE for productions is driven through ProductionDistributeSell's shared
-- 5-state virtual mode, not the generic applyAssetMode path; the dialog dispatches
-- on isProductionAsset.)
function SmartDistribution.productionPointOf(p) return getProductionPoint(p) end
function SmartDistribution.isProductionAsset(p) return getProductionPoint(p) ~= nil end

-- whole-plant on/off + run status (all production lines together). enabled = at
-- least one line active; running = at least one actually producing. Fully guarded.
function SmartDistribution.productionInfo(p)
    local pp = getProductionPoint(p)
    if pp == nil then return nil end
    local total   = (type(pp.productions) == "table") and #pp.productions or 0
    local active  = (type(pp.activeProductions) == "table") and #pp.activeProductions or 0
    local running = 0
    local RUN = (ProductionPoint ~= nil and ProductionPoint.PROD_STATUS ~= nil and ProductionPoint.PROD_STATUS.RUNNING) or 1
    if type(pp.activeProductions) == "table" then
        for _, ap in ipairs(pp.activeProductions) do
            if ap.status == RUN then running = running + 1 end
        end
    end
    local enabled = active > 0
    local status  = (not enabled) and "Off" or (running > 0 and "Running" or "Idle")
    return { enabled = enabled, status = status, total = total, active = active, running = running }
end

-- turn the whole plant on/off (every line). Vanilla setProductionState broadcasts
-- its own MP event and persists, so we just drive it. [VERIFY MP]
function SmartDistribution.setProductionEnabled(p, on)
    local pp = getProductionPoint(p)
    if pp == nil or pp.setProductionState == nil or type(pp.productions) ~= "table" then return false end
    -- Only REAL lines: on a pass-through store this button must never switch the 110 identity lines back
    -- on, which would undo the suppression and put the scaffolding back in the player's face.
    for _, prod in ipairs(SmartDistribution.configuredProductionLines(pp)) do
        if prod.id ~= nil then pcall(function() pp:setProductionState(prod.id, on and true or false) end) end
    end
    return true
end

-- ---- per-line detail (for DistributionProductionDialog) --------------------
-- One descriptor per production LINE: name, on/off + run status, and each input /
-- output with its currently-held amount (shared plant storage) + per-month rate
-- (cyclesPerMonth x amount) + the output's 5-state mode label. Reads are guarded.
local function ftTitle(ft)
    if g_fillTypeManager ~= nil and g_fillTypeManager.getFillTypeByIndex ~= nil then
        local def = g_fillTypeManager:getFillTypeByIndex(ft)
        if def ~= nil and def.title ~= nil then return def.title end
    end
    return tostring(ft)
end

-- How many of this building's production LINES make `ft`, and how many of those are switched ON.
-- Returns (on, total), or nil when the building makes ft on no line at all (silo, pen, market).
--
-- ON means the player's enable toggle -- membership of `pp.activeProductions`, the same signal the
-- Productions tab's Toggle Line drives -- NOT whether the line is currently running. A line starved of
-- input is ON and idle; a line switched off is neither. That distinction is the point of the column: a
-- grain mill reading 1/4 for flour has three lines the player has turned off, which nothing else on the
-- Overview would show.
--
-- Deliberately NOT built on productionLines(), which computes held + capacity for every input and output
-- of every line. This runs per settings ROW, and 5.37 already flags that view's per-row cost as the thing
-- to watch on a large farm.
function SmartDistribution.outputLineCounts(p, ft)
    local pp = getProductionPoint(p)
    if pp == nil or ft == nil or type(pp.productions) ~= "table" then return nil end
    local activeSet = {}
    if type(pp.activeProductions) == "table" then
        for _, ap in ipairs(pp.activeProductions) do
            if ap.id ~= nil then activeSet[ap.id] = true end
        end
    end
    local total, on = 0, 0
    for _, prod in ipairs(SmartDistribution.configuredProductionLines(pp)) do
        local makes = false
        for _, o in ipairs(prod.outputs or {}) do
            if o.type == ft then makes = true; break end
        end
        if makes then
            total = total + 1
            if prod.id ~= nil and activeSet[prod.id] == true then on = on + 1 end
        end
    end
    if total == 0 then return nil end
    return on, total
end

function SmartDistribution.productionLines(p)
    local pp = getProductionPoint(p)
    if pp == nil or type(pp.productions) ~= "table" then return {} end
    local RUN = (ProductionPoint ~= nil and ProductionPoint.PROD_STATUS ~= nil and ProductionPoint.PROD_STATUS.RUNNING) or 1
    local activeSet, activeStatus = {}, {}
    if type(pp.activeProductions) == "table" then
        for _, ap in ipairs(pp.activeProductions) do
            if ap.id ~= nil then activeSet[ap.id] = true; activeStatus[ap.id] = ap.status end
        end
    end
    -- held / capacity include any silo extension folded onto this production's stations (greenhouse water
    -- tank). pp.storage answers for the buffer ALONE -- its getCapacity() is not extension-aware -- so the
    -- extension is added here, matching what inputProductCapacity / inputHeldLevel report elsewhere.
    local function held(ft)
        local total = 0
        local s = pp.storage
        if s ~= nil and s.getFillLevel ~= nil then
            local ok, lvl = pcall(s.getFillLevel, s, ft)
            if ok and type(lvl) == "number" then total = lvl end
        end
        for _, ext in ipairs(parentExtensionStorages(p)) do
            if storageFillTypes(ext)[ft] ~= nil then total = total + (getLevel(ext, ft) or 0) end
        end
        return total
    end
    local function cap(ft)
        local c = storageCapacity(pp.storage, ft)
        for _, ext in ipairs(parentExtensionStorages(p)) do
            if storageFillTypes(ext)[ft] ~= nil then
                local e = storageCapacity(ext, ft)
                if type(e) == "number" then c = (c or 0) + e end
            end
        end
        return c
    end
    local out = {}
    -- A pass-through store contributes only its GENUINE lines here, so the Productions tab shows the
    -- DriveIn's one silage line rather than 111 rows of scaffolding.
    for _, prod in ipairs(SmartDistribution.configuredProductionLines(pp)) do
        local id = prod.id
        local enabled = id ~= nil and activeSet[id] == true
        local st = enabled and (activeStatus[id] or prod.status) or nil
        -- TRANSLATED. These three were the one genuine miss the 2026-08-27 l10n audit turned up: phase 3
        -- localised the mode names and both link-status maps and never reached the production LINE
        -- status, so the Productions tab printed "Off" / "Running" / "Idle" in English in every language.
        -- Looked up per call, not at chunk load, because l10n may not be up when this file runs.
        local status
        if not enabled       then status = SmartDistribution.l10n("dr_lineStatus_off",     "Off")
        elseif st == RUN     then status = SmartDistribution.l10n("dr_lineStatus_running", "Running")
        else                      status = SmartDistribution.l10n("dr_lineStatus_idle",    "Idle") end
        local cpm = prod.cyclesPerMonth or (prod.cyclesPerHour ~= nil and prod.cyclesPerHour * 24) or 1440
        local cph = prod.cyclesPerHour
        if (cph == nil or cph == 0) and prod.cyclesPerMonth ~= nil then
            local env = g_currentMission ~= nil and g_currentMission.environment or nil
            local dpp = (env ~= nil and env.daysPerPeriod) or 1
            if dpp and dpp > 0 then cph = prod.cyclesPerMonth / (dpp * 24) end
        end
        cph = cph or 0
        local inputs = {}
        for _, i in ipairs(prod.inputs or {}) do
            inputs[#inputs + 1] = { ft = i.type, name = ftTitle(i.type), held = held(i.type), capacity = cap(i.type), amount = i.amount or 0, perMonth = (i.amount or 0) * cpm }
        end
        local outputs = {}
        for _, o in ipairs(prod.outputs or {}) do
            local vmode, vname
            if SmartDistribution.productionOutputVMode ~= nil then
                vmode = SmartDistribution.productionOutputVMode(pp, o.type)
                vname = SmartDistribution.productionOutputVModeName(vmode)
                -- Hold and Hold Internal both collapse to vanilla KEEP above, so name them from the DR mode.
                local drMode = SmartDistribution.resolvedAssetMode ~= nil and SmartDistribution.resolvedAssetMode(p, o.type) or nil
                -- holdLabelFlag, not the raw spawner list: with pallet spawning off this must read
                -- "Hold Internal", since the ring has dropped the separate Hold Internal option and this
                -- is the only hold left. Productions come through here rather than modeName.
                if drMode == MODE.HOLD_INTERNAL then vname = SmartDistribution.l10n("dr_mode_9", "Hold Internal")
                elseif drMode == MODE.HOLD then
                    local hf = SmartDistribution.holdLabelFlag(p, o.type)
                    if hf == "internal" then vname = SmartDistribution.l10n("dr_mode_9", "Hold Internal")
                    elseif hf then vname = SmartDistribution.l10n("dr_mode_holdPallets", "Hold Pallets") end
                end
            end
            outputs[#outputs + 1] = { ft = o.type, name = ftTitle(o.type), held = held(o.type), capacity = cap(o.type), amount = o.amount or 0,
                                      perMonth = (o.amount or 0) * cpm, perHour = (o.amount or 0) * cph, mode = vmode, modeName = vname, sellDirectly = o.sellDirectly }
        end
        local label = prod.name
        if (label == nil or label == "") and outputs[1] ~= nil then label = outputs[1].name end
        if label == nil or label == "" then label = "Line " .. tostring(#out + 1) end
        -- cyclesPerHour is exposed too: the Overview tab's "expected" figures scale by DR's own window
        -- lengths (a DR month is 24 hourly cycles), so they must come off a per-HOUR rate. cyclesPerMonth
        -- is the game's per-PERIOD count and would be wrong on a save with daysPerPeriod > 1.
        out[#out + 1] = { id = id, name = label, index = prod.index, enabled = enabled,
                          status = status, cyclesPerMonth = cpm, cyclesPerHour = cph,
                          inputs = inputs, outputs = outputs }
    end
    return out
end

-- toggle ONE production line on/off (vanilla owns persist + MP). [VERIFY MP]
function SmartDistribution.setProductionLineEnabled(p, id, on)
    local pp = getProductionPoint(p)
    if pp == nil or pp.setProductionState == nil or id == nil then return false end
    return pcall(function() pp:setProductionState(id, on and true or false) end)
end

-- cycle ONE line's output mode(s) through the shared 5-state seam (synced to the
-- production screen). Advances every output of the line together.
function SmartDistribution.cycleProductionLineOutput(p, id)
    local pp = getProductionPoint(p)
    if pp == nil or SmartDistribution.productionOutputVMode == nil then return false end
    local prod = (type(pp.productionsIdToObj) == "table") and pp.productionsIdToObj[id] or nil
    if prod == nil then return false end
    local outs = {}
    for _, o in ipairs(prod.outputs or {}) do outs[#outs + 1] = o.type end
    if #outs == 0 then return true end
    local modes = {}
    for i, ft in ipairs(outs) do modes[i] = SmartDistribution.productionOutputVMode(pp, ft) or 0 end
    local target = bulkCycleTarget(modes, modes[1], function(v) return (v + 1) % 6 end)
    for _, ft in ipairs(outs) do
        if SmartDistribution.setProductionOutputMode ~= nil then
            SmartDistribution.setProductionOutputMode(pp, ft, target)
        else
            SmartDistribution.cycleProductionOutputMode(pp, ft)   -- fallback if PDS set API missing
        end
    end
    return true
end

-- ---- asset dialog: held + last-cycle distributed/sold/stored ---------------
-- current held liters of ft across an asset's storages, plus shed (object
-- storage) and pallet-spawner (eggs/wool/honey) holdings. Guarded; never throws.
-- Eggs / wool / honey a pallet-spawner husbandry holds INTERNALLY but hasn't materialised as pallets: the
-- base game's per-fill-type pending queue (spec_husbandryPallets.pendingLiters[ft]; a scalar on a beehive
-- spawner). Normally near zero -- updatePallets drains it into pallets each tick -- but under Hold Internal
-- DR suppresses that spawn, so produced eggs pile up here instead. Counting it as held makes the amount
-- VISIBLE and growing (else the display sits on the frozen spawned-pallet total) and keeps the husbandry
-- produced-throughput stat correct. It is NOT a distributable source: gatherSources still pulls only real
-- spawned pallets (palletFillLevel), so nothing tries to drain this queue directly.
function SmartDistribution.palletPendingLiters(p, ft)
    if p == nil or ft == nil then return 0 end
    local hs = p.spec_husbandryPallets
    if hs ~= nil and type(hs.pendingLiters) == "table" then
        local v = hs.pendingLiters[ft]; if type(v) == "number" then return v end
    end
    local bs = p.spec_beehivePalletSpawner
    if bs ~= nil and bs.fillType == ft and type(bs.pendingLiters) == "number" then return bs.pendingLiters end
    return 0
end

function SmartDistribution.assetHeld(p, ft)
    if p == nil or ft == nil then return 0 end
    -- bunker silos own no Storage; their held product comes from the terrain heap, and only counts once
    -- the silo is uncovered (bunkerSilageLiters enforces that)
    if SmartDistribution.isBunkerSiloPlaceable(p) then
        -- OPEN bunker: the OUTPUT (silage / compost) is what the terrain heap holds, counted only when uncovered.
        if ft == SmartDistribution.bunkerOutputFillType(p) then return SmartDistribution.bunkerPlaceableSilage(p) end
        if ft == SmartDistribution.bunkerInputFillType(p) then return SmartDistribution.bunkerHeapLiters(p) end

        return 0
    end

    local total = 0
    local okS, storages = pcall(getAllStorages, p)
    if okS and type(storages) == "table" then
        for _, storage in ipairs(storages) do total = total + (getLevel(storage, ft) or 0) end
    end
    if p.spec_objectStorage ~= nil and shedStoredLiters ~= nil then
        local ok, v = pcall(shedStoredLiters, p, ft); if ok and type(v) == "number" then total = total + v end
    end
    if (p.spec_husbandryPallets ~= nil or p.spec_beehivePalletSpawner ~= nil) and palletFillLevel ~= nil then
        -- ALWAYS the full stock: internal buffer PLUS what stands on the pad, whatever the mode.
        --
        -- This used to switch basis on the mode -- pending only under Hold Internal, pallets otherwise --
        -- so the same coop read 473 under Hold and 3,473 under anything else, changing meaning as the
        -- player cycled the mode. The original reason for picking one was that counting both makes the
        -- total look FROZEN across a spawn (buffer drops, pallet rises, total unchanged). That is now
        -- handled where it belongs: the number is genuinely unchanged -- nothing was created or destroyed
        -- -- and the UI shows the two parts SEPARATELY ("473 L + 3,000 L (3p)"), so the player can see the
        -- stock move from buffer to pad without the total lying about how much there is.
        total = total + SmartDistribution.palletPendingLiters(p, ft)
        local ok, v = pcall(palletFillLevel, p, ft); if ok and type(v) == "number" then total = total + v end
    end
    return total
end

-- distributed / sold / stored liters for (asset, ft) in the last completed hourly
-- cycle (host-side; clients don't run the pass). Returns three numbers.
function SmartDistribution.lastCycleStats(p, ft)
    local lc = S.lastCycle
    if lc == nil or p == nil or ft == nil then return 0, 0, 0 end
    local a = lc[getUid(p)]
    local e = a ~= nil and a[ft] or nil
    if e == nil then return 0, 0, 0 end
    return e.dist or 0, e.sold or 0, e.stored or 0
end

-- liters RECEIVED from distribution for (asset, ft) in the last completed cycle
-- (recipient side -- e.g. liters that arrived into a production's input storage).
function SmartDistribution.lastCycleReceived(p, ft)
    local lc = S.lastCycle
    if lc == nil or p == nil or ft == nil then return 0 end
    local a = lc[getUid(p)]
    local e = a ~= nil and a[ft] or nil
    return e ~= nil and (e.received or 0) or 0
end

-- MONTHLY (rolling 24-cycle) distributed / sold / stored for (asset, ft): the same per-cycle
-- deltas as lastCycleStats, summed over the last MONTHLY_CYCLES completed cycles. Persisted.
function SmartDistribution.monthlyStats(p, ft)
    if p == nil or ft == nil then return 0, 0, 0, 0 end
    local uid = getUid(p)
    if clientMonthly ~= nil then                                  -- client: read the synced aggregate
        local au = clientMonthly[uid]; local e = au ~= nil and au[ft] or nil
        if e == nil then return 0, 0, 0, 0 end
        return e.dist or 0, e.sold or 0, e.stored or 0, e.money or 0
    end
    local d, s, st, mo = 0, 0, 0, 0
    for i = 1, MONTHLY_CYCLES do
        local snap = monthlyRing[i]
        local a = snap ~= nil and snap[uid] or nil
        local e = a ~= nil and a[ft] or nil
        if e ~= nil then d = d + (e.dist or 0); s = s + (e.sold or 0); st = st + (e.stored or 0); mo = mo + (e.money or 0) end
    end
    return d, s, st, mo
end

-- MONTHLY (rolling 24-cycle) received for (asset, ft); mirror of lastCycleReceived. Persisted.
function SmartDistribution.monthlyReceived(p, ft)
    if p == nil or ft == nil then return 0 end
    local uid = getUid(p)
    if clientMonthly ~= nil then                                  -- client: read the synced aggregate
        local au = clientMonthly[uid]; local e = au ~= nil and au[ft] or nil
        return e ~= nil and (e.received or 0) or 0
    end
    local r = 0
    for i = 1, MONTHLY_CYCLES do
        local snap = monthlyRing[i]
        local a = snap ~= nil and snap[uid] or nil
        local e = a ~= nil and a[ft] or nil
        if e ~= nil then r = r + (e.received or 0) end
    end
    if SmartDistribution._monthlyDebug then
        local parts = {}
        for i = 1, MONTHLY_CYCLES do
            local snap = monthlyRing[i]; local a = snap ~= nil and snap[uid] or nil; local e = a ~= nil and a[ft] or nil
            parts[#parts+1] = string.format("%d", (e ~= nil and (e.received or 0)) or 0)
        end
        SmartDistribution.log("monthlyRecv %s [%s] pos=%d sum=%d slots=[%s]", placeableName(p), fillTypeName(ft), monthlyPos, r, table.concat(parts, ","))
    end
    return r
end

-- Aggregate SOLD liters + money per fill type across ALL assets, for Production Redux.
-- window = "hour"  -> the last completed cycle (S.lastCycle)
--          "month" -> the rolling 24-cycle window (monthlyRing; clientMonthly on an MP client)
-- Returns { [fillTypeIndex] = { sold = <liters>, money = <currency> }, ... }. Server-authoritative
-- for "hour" (clients don't run the pass, so their lastCycle is empty); "month" also works on clients
-- via the synced clientMonthly aggregate. Read-only; never mutates the ring.
function SmartDistribution.salesByProduct(window)
    local out = {}
    local function add(ft, sold, money)
        if ft == nil then return end
        sold = sold or 0; money = money or 0
        if sold == 0 and money == 0 then return end
        local e = out[ft]
        if e == nil then e = { sold = 0, money = 0 }; out[ft] = e end
        e.sold  = e.sold  + sold
        e.money = e.money + money
    end
    local function scan(byUid)
        if type(byUid) ~= "table" then return end
        for _, byFt in pairs(byUid) do
            if type(byFt) == "table" then
                for ft, e in pairs(byFt) do
                    if type(e) == "table" then add(ft, e.sold, e.money) end
                end
            end
        end
    end

    if window == "hour" then
        scan(S.lastCycle)                                  -- last completed cycle (host-side)
    elseif clientMonthly ~= nil then
        scan(clientMonthly)                                -- MP client: synced monthly aggregate
    else
        for i = 1, MONTHLY_CYCLES do scan(monthlyRing[i]) end   -- server/SP: sum the 24-cycle ring
    end
    return out
end

-- Per-ASSET sold liters + money for Production Redux's expanded Product Sales view.
-- Like salesByProduct, but keeps the placeable dimension so the UI can show one row
-- per selling asset. Each uid is resolved to its placeable for a display name + shop
-- image. window = "hour" (last cycle) | "month" (24-cycle window / client aggregate).
-- Returns an ARRAY: { { ft=, uid=, assetName=, assetIcon=, sold=, money= }, ... }.
function SmartDistribution.salesByAsset(window)
    local byUid = {}
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps ~= nil and ps.placeables ~= nil then
        for _, p in ipairs(ps.placeables) do
            if p ~= nil and p.rootNode ~= nil then byUid[getUid(p)] = p end
        end
    end

    local function storeItemOf(p)
        if p == nil then return nil end
        if type(p.storeItem) == "table" then return p.storeItem end
        if p.configFileName ~= nil and g_storeManager ~= nil and g_storeManager.getItemByXMLFilename ~= nil then
            local ok, item = pcall(g_storeManager.getItemByXMLFilename, g_storeManager, p.configFileName)
            if ok and type(item) == "table" then return item end
        end
        return nil
    end
    local function assetName(p)
        if p ~= nil and p.getName ~= nil then
            local ok, n = pcall(p.getName, p)
            if ok and type(n) == "string" and n ~= "" then return n end
        end
        local si = storeItemOf(p)
        if si ~= nil and type(si.name) == "string" and si.name ~= "" then return si.name end
        return "Unknown asset"
    end
    -- The third copy of this question; delegated for the same reason as setAssetIcon.
    -- It gains the placeholder rejection and the product fallback, so a notification
    -- naming one of these buildings shows an icon rather than a blank.
    local function assetIcon(p)
        return SmartDistribution.assetIconFile(p)
    end

    local out = {}
    local function emit(uid, byFt)
        if type(byFt) ~= "table" then return end
        -- ledger keys may name a secondary ROLE once roles route product; resolve to the building
        local p = byUid[SmartDistribution.baseUidOf(uid)]
        local name, icon
        for ft, e in pairs(byFt) do
            if type(e) == "table" then
                local sold, money = e.sold or 0, e.money or 0
                if sold ~= 0 or money ~= 0 then
                    if name == nil then name = assetName(p); icon = assetIcon(p) end
                    out[#out + 1] = { ft = ft, uid = uid, assetName = name, assetIcon = icon, sold = sold, money = money }
                end
            end
        end
    end

    if window == "hour" then
        if type(S.lastCycle) == "table" then
            for uid, byFt in pairs(S.lastCycle) do emit(uid, byFt) end
        end
    elseif clientMonthly ~= nil then
        for uid, byFt in pairs(clientMonthly) do emit(uid, byFt) end
    else
        local acc = {}   -- uid -> ft -> {sold, money}
        for i = 1, MONTHLY_CYCLES do
            local snap = monthlyRing[i]
            if type(snap) == "table" then
                for uid, byFt in pairs(snap) do
                    if type(byFt) == "table" then
                        local au = acc[uid]; if au == nil then au = {}; acc[uid] = au end
                        for ft, e in pairs(byFt) do
                            if type(e) == "table" then
                                local ae = au[ft]; if ae == nil then ae = { sold = 0, money = 0 }; au[ft] = ae end
                                ae.sold = ae.sold + (e.sold or 0)
                                ae.money = ae.money + (e.money or 0)
                            end
                        end
                    end
                end
            end
        end
        for uid, byFt in pairs(acc) do emit(uid, byFt) end
    end
    return out
end

-- Record a per-cycle stat for a move/sale that happens OUTSIDE the main pass -- e.g. the
-- ProductionDistributeSell add-on's appended surplus-sell, which runs right after runHourly has
-- already published (cycleAcc niled). Writes into the live cycle if one is open, else into the
-- just-published cycle (S.lastCycle) -- the same table the monthly ring's newest slot references --
-- so the sale shows in BOTH the per-cycle and monthly columns. field = "dist"/"sold"/"stored"/"received".
function SmartDistribution.recordCycleStat(placeable, ft, field, amount)
    if placeable == nil or ft == nil or amount == nil or amount <= 0 then return end
    local tbl = cycleAcc or S.lastCycle
    if tbl == nil then return end
    local uid = getUid(placeable)
    if uid == nil then return end
    local a = tbl[uid]; if a == nil then a = {}; tbl[uid] = a end
    local e = a[ft];    if e == nil then e = { dist = 0, sold = 0, stored = 0, received = 0 }; a[ft] = e end
    e[field] = (e[field] or 0) + amount
end

-- ============================================================================
-- MULTIPLAYER: monthly /mo stats sync (server -> clients)
-- The hourly distribute/sell/store pass runs only on the server, so the monthly ring -- and thus
-- monthlyStats / monthlyReceived -- is empty on clients, leaving every /mo column blank for non-host
-- players. Each hour (and once for a joining client) the server flattens the 24-cycle ring to a
-- per-(placeable,fillType) aggregate and pushes it; the client stores it in clientMonthly, which the
-- two accessors above read. Sent in chunks; the first chunk of a push clears the client's table so
-- fill types that aged out of the 24-cycle window correctly fall back to zero.
-- ============================================================================
local STATS_MAX_PER_EVENT = 60     -- entries per event; keeps each network stream comfortably small

-- flatten one WINDOW's ledger to a list of { p = placeable, ft, d, s, st, r } with any non-zero total
-- (server side). window = "month" (the 24-cycle ring, the original behaviour and the only one that also
-- carries market buffers) | "hour" (last completed cycle) | "year" (the 12-month ring). The Overview tab
-- offers all three timescales, and a client runs no pass at all, so each is pushed separately.
local function buildMonthlyAggList(window)
    local agg = {}
    for _, led in ipairs(SmartDistribution.windowLedgers(window or "month")) do
        for uid, fts in pairs(led) do
            local au = agg[uid]; if au == nil then au = {}; agg[uid] = au end
            for ft, e in pairs(fts) do
                if type(e) == "table" then
                    local ae = au[ft]
                    if ae == nil then ae = { d = 0, s = 0, st = 0, r = 0, mo = 0, pr = 0, co = 0, lo = 0, ul = 0, ct = 0 }; au[ft] = ae end
                    ae.d  = ae.d  + (e.dist or 0);   ae.s = ae.s + (e.sold or 0)
                    ae.st = ae.st + (e.stored or 0); ae.r = ae.r + (e.received or 0)
                    ae.mo = ae.mo + (e.money or 0)
                    ae.pr = ae.pr + (e.produced or 0); ae.co = ae.co + (e.consumed or 0)
                    ae.lo = ae.lo + (e.loaded or 0);   ae.ul = ae.ul + (e.unloaded or 0)
                    ae.ct = ae.ct + (e.cost or 0)
                end
            end
        end
    end
    local withBuffers = (window == nil or window == "month")   -- market buffers ride with the monthly push only
    local list = {}
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps ~= nil then
        for _, p in ipairs(ps.placeables) do
            local uid = getUid(p)
            if uid ~= nil then
                local au = agg[uid]
                local isMkt = SmartDistribution.isMarket(p) and withBuffers
                if au ~= nil then
                    for ft, ae in pairs(au) do
                        local buf = isMkt and SmartDistribution.marketBufferLevel(uid, ft) or 0
                        if (ae.d + ae.s + ae.st + ae.r + ae.mo + ae.pr + ae.co + ae.lo + ae.ul + ae.ct) > 0 or buf > 0 then
                            list[#list + 1] = { p = p, ft = ft, d = ae.d, s = ae.s, st = ae.st, r = ae.r, mo = ae.mo,
                                                buf = buf, pr = ae.pr, co = ae.co, lo = ae.lo, ul = ae.ul, ct = ae.ct }
                        end
                    end
                end
                if isMkt then   -- markets with buffer but no monthly activity: still send so the tab shows live buffer
                    local b = SmartDistribution._marketBuffer[uid]
                    if b ~= nil then
                        for ft, litres in pairs(b) do
                            if litres ~= nil and litres > 0 and (au == nil or au[ft] == nil) then
                                list[#list + 1] = { p = p, ft = ft, d = 0, s = 0, st = 0, r = 0, mo = 0, buf = litres }
                            end
                        end
                    end
                end
            end
        end
    end
    return list
end

DistributionStatsEvent = {}
local DistributionStatsEvent_mt = Class(DistributionStatsEvent, Event)
InitEventClass(DistributionStatsEvent, "DistributionStatsEvent")   -- register network id (server + client)

function DistributionStatsEvent.emptyNew()
    return Event.new(DistributionStatsEvent_mt)
end
-- kind: which timescale the payload belongs to. 0 keeps the original monthly meaning, so an event from
-- an older peer that never wrote the field still lands in clientMonthly.
DistributionStatsEvent.KIND_MONTH = 0
DistributionStatsEvent.KIND_HOUR  = 1
DistributionStatsEvent.KIND_YEAR  = 2

function DistributionStatsEvent.new(entries, clearFirst, kind)
    local self = DistributionStatsEvent.emptyNew()
    self.entries    = entries or {}
    self.clearFirst = clearFirst and true or false
    self.kind       = kind or DistributionStatsEvent.KIND_MONTH
    return self
end
function DistributionStatsEvent:writeStream(streamId, connection)
    streamWriteBool(streamId, self.clearFirst)
    streamWriteUIntN(streamId, self.kind or 0, 2)                -- timescale: month / hour / year
    streamWriteUIntN(streamId, #self.entries, 8)                 -- <=255 per event; chunked well under
    for _, en in ipairs(self.entries) do
        NetworkUtil.writeNodeObject(streamId, en.p)
        streamWriteUIntN(streamId, en.ft, FillTypeManager.SEND_NUM_BITS)
        streamWriteFloat32(streamId, en.d)
        streamWriteFloat32(streamId, en.s)
        streamWriteFloat32(streamId, en.st)
        streamWriteFloat32(streamId, en.r)
        streamWriteFloat32(streamId, en.mo or 0)
        streamWriteFloat32(streamId, en.buf or 0)
        streamWriteFloat32(streamId, en.pr or 0)
        streamWriteFloat32(streamId, en.co or 0)
        streamWriteFloat32(streamId, en.lo or 0)
        streamWriteFloat32(streamId, en.ul or 0)
        streamWriteFloat32(streamId, en.ct or 0)
    end
end
function DistributionStatsEvent:readStream(streamId, connection)
    self.clearFirst = streamReadBool(streamId)
    self.kind = streamReadUIntN(streamId, 2)
    local n = streamReadUIntN(streamId, 8)
    self.entries = {}
    for i = 1, n do
        local p  = NetworkUtil.readNodeObject(streamId)
        local ft = streamReadUIntN(streamId, FillTypeManager.SEND_NUM_BITS)
        local d  = streamReadFloat32(streamId)
        local s  = streamReadFloat32(streamId)
        local st = streamReadFloat32(streamId)
        local r  = streamReadFloat32(streamId)
        local mo = streamReadFloat32(streamId)
        local bf = streamReadFloat32(streamId)
        local pr = streamReadFloat32(streamId)
        local co = streamReadFloat32(streamId)
        local lo = streamReadFloat32(streamId)
        local ul = streamReadFloat32(streamId)
        local ct = streamReadFloat32(streamId)
        self.entries[i] = { p = p, ft = ft, d = d, s = s, st = st, r = r, mo = mo, buf = bf, pr = pr, co = co, lo = lo, ul = ul, ct = ct }
    end
    self:run(connection)
end
function DistributionStatsEvent:run(connection)
    -- stats flow server -> client only; never relayed onward.
    local kind = self.kind or DistributionStatsEvent.KIND_MONTH
    local tbl
    if kind == DistributionStatsEvent.KIND_HOUR then
        if self.clearFirst or SmartDistribution._clientHour == nil then SmartDistribution._clientHour = {} end
        tbl = SmartDistribution._clientHour
    elseif kind == DistributionStatsEvent.KIND_YEAR then
        if self.clearFirst or SmartDistribution._clientYear == nil then SmartDistribution._clientYear = {} end
        tbl = SmartDistribution._clientYear
    else
        -- clientMonthly ~= nil is the "this peer is a client" flag the whole file keys off, so the monthly
        -- push must stay the one that creates it.
        if self.clearFirst or clientMonthly == nil then clientMonthly = {}; SmartDistribution._marketBuffer = {} end
        tbl = clientMonthly
    end
    for _, en in ipairs(self.entries) do
        local p = en.p
        if p ~= nil then
            local uid = getUid(p)
            if uid ~= nil then
                local au = tbl[uid]; if au == nil then au = {}; tbl[uid] = au end
                au[en.ft] = { dist = en.d, sold = en.s, stored = en.st, received = en.r, money = en.mo or 0,
                              produced = en.pr or 0, consumed = en.co or 0, loaded = en.lo or 0, unloaded = en.ul or 0,
                              cost = en.ct or 0 }
                if (en.buf or 0) > 0 then   -- client-side market buffer for the Markets tab (monthly push only)
                    local b = SmartDistribution._marketBuffer[uid]; if b == nil then b = {}; SmartDistribution._marketBuffer[uid] = b end
                    b[en.ft] = en.buf
                end
            end
        end
    end
end

-- server: push the whole rolling aggregate. targetConnection set -> only that joining client;
-- nil -> broadcast to everyone. No-op in single-player (the host reads the ring directly).
-- One pass per timescale: the Overview tab can show hour / month / year, and a client runs no hourly
-- pass, so none of the three exist client-side unless they are pushed. Month goes FIRST because its
-- arrival is what marks the peer as a client.
function DistributionStatsEvent.broadcast(targetConnection)
    if g_currentMission == nil or not g_currentMission:getIsServer() then return end
    local dyn = g_currentMission.missionDynamicInfo
    if dyn == nil or dyn.isMultiplayer ~= true or g_server == nil then return end
    local windows = {
        { "month", DistributionStatsEvent.KIND_MONTH },
        { "hour",  DistributionStatsEvent.KIND_HOUR  },
        { "year",  DistributionStatsEvent.KIND_YEAR  },
    }
    for _, w in ipairs(windows) do
        local list = buildMonthlyAggList(w[1])
        local i, total, first = 1, #list, true
        repeat
            local slice = {}
            while #slice < STATS_MAX_PER_EVENT and i <= total do
                slice[#slice + 1] = list[i]; i = i + 1
            end
            local ev = DistributionStatsEvent.new(slice, first, w[2])
            if targetConnection ~= nil then targetConnection:sendEvent(ev) else g_server:broadcastEvent(ev) end
            first = false
        until i > total
    end
end

-- ============================================================================
-- MULTIPLAYER: the per-LINK feed log (server -> clients)
--
-- DistributionStatsEvent carries per-(uid, ft) FLOWS, which is what the Overview's columns need. It
-- cannot answer "WHICH source fed this consumer", because that is a per-(consumer, ft, source) fact and
-- has never left the server. So on a client fedBy() returned 0 for everything: "Active (Receiving)" and
-- "Sending" fell back to the window totals and mostly still looked right, but the 5.77 source drill-down
-- could never show FEEDING and its count read 0/N on every row. Found while adding save/restore of the
-- last cycle 2026-08-27; the gap itself shipped with 5.76.
--
-- SHAPE MIRRORS DistributionStatsEvent deliberately: chunked at STATS_MAX_PER_EVENT with a clearFirst
-- flag on the first chunk, and it sends PLACEABLES via writeNodeObject rather than uid strings -- so the
-- client resolves identity through its own getUid, which carries the client-side remap that 5.49 / 5.50
-- exist for. Sending the server's uid string would reintroduce exactly that bug.
--
-- The SOURCE side is accumulated on arrival rather than sent, the same reason the savegame omits it:
-- recordFeed derives both from one call, so a second copy on the wire could only drift.
-- ============================================================================
DistributionFeedEvent = {}
-- A FIELD, not `local DistributionFeedEvent_mt` -- the main chunk is at Lua's 200-local ceiling
-- (CLAUDE.md 1.1) and one more top-level local does not compile. Class() returns the metatable either
-- way, so this is the same object under a different name.
DistributionFeedEvent._mt = Class(DistributionFeedEvent, Event)
InitEventClass(DistributionFeedEvent, "DistributionFeedEvent")   -- register network id (server + client)

function DistributionFeedEvent.emptyNew()
    return Event.new(DistributionFeedEvent._mt)
end
function DistributionFeedEvent.new(entries, clearFirst)
    local self = DistributionFeedEvent.emptyNew()
    self.entries    = entries or {}
    self.clearFirst = clearFirst and true or false
    return self
end
function DistributionFeedEvent:writeStream(streamId, connection)
    streamWriteBool(streamId, self.clearFirst)
    streamWriteUIntN(streamId, #self.entries, 8)                 -- <=255 per event; chunked well under
    for _, en in ipairs(self.entries) do
        NetworkUtil.writeNodeObject(streamId, en.c)              -- consumer
        NetworkUtil.writeNodeObject(streamId, en.s)              -- source
        streamWriteUIntN(streamId, en.ft, FillTypeManager.SEND_NUM_BITS)
        streamWriteFloat32(streamId, en.l)
    end
end
function DistributionFeedEvent:readStream(streamId, connection)
    self.clearFirst = streamReadBool(streamId)
    local n = streamReadUIntN(streamId, 8)
    self.entries = {}
    for i = 1, n do
        local c  = NetworkUtil.readNodeObject(streamId)
        local s  = NetworkUtil.readNodeObject(streamId)
        local ft = streamReadUIntN(streamId, FillTypeManager.SEND_NUM_BITS)
        local l  = streamReadFloat32(streamId)
        self.entries[i] = { c = c, s = s, ft = ft, l = l }
    end
    self:run(connection)
end
function DistributionFeedEvent:run(connection)
    -- server -> client only; never relayed onward
    if self.clearFirst or SmartDistribution._clientFeed == nil then
        SmartDistribution._clientFeed   = {}
        SmartDistribution._clientFedOut = {}
    end
    local feed, fedOut = SmartDistribution._clientFeed, SmartDistribution._clientFedOut
    for _, en in ipairs(self.entries) do
        if en.c ~= nil and en.s ~= nil then
            local cu, su = getUid(en.c), getUid(en.s)
            if cu ~= nil and su ~= nil then
                local a = feed[cu];  if a == nil then a = {}; feed[cu] = a end
                local t = a[en.ft];  if t == nil then t = {}; a[en.ft] = t end
                t[su] = (t[su] or 0) + en.l
                local o = fedOut[su]; if o == nil then o = {}; fedOut[su] = o end
                o[en.ft] = (o[en.ft] or 0) + en.l
            end
        end
    end
end

-- server: push the last completed pass's link log. targetConnection set -> only that joining client;
-- nil -> broadcast to everyone. No-op in single-player, where the host reads _feedPrev directly.
--
-- _feedPrev holds UIDS, and the wire wants PLACEABLES, so the map is built from ONE placeableSystem walk
-- per broadcast rather than resolving each entry through placeableByUid -- which is itself a full scan,
-- and would make this O(links x placeables). It also has to be a walk rather than a table kept by
-- recordFeed, because after a savegame restore _feedPrev is repopulated from uids alone with no
-- placeables anywhere. A uid that no longer resolves (the building was demolished) is simply skipped.
function DistributionFeedEvent.broadcast(targetConnection)
    if g_currentMission == nil or not g_currentMission:getIsServer() then return end
    local dyn = g_currentMission.missionDynamicInfo
    if dyn == nil or dyn.isMultiplayer ~= true or g_server == nil then return end
    local byUid = {}
    local ps = g_currentMission.placeableSystem
    if ps ~= nil then
        for _, p in ipairs(ps.placeables) do
            if p.rootNode ~= nil then
                local u = getUid(p)
                if u ~= nil then byUid[u] = p end
            end
        end
    end
    local list = {}
    for cu, byFt in pairs(SmartDistribution._feedPrev or {}) do
        local cp = byUid[cu]
        if cp ~= nil then
            for ft, bySrc in pairs(byFt) do
                for su, litres in pairs(bySrc) do
                    local sp = byUid[su]
                    if sp ~= nil and type(litres) == "number" and litres > 0 then
                        list[#list + 1] = { c = cp, s = sp, ft = ft, l = litres }
                    end
                end
            end
        end
    end
    -- ALWAYS SEND AT LEAST ONE EVENT, even with an empty list: clearFirst is what tells the client to
    -- drop last hour's links, and a cycle in which nothing moved is exactly when they must go.
    local i, total, first = 1, #list, true
    repeat
        local slice = {}
        while #slice < STATS_MAX_PER_EVENT and i <= total do
            slice[#slice + 1] = list[i]; i = i + 1
        end
        local ev = DistributionFeedEvent.new(slice, first)
        if targetConnection ~= nil then targetConnection:sendEvent(ev) else g_server:broadcastEvent(ev) end
        first = false
    until i > total
end

-- ============================================================================
-- MULTIPLAYER: per-cycle money summary mirror (server -> clients)
-- flushCycleSummary emits the "Biogas income / Product sales / Distribution costs" side-notifications
-- on the server (which runs the pass). This event carries the same three category totals to clients
-- so non-host players see the identical summary; each client formats with its own locale and notifies.
-- ============================================================================
DistributionMoneyNotifyEvent = {}
local DistributionMoneyNotifyEvent_mt = Class(DistributionMoneyNotifyEvent, Event)
InitEventClass(DistributionMoneyNotifyEvent, "DistributionMoneyNotifyEvent")   -- register network id (server + client)

function DistributionMoneyNotifyEvent.emptyNew()
    return Event.new(DistributionMoneyNotifyEvent_mt)
end
function DistributionMoneyNotifyEvent.new(biogas, sales, cost)
    local self = DistributionMoneyNotifyEvent.emptyNew()
    self.biogas = biogas or 0
    self.sales  = sales  or 0
    self.cost   = cost   or 0
    return self
end
function DistributionMoneyNotifyEvent:writeStream(streamId, connection)
    streamWriteFloat32(streamId, self.biogas)
    streamWriteFloat32(streamId, self.sales)
    streamWriteFloat32(streamId, self.cost)
end
function DistributionMoneyNotifyEvent:readStream(streamId, connection)
    self.biogas = streamReadFloat32(streamId)
    self.sales  = streamReadFloat32(streamId)
    self.cost   = streamReadFloat32(streamId)
    self:run(connection)
end
function DistributionMoneyNotifyEvent:run(connection)
    -- client display only; never relayed onward. Mirrors flushCycleSummary's notifications.
    if self.biogas ~= 0 then SmartDistribution.notify("Biogas income: "     .. fmtMoney(self.biogas)) end
    if self.sales  ~= 0 then SmartDistribution.notify("Product sales: "     .. fmtMoney(self.sales))  end
    if self.cost   ~= 0 then SmartDistribution.notify("Distribution costs: -" .. fmtMoney(math.abs(self.cost)), SmartDistribution.COST_NOTIFY_COLOUR) end
end
-- server: mirror the just-emitted summary to all clients. No-op in single-player.
function DistributionMoneyNotifyEvent.broadcast(biogas, sales, cost)
    if g_currentMission == nil or not g_currentMission:getIsServer() then return end
    local dyn = g_currentMission.missionDynamicInfo
    if dyn == nil or dyn.isMultiplayer ~= true or g_server == nil then return end
    if (biogas or 0) == 0 and (sales or 0) == 0 and (cost or 0) == 0 then return end
    g_server:broadcastEvent(DistributionMoneyNotifyEvent.new(biogas, sales, cost))
end

-- cycle ONE production output's distribution mode (per fill type) through the shared
-- 5-state seam. Backs the Productions page's per-output "Cycle Output" action.
function SmartDistribution.cycleProductionOutput(p, ft)
    local pp = getProductionPoint(p)
    if pp == nil or ft == nil or SmartDistribution.cycleProductionOutputMode == nil then return false end
    return SmartDistribution.cycleProductionOutputMode(pp, ft)
end

-- ...and one step the other way, for the in-row left arrow on the Productions tab.
function SmartDistribution.cycleProductionOutputBack(p, ft)
    local pp = getProductionPoint(p)
    if pp == nil or ft == nil or SmartDistribution.cycleProductionOutputModeBack == nil then return false end
    return SmartDistribution.cycleProductionOutputModeBack(pp, ft)
end

-- ============================================================================
-- SEASONAL HARVEST RESERVE -- primitives (calendar + crop test + demand)
-- Foundation for holding a year's feedstock back from Distribute+Sell. Nothing
-- here changes behaviour yet; it's the data layer the reserve will use.
-- Confirmed in-game (sdSeasonProbe): environment.currentPeriod is the 1..12 month;
-- growthSystem.growthEnabled flags seasonal growth; g_fruitTypeManager resolves via
-- direct global access (rawget does not see engine globals).
-- ============================================================================

-- current in-game month, 1..12 (FS calls it "period"); nil if unavailable
function SmartDistribution.currentMonth()
    local e = g_currentMission ~= nil and g_currentMission.environment or nil
    return e ~= nil and e.currentPeriod or nil
end

-- whether seasonal crop growth is on; if off there are no harvest windows
function SmartDistribution.growthEnabled()
    local g = g_currentMission ~= nil and g_currentMission.growthSystem or nil
    if g == nil or g.growthEnabled == nil then return true end
    return g.growthEnabled == true
end

-- forward distance in months from `from` to `to` (1..12, wrapping; same month -> 12)
local function monthsForward(from, to)
    if from == nil or to == nil then return nil end
    local d = (to - from) % 12
    return d == 0 and 12 or d
end

-- the smallest circular window covering recorded harvest months -> earliest month
-- of that window and its span in months (0 for a single-month window).
local function harvestWindow(months)
    local ms = {}
    for _, m in ipairs(months) do if type(m) == "number" then ms[#ms + 1] = m end end
    if #ms == 0 then return nil, nil end
    table.sort(ms)
    if #ms == 1 then return ms[1], 0 end
    local largestGap, gapIdx = -1, 1
    for i = 1, #ms do
        local gap = (ms[(i % #ms) + 1] - ms[i]) % 12
        if gap == 0 then gap = 12 end
        if gap > largestGap then largestGap = gap; gapIdx = i end
    end
    return ms[(gapIdx % #ms) + 1], 12 - largestGap   -- month after the largest gap; span
end

-- months of demand to cover before the crop is reliably replenished. Worst case:
-- the player harvested at the EARLIEST window month, then waits until the LATEST
-- window month the NEXT time round -- so cover = (now -> earliest) + window span.
-- A 2-month window peaks at 13 just after an early harvest. nil if no data.
function SmartDistribution.monthsToCover(harvestMonths)
    local now = SmartDistribution.currentMonth()
    if now == nil or type(harvestMonths) ~= "table" then return nil end
    local earliest, span = harvestWindow(harvestMonths)
    if earliest == nil then return nil end
    return monthsForward(now, earliest) + span
end

-- is this fill type a harvested crop? (has a fruitType). Direct global on purpose.
function SmartDistribution.isCropFillType(ft)
    if ft == nil then return false end
    local ftm = g_fruitTypeManager
    if ftm == nil or ftm.getFruitTypeIndexByFillTypeIndex == nil then return false end
    local ok, idx = pcall(ftm.getFruitTypeIndexByFillTypeIndex, ftm, ft)
    return ok and idx ~= nil and idx ~= 0
end

-- Perennial / multi-cut forage (grass and similar): regrows and is harvested several times a
-- year, so it needs far less seasonal reserve than an annual crop. Base game marks grass with
-- foliageState regrowthStart="true"; that flag isn't reliably exposed at runtime, so we match
-- the fruit's NAME against a forage keyword set (covers base GRASS plus common mod forages such
-- as alfalfa / clover / meadow / ryegrass). Annual grains, roots and oilseeds return false.
SmartDistribution.REGROW_CROP_KEYWORDS = { "GRASS", "MEADOW", "ALFALFA", "LUCERNE", "LUZERNE", "CLOVER", "RYEGRASS", "HERBAL" }
function SmartDistribution.isRegrowCrop(ft)
    if ft == nil then return false end
    local ftm = g_fruitTypeManager
    if ftm == nil or ftm.getFruitTypeIndexByFillTypeIndex == nil then return false end
    local ok, idx = pcall(ftm.getFruitTypeIndexByFillTypeIndex, ftm, ft)
    if not ok or idx == nil or idx == 0 then return false end
    local ftype = ftm.getFruitTypeByIndex ~= nil and ftm:getFruitTypeByIndex(idx) or nil
    local name = ftype ~= nil and ftype.name or nil
    if type(name) ~= "string" then return false end
    name = string.upper(name)
    for _, kw in ipairs(SmartDistribution.REGROW_CROP_KEYWORDS) do
        if string.find(name, kw, 1, true) ~= nil then return true end
    end
    return false
end

-- Reserve horizon (months of feedstock to hold) for a crop in the seasonal reserve. Regrowing
-- forage regrows every few months, so it holds only GRASS_RESERVE_MONTHS; annual crops use the
-- learned single-season harvest-window cover (monthsToCover), else the configured fallback.
SmartDistribution.GRASS_RESERVE_MONTHS = 3
function SmartDistribution.cropReserveMonths(ft)
    if SmartDistribution.isRegrowCrop(ft) then return SmartDistribution.GRASS_RESERVE_MONTHS end
    local fallback = S.global.seasonalFallbackMonths or 13
    return SmartDistribution.monthsToCover(S.harvestMonths and S.harvestMonths[ft]) or fallback
end

-- Monthly feed demand a single husbandry places on a specific crop fill type, for the
-- seasonal reserve.
--   * Feeding-robot barns take each ingredient into its own BUNKER, so a crop ingredient's
--     demand is simply the herd's food rate x that ingredient's recipe ratio (e.g. grass in
--     a TMR mix) -- no group attribution needed.
--   * Shared food-pool barns (chicken / pig / etc.) eat a food GROUP of interchangeable crops
--     at ONE aggregate rate with no per-crop split, so we attribute that rate only to the crops
--     the pen is actually eating -- weighted by recent per-ft consumption, or (no history yet)
--     by what's currently loaded in the food pool. A feed crop the animals aren't touching gets
--     weight 0 and stays fully sellable.
-- Returns 0 for pens that don't eat ft and for water.
function SmartDistribution.husbandryFeedDemand(p, ft)
    if p == nil or ft == nil or not isHusbandryBuilding(p) then return 0 end
    if ft == waterFillType() then return 0 end
    local env = g_currentMission ~= nil and g_currentMission.environment or nil
    local hpm = 24 * ((env ~= nil and env.daysPerPeriod) or 1)   -- hours per economic month (period)

    -- feeding-robot barns: one bunker per ingredient. Demand for a crop ingredient is the herd's
    -- food rate x this ingredient's mixer-recipe ratio. Non-bunker / non-recipe fts demand nothing.
    if SmartDistribution.feedingRobotOf(p) ~= nil then
        if not SmartDistribution.robotBunkerFillTypes(p)[ft] then return 0 end
        local rfs = p.spec_husbandryFood
        local rrate = rfs ~= nil and SmartDistribution.husbandryInputRate(p, rfs.litersPerHour, "food") or 0
        if rrate <= 0 then return 0 end
        local ings = SmartDistribution.robotRecipeIngredients(p)
        if ings == nil then return 0 end
        for _, ing in ipairs(ings) do
            if type(ing.fillTypes) == "table" then
                for _, ift in pairs(ing.fillTypes) do
                    if ift == ft and type(ing.ratio) == "number" then return rrate * ing.ratio * hpm end
                end
            end
        end
        return 0
    end

    -- shared food-pool husbandry
    local fs = p.spec_husbandryFood
    if fs == nil or fs.supportedFillTypes == nil or not fs.supportedFillTypes[ft] then return 0 end
    local rate = SmartDistribution.husbandryInputRate(p, fs.litersPerHour, "food")
    if not rate or rate <= 0 then return 0 end
    local monthly = rate * hpm
    if monthly <= 0 then return 0 end
    -- attribution weight: share of the food rate to charge to ft. primary = recent per-ft
    -- consumption (what it's really eating); fallback = current per-ft holdings in the pool.
    local ftShare, total = 0, 0
    for f in pairs(fs.supportedFillTypes) do
        if f ~= waterFillType() then
            local c = SmartDistribution.monthlyConsumed(p, f) or 0
            total = total + c
            if f == ft then ftShare = c end
        end
    end
    if total <= 0 then
        ftShare, total = 0, 0
        if fs.fillLevels ~= nil then
            for f, lvl in pairs(fs.fillLevels) do
                if f ~= waterFillType() then
                    total = total + (lvl or 0)
                    if f == ft then ftShare = (lvl or 0) end
                end
            end
        end
    end
    if total <= 0 then return 0 end     -- can't tell what it eats -> reserve nothing (don't freeze cash crops)
    return monthly * (ftShare / total)
end

-- total monthly INPUT demand for a fill type across all ACTIVE production lines
-- (cyclesPerMonth x input amount, summed) PLUS husbandry feed demand for the crops each
-- pen is actually eating (husbandryFeedDemand). Used by the seasonal harvest reserve.
function SmartDistribution.monthlyDemand(ft)
    if ft == nil then return 0 end
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil or type(ps.placeables) ~= "table" then return 0 end
    local total = 0
    for _, p in ipairs(ps.placeables) do
        local pp = getProductionPoint(p)
        if pp ~= nil and type(pp.activeProductions) == "table" then
            for _, prod in ipairs(pp.activeProductions) do
                local cpm = prod.cyclesPerMonth or (prod.cyclesPerHour ~= nil and prod.cyclesPerHour * 24) or 1440
                for _, i in ipairs(prod.inputs or {}) do
                    if i.type == ft then total = total + (i.amount or 0) * cpm end
                end
            end
        elseif pp == nil and isHusbandryBuilding(p) then
            total = total + SmartDistribution.husbandryFeedDemand(p, ft)
        end
    end
    return total
end

function SmartDistribution.cycleAssetMode(asset)
    if asset == nil then return end
    local fts, any = SmartDistribution.assetMenuFillTypes(asset)
    if not any then
        SmartDistribution.notify(placeableName(asset) .. ": no fill types to configure")
        return
    end
    -- stable order so the "unify to first" anchor is deterministic
    local order = {}
    for ft in pairs(fts) do order[#order + 1] = ft end
    table.sort(order)

    -- productions: bulk-cycle the outputs through the shared 5-state virtual mode
    -- (Keep/Distribute/Sell/Distribute+Sell/Distribute+Store), unify-then-step, so
    -- the distribution UI and the production screen stay in lockstep.
    -- ...but ONLY for products that actually run on the v-mode. On a pass-through store the Silos tab's
    -- list is the TANK's crops, which do not -- cycling those as v-modes wrote a mode nothing reads.
    -- The list is homogeneous by construction (the tabs partition products by role, 5.65), so testing it
    -- is enough; a mixed list falls through to the asset path, which is the safe direction.
    local vCycles = getProductionPoint(asset) ~= nil and SmartDistribution.productionOutputVMode ~= nil
    if vCycles then
        for _, ft in ipairs(order) do
            if not SmartDistribution.usesVMode(asset, ft) then vCycles = false; break end
        end
    end
    if vCycles then
        local pp = getProductionPoint(asset)
        local modes = {}
        for i, ft in ipairs(order) do modes[i] = SmartDistribution.productionOutputVMode(pp, ft) or 0 end
        local target = bulkCycleTarget(modes, modes[1] or 0, function(v) return (v + 1) % 6 end)
        local names = {}
        for _, ft in ipairs(order) do
            if SmartDistribution.setProductionOutputMode ~= nil then
                SmartDistribution.setProductionOutputMode(pp, ft, target)
            else
                SmartDistribution.cycleProductionOutputMode(pp, ft)
            end
            names[#names + 1] = fillTypeName(ft)
        end
        local label = (SmartDistribution.productionOutputVModeName and SmartDistribution.productionOutputVModeName(target)) or tostring(target)
        log("%s", string.format("%s outputs -> %s  [%s]", placeableName(asset), label, table.concat(names, ", ")))
        return
    end

    -- everything else: unify-then-step the asset mode across all its fill types
    local store = assetCanStore(asset)
    local market = SmartDistribution.assetHasMarket(asset)
    local modes = {}
    for i, ft in ipairs(order) do modes[i] = SmartDistribution.resolvedAssetMode(asset, ft) end
    local target = bulkCycleTarget(modes, modes[1], function(m)
        return cycleNext(m, store, market, palletSpawnerFillTypes(asset) ~= nil and SmartDistribution.palletSpawnAllowed()) end)
    local names, skipped = {}, {}
    for _, ft in ipairs(order) do
        -- don't park a product on a mode it has no endpoint for (e.g. Market Supply for a product no
        -- market accepts): leave that one on its current mode instead.
        if SmartDistribution.modeHasEndpoint == nil or SmartDistribution.modeHasEndpoint(asset, ft, target) then
            SmartDistribution.applyAssetMode(asset, ft, target)   -- syncs MP + persists on save
            names[#names + 1] = fillTypeName(ft)
        else
            skipped[#skipped + 1] = fillTypeName(ft)
        end
    end
    log("%s", string.format("%s -> %s  [%s]%s",
        placeableName(asset), SmartDistribution.modeName(target), table.concat(names, ", "),
        #skipped > 0 and ("  (no endpoint, unchanged: " .. table.concat(skipped, ", ") .. ")") or ""))
end
-- back-compat alias
SmartDistribution.cycleSiloMode = SmartDistribution.cycleAssetMode

-- Targeting for the in-world keys. We measure to each asset's INTERACTION node
-- (where the player actually stands to use it) rather than its rootNode, which
-- on large buildings can sit far from the working area. Among in-range
-- candidates we additionally require the player to be LOOKING AT (gaze gate),
-- and among those that pass, prefer the nearest / most-centred one.
local CYCLE_MAX_DIST = 2    -- metres: in-world prompt + keys act on an owned asset within this range
local LOOK_AT_RADIUS = 6    -- metres: how far a load/unload node may sit from the player's gaze
                            -- line and still count as "looking at it". A perpendicular tolerance, so
                            -- it's forgiving at the node you're standing at and tightens with distance.

local function playerPos()
    local p = g_localPlayer
    if p == nil then return nil end
    if p.getPosition ~= nil then
        local ok, x, y, z = pcall(p.getPosition, p)
        if ok and x ~= nil then return x, y, z end
    end
    if p.rootNode ~= nil then return getWorldTranslation(p.rootNode) end
    return nil
end

-- normalised world XZ the player is facing (camera yaw node forward = +Z); nil
-- if unresolved, in which case selection falls back to pure distance.
local function playerForwardXZ()
    local pl = g_localPlayer
    if pl == nil or pl.camera == nil or pl.camera.yawNode == nil then return nil end
    local ok, fx, _, fz = pcall(localDirectionToWorld, pl.camera.yawNode, 0, 0, 1)
    if not ok or fx == nil then return nil end
    local len = math.sqrt(fx * fx + fz * fz)
    if len < 1e-4 then return nil end
    return fx / len, fz / len
end

-- All DISTRIBUTION interaction nodes for an asset: every loading + unloading
-- station trigger it has, so the player can open the menu from ANY input/output
-- point rather than one mystery spot. Deliberately EXCLUDES animal-management and
-- production-access nodes (those aren't load/unload points). Silos and husbandries
-- both carry loading/unloading stations; productions contribute nothing here.
-- Falls back to the silo player trigger, then the rootNode, if no station nodes.
local function triggerNodeOf(t)
    if t == nil then return nil end
    return t.triggerNode          -- LoadTrigger (output pickup point)
        or t.exactFillRootNode    -- UnloadTrigger (input fill point)
        or t.aiNode               -- UnloadTrigger AI node (last-resort position)
end

local function collectStationNodes(station, out)
    if station == nil then return end
    if type(station.loadTriggers) == "table" then
        for _, t in ipairs(station.loadTriggers) do
            local n = triggerNodeOf(t); if n ~= nil then out[#out + 1] = n end
        end
    end
    if type(station.unloadTriggers) == "table" then
        for _, t in ipairs(station.unloadTriggers) do
            local n = triggerNodeOf(t); if n ~= nil then out[#out + 1] = n end
        end
    end
end

local function assetInteractionNodes(p)
    local out = {}
    -- A PASS-THROUGH STORE'S TANK HANGS OFF ITS PRODUCTION POINT, not off a spec_silo, so none of the
    -- branches below found its tipping or loading triggers: reported in game as "the silo drop-off
    -- points have no icon and do nothing", while the pallet store beside them worked. Its stations are
    -- ordinary unloading/loading stations; they just live somewhere this function never looked.
    if SmartDistribution.treatPassThroughAsStore(p) then
        local pp = getProductionPoint(p)
        if pp ~= nil then
            collectStationNodes(pp.unloadingStation, out)
            collectStationNodes(pp.loadingStation, out)
        end
    end
    if p.spec_silo ~= nil then
        collectStationNodes(p.spec_silo.loadingStation, out)
        collectStationNodes(p.spec_silo.unloadingStation, out)
        if #out == 0 and p.spec_silo.playerActionTrigger ~= nil then
            out[#out + 1] = p.spec_silo.playerActionTrigger
        end
    end
    -- bulk hall: a placeable-level pair of stations plus one pair per bay
    local hall = SmartDistribution.bulkHallSpec(p)
    if hall ~= nil then
        collectStationNodes(hall.loadingStation, out)
        collectStationNodes(hall.unloadingStation, out)
        if type(hall.sections) == "table" then
            for _, sec in pairs(hall.sections) do
                if type(sec) == "table" then
                    collectStationNodes(sec.loadingStation, out)
                    collectStationNodes(sec.unloadingStation, out)
                end
            end
        end
    end
    if p.spec_husbandry ~= nil then
        collectStationNodes(p.spec_husbandry.loadingStation, out)
        collectStationNodes(p.spec_husbandry.unloadingStation, out)
    end
    -- Chicken coops / sheep pastures have no husbandry loading/unloading station --
    -- their output is pallets -- so the checks above find nothing and we'd fall back to
    -- the unreachable building rootNode (no in-world prompt). The food trough is the one
    -- interaction point every husbandry has and the player can physically stand at, so
    -- add it as a reachable node. (item 5 step a follow-up: gives coops/sheep a node.)
    if p.spec_husbandryFood ~= nil and type(p.spec_husbandryFood.feedingTroughs) == "table" then
        for _, t in ipairs(p.spec_husbandryFood.feedingTroughs) do
            local n = triggerNodeOf(t); if n ~= nil then out[#out + 1] = n end
        end
    end
    -- Pallet/bale storage sheds (object storage) have TWO interaction spots: the player
    -- (load/pickup) trigger and the object (unload/drop-off) trigger, often at different ends of
    -- the shed. Expose BOTH so the [ gaze prompt resolves whichever one you're standing at. (The
    -- old "#out == 0" guard hid the object trigger whenever a player trigger existed, leaving a
    -- shed reachable from only one of its two points -- looking at it from the other end did
    -- nothing, even though the shed's own load icon was showing.)
    if p.spec_objectStorage ~= nil then
        local oss = p.spec_objectStorage
        if oss.playerTriggerNode ~= nil then out[#out + 1] = oss.playerTriggerNode end
        if oss.objectTriggerNode ~= nil then out[#out + 1] = oss.objectTriggerNode end
    end
    -- Manure heap / extension: the loading station (where you back a trailer in) + the heap's own
    -- activation trigger are the reachable interaction nodes.
    if p.spec_manureHeap ~= nil then
        collectStationNodes(p.spec_manureHeap.loadingStation, out)
        local hs = p.spec_manureHeap.manureHeap
        if hs ~= nil and hs.activationTriggerNode ~= nil then out[#out + 1] = hs.activationTriggerNode end
    end
    -- Productions: the reachable interaction points are the input/output station triggers (where
    -- you back a trailer in to deliver/collect) plus the building's player trigger.  Without these,
    -- a production falls back to its building-centre rootNode -- out of the in-world key's reach --
    -- so the walk-up open-dialog key never fires on a production (manager access still works).
    local pp = getProductionPoint(p)
    if pp ~= nil then
        collectStationNodes(pp.loadingStation, out)
        collectStationNodes(pp.unloadingStation, out)
        if pp.playerTrigger ~= nil then out[#out + 1] = pp.playerTrigger end
        if pp.playerTriggerNode ~= nil then out[#out + 1] = pp.playerTriggerNode end
    end
    -- Markets / kiosks: the reachable interaction points are the selling station's load / unload
    -- trigger(s) -- where you drive a trailer in to sell. Lets the [ gaze prompt fire at any of them.
    if SmartDistribution.isMarket ~= nil and SmartDistribution.isMarket(p) then
        collectStationNodes(SmartDistribution.marketStationOf(p), out)
    end
    if #out == 0 and p.rootNode ~= nil then out[#out + 1] = p.rootNode end
    return out
end
SmartDistribution.assetInteractionNodes = assetInteractionNodes

local function findNearestOwned(matchFn)
    local px, _, pz = playerPos()
    if px == nil then log("cycle: no player position [VERIFY g_localPlayer]"); return nil end
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return nil end
    local farmId = (g_currentMission.getFarmId ~= nil) and g_currentMission:getFarmId() or nil
    local fx, fz = playerForwardXZ()
    local max2 = CYCLE_MAX_DIST * CYCLE_MAX_DIST
    local best, bestScore = nil, math.huge
    for _, p in ipairs(ps.placeables) do
        if p.rootNode ~= nil and matchFn(p) then
            local owned = SmartDistribution._farmCanUse(p, farmId)
            if owned then
                -- consider EVERY loading/unloading node; the player may stand at any
                -- of them, so the asset is "the one you mean" when you are near + looking
                -- at any single input/output point of it.
                for _, node in ipairs(assetInteractionNodes(p)) do
                    local x, _, z = getWorldTranslation(node)
                    local dx, dz = x - px, z - pz
                    local d2 = dx * dx + dz * dz
                    if d2 <= max2 then
                        -- hard "looking at it" gate: node must be IN FRONT of the player and within
                        -- LOOK_AT_RADIUS of the gaze line. No gaze available (fx == nil) -> don't gate,
                        -- fall back to nearest-within-range so the prompt still functions.
                        local looking, score = true, d2
                        if fx ~= nil and d2 > 1e-4 then
                            local along = dx * fx + dz * fz             -- > 0  => in front of the player
                            local perp  = math.abs(dx * fz - dz * fx)   -- perpendicular distance to gaze line
                            looking = (along > 0) and (perp <= LOOK_AT_RADIUS)
                            local align = along / math.sqrt(d2)         -- cos(angle), for ranking only
                            score = d2 * (1.5 - 0.5 * align)            -- among gated nodes: prefer near + centred
                        end
                        if looking and score < bestScore then best, bestScore = p, score end
                    end
                end
            end
        end
    end
    return best
end

-- silo-only (kept for back-compat) and the generalized configurable-asset lookup
function SmartDistribution.findNearestOwnedSilo()
    return findNearestOwned(function(p) return p.spec_silo ~= nil end)
end
function SmartDistribution.findNearestConfigurableAsset()
    -- a configurable class AND still in the network: assets excluded via Settings lose their direct
    -- loading/unloading-point access (the [ prompt + cycle key stop seeing them).
    return findNearestOwned(function(p)
        if SmartDistribution.isMarket ~= nil and SmartDistribution.isMarket(p) then return isEnrolled(p) end   -- markets/kiosks: [ opens the Markets tab (only while the Markets group is on)
        local cfg = p.spec_silo ~= nil or isHusbandryBuilding(p) or p.spec_objectStorage ~= nil
                 or isManurePit(p) or isBeehiveSpawner(p) or getProductionPoint(p) ~= nil
                 or SmartDistribution.bulkHallSpec(p) ~= nil
        return cfg and isEnrolled(p)
    end)
end

-- input action callback: cycle the nearest configurable asset (silo or barn)
function SmartDistribution.onCycleAction(self, actionName, inputValue)
    local asset = SmartDistribution.findNearestConfigurableAsset()
    if asset == nil then
        SmartDistribution.notify(string.format("No configurable asset within %dm", CYCLE_MAX_DIST))
        return
    end
    SmartDistribution.cycleAssetMode(asset)
end

-- open the per-asset config dialog for the nearest configurable asset
-- (openAssetDialog + the old per-asset Silo/Production popups were retired; [ opens the menu now)

function SmartDistribution.onOpenDialogAction(self, actionName, inputValue)
    local asset = SmartDistribution.findNearestConfigurableAsset()
    if asset == nil then
        SmartDistribution.notify(string.format("No configurable asset within %dm", CYCLE_MAX_DIST))
        return
    end
    SmartDistribution.openMenuForAsset(asset)
end

-- [ + gaze: open the consolidated menu jumped straight to the gazed asset's tab
-- (productions / silos / silo extensions / animal husbandry) with that asset
-- preselected. Falls back to the old list dialog only if the new menu is absent.
-- Jump the ALREADY-OPEN menu to an asset's tab and select it (Overview row double-click).
-- Deliberately NOT routed through openMenuForAsset below: that one has to cope with the menu being shut,
-- so it branches on `menu.isOpen` -- a field the base ScreenElement maintains and DR never sets itself. From
-- inside the menu the answer is known, so this calls focusAsset directly and cannot silently do nothing.
-- Lives here rather than in the page because getAssetClass is a local of this file.
function SmartDistribution.jumpMenuToAsset(asset)
    if asset == nil then return false end
    local menu = SmartDistribution._menu
    if menu == nil or menu.focusAsset == nil then return false end
    menu._focusAsset = asset
    menu._focusClass = getAssetClass(asset)
    menu:focusAsset()
    return true
end

function SmartDistribution.openMenuForAsset(asset)
    if asset == nil then return end
    local menu = SmartDistribution._menu
    if menu == nil then
        SmartDistribution.notify("Distribution menu isn't ready yet")
        return
    end
    menu._focusAsset = asset
    menu._focusClass = getAssetClass(asset)
    if menu.isOpen then
        if menu.focusAsset ~= nil then menu:focusAsset() end          -- already open: jump now
    elseif g_gui ~= nil and not g_gui:getIsGuiVisible() then
        g_gui:showGui("DistributionMenu")                             -- onOpen consumes the pending focus
    end
end

-- ---- manager (authoritative list) ------------------------------------------
-- every owned configurable asset (silos + barns for now; productions join when
-- their config lands), ordered by class then name, for the manager list.
-- ---- Markets tab helpers (per-market buffer / timing / accepted-item list) --
function SmartDistribution.hasAnyMarket()
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return false end
    for _, p in ipairs(ps.placeables) do if SmartDistribution.isMarket(p) then return true end end
    return false
end
function SmartDistribution.marketBufferOf(market, ft)
    if market == nil then return 0 end
    return SmartDistribution.marketBufferLevel(getUid(market), ft)
end
-- per-(market, ft) sell-mode label for the MODE column.
function SmartDistribution.marketProductLabel(market, ft)
    -- no market resolved: report the RESOLVED default, not a hardcoded word, or the column contradicts
    -- what an unconfigured product actually does
    local m = (market == nil) and SmartDistribution.marketDefaultMode()
              or SmartDistribution.marketSellMode(getUid(market), ft)
    if m == SmartDistribution.MARKET_HOLD then return SmartDistribution.l10n("dr_market_hold", "Hold") end
    if m == SmartDistribution.MARKET_BEST then return SmartDistribution.l10n("dr_market_best", "Sell  -  Best price") end
    return SmartDistribution.l10n("dr_market_immediate", "Sell  -  Immediate")
end
-- current per-(market, ft) sell mode (0/1/2), taking the market placeable.
function SmartDistribution.marketModeOf(market, ft)
    if market == nil or ft == nil then return SmartDistribution.marketDefaultMode() end
    return SmartDistribution.marketSellMode(getUid(market), ft)
end
-- short sell-type label (Immediate / Best price) for the footer button; nil while Held.
function SmartDistribution.marketSellTypeLabel(market, ft)
    if market == nil or ft == nil then return nil end
    local m = SmartDistribution.marketSellMode(getUid(market), ft)
    if m == SmartDistribution.MARKET_HOLD then return nil end
    if m == SmartDistribution.MARKET_BEST then
        return SmartDistribution.l10n("dr_timing_bestPrice", "Best price")
    end
    return SmartDistribution.l10n("dr_timing_immediate", "Immediate")
end
-- "Change output": toggle the selected product between Sell and Hold.
-- Coming OFF Hold lands on the player's chosen DEFAULT, not a hardcoded Immediate. The old form could
-- never produce Best price and wrote an explicit 0, which then overrode the "Default sell timing" setting
-- for that product permanently -- reported in game as markets "always defaulting to immediate regardless
-- of the setting", and the reason wiring the default in (5.44) appeared to change nothing: one press of
-- this button pinned the product to Immediate for good.
-- Written as if/else rather than `a and b or c`: marketDefaultMode() can return 0, and this file has been
-- bitten by that collapse before (see marketSellMode).
function SmartDistribution.marketToggleOutput(market, ft)
    if market == nil or ft == nil then return SmartDistribution.MARKET_IMMEDIATE end
    local cur = SmartDistribution.marketSellMode(getUid(market), ft)
    local nextMode
    if cur == SmartDistribution.MARKET_HOLD then
        -- only ever Immediate or Best price, so this can never resolve back to Hold and leave the
        -- button visibly doing nothing
        nextMode = SmartDistribution.marketDefaultMode()
    else
        nextMode = SmartDistribution.MARKET_HOLD
    end
    SmartDistribution.applyMarketTiming(market, ft, nextMode)
    return nextMode
end
-- What the MODE cell should read for a market product, and whether the player's choice is currently
-- being OVERRULED. Two facts, because with the Selling setting off they diverge and the player needs
-- both: what the market is actually DOING right now, and what they set it to.
--
-- Reported 2026-08-22: after the 6.25a split the rows correctly kept showing the stored choice, but
-- "there is really no indication that all lines have been set to sell immediate". Honest about the
-- setting, silent about the override -- so the row said Hold while the market sold everything on
-- arrival. The footer button said so, but only for the selected row and only if you looked.
--
-- Returns (text, overridden). When nothing is overruling the choice this is exactly marketProductLabel,
-- so the normal case is unchanged.
function SmartDistribution.marketModeDisplay(market, ft)
    local chosen = SmartDistribution.marketProductLabel(market, ft)
    if S.global.sellEnabled then return chosen, false end
    -- Selling off: the pass sells on arrival whatever the timing says (marketSellModeEffective). Lead
    -- with what it is DOING and keep the choice visible after it, so the arrows still visibly edit
    -- something real -- and drop the suffix when the two agree, or every Immediate row would carry a
    -- redundant "(set: Sell - Immediate)".
    local doing = SmartDistribution.l10n("dr_market_sellsNow", "Sells now")
    local uid = getUid(market)
    if uid ~= nil and SmartDistribution.marketSellMode(uid, ft) == SmartDistribution.MARKET_IMMEDIATE then
        return doing, true
    end
    return string.format(SmartDistribution.l10n("dr_market_sellsNowSet", "%s (set: %s)"), doing, chosen), true
end

-- ONE RING OVER ALL THREE MARKET STATES: Hold -> Sell Immediate -> Sell Best price -> Hold.
--
-- The two toggles below it (marketToggleOutput = Hold<->Sell, marketToggleSellType = Immediate<->Best)
-- each cover a PAIR, and the second HIDES ITSELF while a product is on Hold -- so reaching Immediate from
-- Hold meant pressing one button and then a second one that did not exist until the first press.
-- Reported 2026-08-21 as "I can not change the market output mode"; instrumenting it showed seven
-- presses, seven correct writes, and the value flipping Hold <-> Best every time. The control worked, it
-- simply could not REACH the third state. This is what the in-row arrows and Z/X drive.
--
-- Ordered Hold FIRST so stepping forward off Hold reaches "sell it now" before "wait for the peak" --
-- coming off a hold, the impatient option is the commoner intent.
SmartDistribution.MARKET_TIMING_RING = { 2, 0, 1 }   -- HOLD, IMMEDIATE, BEST (values, not indices)

function SmartDistribution.marketTimingNext(cur)
    local R = SmartDistribution.MARKET_TIMING_RING
    for i = 1, #R do
        if R[i] == cur then return R[(i % #R) + 1] end
    end
    return SmartDistribution.MARKET_HOLD              -- an unknown value lands somewhere valid
end

-- DERIVED BY WALKING FORWARD, never a second hand-written order -- the rule cyclePrevForAsset and
-- prevVirtual both follow, so the two directions cannot drift when a value is added.
function SmartDistribution.marketTimingPrev(cur)
    local R = SmartDistribution.MARKET_TIMING_RING
    local c = R[1]
    for _ = 1, #R do
        local n = SmartDistribution.marketTimingNext(c)
        if n == cur then return c end
        c = n
    end
    return cur
end

-- Step the selected market product one place around that ring. Shares applyMarketTiming with the footer
-- buttons, so the arrows, the keys and the footer all replicate and refresh identically.
function SmartDistribution.marketCycleTiming(market, ft, back)
    if market == nil or ft == nil then return end
    local cur = SmartDistribution.marketSellMode(getUid(market), ft)
    local nextMode = back and SmartDistribution.marketTimingPrev(cur)
                          or  SmartDistribution.marketTimingNext(cur)
    if nextMode == nil or nextMode == cur then return cur end
    SmartDistribution.applyMarketTiming(market, ft, nextMode)
    return nextMode
end

-- "Change sell type": toggle the selected product between Immediate and Best price (no-op while Held).
function SmartDistribution.marketToggleSellType(market, ft)
    if market == nil or ft == nil then return end
    local cur = SmartDistribution.marketSellMode(getUid(market), ft)
    if cur == SmartDistribution.MARKET_HOLD then return cur end
    local nextMode = (cur == SmartDistribution.MARKET_BEST) and SmartDistribution.MARKET_IMMEDIATE or SmartDistribution.MARKET_BEST
    SmartDistribution.applyMarketTiming(market, ft, nextMode)
    return nextMode
end
-- "Change all outputs": set every accepted product of the market to Sell or Hold.
-- Same rule as marketToggleOutput: "Sell" means the player's chosen default, not a hardcoded Immediate.
-- The values ARE written explicitly -- a deliberate bulk action should produce a state that sticks if the
-- global default is changed later, unlike a product the player has simply never touched.
function SmartDistribution.marketSetAllOutputs(market, hold)
    if market == nil then return end
    local mode
    if hold then mode = SmartDistribution.MARKET_HOLD
    else         mode = SmartDistribution.marketDefaultMode() end
    for ft in pairs(SmartDistribution.marketMenuFillTypes(market)) do
        SmartDistribution.applyMarketTiming(market, ft, mode)
    end
end
-- set + sync a (market, ft) sell mode. On the sync-receiving side run() calls this with
-- noEventSend = true so it never echoes back. Mirrors applyAssetSellTiming.
function SmartDistribution.applyMarketTiming(market, ft, mode, noEventSend)
    if market == nil or ft == nil then return end
    SmartDistribution.setMarketSellMode(getUid(market), ft, mode)
    if not noEventSend and DistributionMarketTimingEvent ~= nil and DistributionMarketTimingEvent.sendEvent ~= nil then
        DistributionMarketTimingEvent.sendEvent(market, ft, mode)
    end
end
-- replay every non-default (market, ft, mode) for the multiplayer join sync.
function SmartDistribution.forEachMarketTiming(fn)
    if fn == nil or g_currentMission == nil then return end
    local ps = g_currentMission.placeableSystem
    if ps == nil then return end
    for _, p in ipairs(ps.placeables) do
        if SmartDistribution.isMarket(p) then
            local byFt = SmartDistribution._marketTiming[getUid(p)]
            if byFt ~= nil then
                for ft, mode in pairs(byFt) do
                    -- every explicit choice replays, Immediate included: a joining client resolves an
                    -- absent entry through its own marketDefaultMode(), so anything omitted here would
                    -- silently become whatever that client's default happens to be
                    if mode ~= nil then fn(p, ft, mode) end
                end
            end
        end
    end
end
-- ---- Animal Husbandry tab data --------------------------------------------
-- the input fill types a husbandry demands: animal food + straw + (non-automatic) water.
function SmartDistribution.husbandryInputFillTypes(p)
    local out = {}
    if p == nil then return out end
    -- Feeding-robot barns take ingredients into per-fill-type BUNKERS, not a shared food pool: list the
    -- bunker fill types (silage / hay / straw / mineral feed) instead of the generic food supportedFillTypes.
    -- Water still applies if not auto-supplied. (Straw bedding shares the STRAW bunker ft here.)
    if SmartDistribution.feedingRobotOf(p) ~= nil then
        for ft in pairs(SmartDistribution.robotBunkerFillTypes(p)) do out[ft] = true end
        local water = waterFillType()
        if water ~= nil and p.spec_husbandryWater ~= nil and not p.spec_husbandryWater.automaticWaterSupply then out[water] = true end
        return out
    end
    local fmap = foodQualityMap(p)
    if fmap ~= nil then for ft in pairs(fmap) do out[ft] = true end end
    if p.getHusbandryIsFillTypeSupported ~= nil then
        local straw = g_fillTypeManager ~= nil and g_fillTypeManager:getFillTypeIndexByName("STRAW") or nil
        if straw ~= nil and p.spec_husbandryStraw ~= nil then
            local ok, sup = pcall(p.getHusbandryIsFillTypeSupported, p, straw); if ok and sup then out[straw] = true end
        end
        local water = waterFillType()
        if water ~= nil and p.spec_husbandryWater ~= nil and not p.spec_husbandryWater.automaticWaterSupply then
            local ok, sup = pcall(p.getHusbandryIsFillTypeSupported, p, water); if ok and sup then out[water] = true end
        end
    end
    -- The pits (Manure Pit / Slurry Pit) are HEAP assets, not barns, so none of the barn specs above
    -- apply and they were listing no incoming product at all. What flows INTO a pit is simply what its
    -- storage holds: manure for a manure heap, liquid manure for a slurry pit.
    if not isHusbandryBuilding(p) then
        for _, s in ipairs(getAllStorages(p)) do
            for ft in pairs(storageFillTypes(s)) do out[ft] = true end
        end
    end
    return out
end

-- held / capacity for a husbandry INPUT. Animal food is a single SHARED pool (spec_husbandryFood):
-- every food fill type reports the same total food level and the shared food capacity. Straw / water
-- read their own husbandry fill levels.
-- The BARN's total food across every type -- what the base game's own info panel shows (getTotalFood).
-- Kept separate from husbandryInputHeld, which answers the per-product question.
function SmartDistribution.husbandryFoodTotal(p)
    local fs = p ~= nil and p.spec_husbandryFood or nil
    if fs == nil or fs.fillLevels == nil then return 0 end
    local t = 0
    for _, lvl in pairs(fs.fillLevels) do t = t + (lvl or 0) end
    return t
end

function SmartDistribution.husbandryInputHeld(p, ft)
    if p == nil or ft == nil then return 0 end
    if SmartDistribution.feedingRobotOf(p) ~= nil and SmartDistribution.robotBunkerFillTypes(p)[ft] then
        return SmartDistribution.robotBunkerLevel(p, ft)
    end
    local fs = p.spec_husbandryFood
    if fs ~= nil and fs.supportedFillTypes ~= nil and fs.supportedFillTypes[ft] and ft ~= waterFillType() then
        -- THE PER-FOOD LEVEL, not the barn's total. This summed every food type and returned the same
        -- figure for all of them, so a Cow Barn holding 1,458 L of food showed "1,458 L (4%)" on its
        -- Silage row, its Grass row, its Hay row AND its TMR row -- four identical numbers that told the
        -- player nothing about what the barn actually had (reported 2026-08-26 with the food bars, which
        -- made four identical bars impossible to miss).
        --
        -- spec.fillLevels IS per fill type: PlaceableHusbandryFood saves one <fillLevel fillType=...>
        -- element each and network-syncs them individually, and getTotalFood() is defined as the SUM of
        -- them. So the per-product figure was always there; DR was throwing it away.
        --
        -- The barn total is still available where it is genuinely wanted -- husbandryFoodTotal below --
        -- and the CAPACITY stays the pool's, because the foods really do share one tank. Green is now
        -- this food, red is the other foods, grey is free space: the same reading as a silo.
        if fs.fillLevels ~= nil then return fs.fillLevels[ft] or 0 end
        return 0
    end
    if p.getHusbandryFillLevel ~= nil then
        local ok, lvl = pcall(p.getHusbandryFillLevel, p, ft); if ok and type(lvl) == "number" then return lvl end
    end
    return SmartDistribution.assetHeld(p, ft)
end
function SmartDistribution.husbandryInputCapacity(p, ft)
    if p == nil or ft == nil then return 0 end
    if SmartDistribution.feedingRobotOf(p) ~= nil and SmartDistribution.robotBunkerFillTypes(p)[ft] then
        return SmartDistribution.robotBunkerCapacity(p, ft)
    end
    local fs = p.spec_husbandryFood
    if fs ~= nil and fs.supportedFillTypes ~= nil and fs.supportedFillTypes[ft] and ft ~= waterFillType() then
        return fs.capacity or 0
    end
    if p.getHusbandryCapacity ~= nil then
        local ok, c = pcall(p.getHusbandryCapacity, p, ft); if ok and type(c) == "number" and c > 0 then return c end
    end
    return SmartDistribution.assetCapacity(p, ft)
end

-- total storage capacity for ft across an asset's storages (partner to assetHeld).
function SmartDistribution.assetCapacity(p, ft)
    if p == nil or ft == nil then return 0 end
    local total = 0
    local okS, storages = pcall(getAllStorages, p)
    if okS and type(storages) == "table" then
        for _, storage in ipairs(storages) do
            local c = storageCapacity(storage, ft); if type(c) == "number" then total = total + c end
        end
    end
    return total
end

-- monthly husbandry production per (asset, ft), summed from the rolling window (mirrors monthlyReceived).
function SmartDistribution.monthlyProduced(p, ft)
    if p == nil or ft == nil then return 0 end
    local uid = getUid(p)
    if clientMonthly ~= nil then
        local au = clientMonthly[uid]; local e = au ~= nil and au[ft] or nil
        return e ~= nil and (e.produced or 0) or 0
    end
    local r = 0
    for i = 1, MONTHLY_CYCLES do
        local snap = monthlyRing[i]
        local a = snap ~= nil and snap[uid] or nil
        local e = a ~= nil and a[ft] or nil
        if e ~= nil then r = r + (e.produced or 0) end
    end
    return r
end

-- The pallet-borne stock of a husbandry output: the internal pending queue PLUS what is on its pad.
--
-- assetHeld deliberately reports ONE or the OTHER -- pendingLiters under Hold Internal, pallets otherwise
-- -- because counting both would freeze the DISPLAY the instant a pallet spawns (buffer drops, pallet
-- rises, total unchanged). For a TRACKER that same property is exactly what is wanted: the sum is
-- CONSERVED across a spawn, so it moves only when the barn makes something or a pallet leaves. That is
-- also why this needs none of the debt-carry machinery the production path uses -- a production's
-- palletized output swings negative on a spawn because its buffer and its pallets are measured on
-- different bases, whereas these two are the same litres in two places.
-- It is stable across a MODE change too, which assetHeld is not: switching to Hold Internal flips its
-- basis outright and would otherwise read as one enormous load or unload.
-- One pass over the pad: the litres standing on it, AND a pallet-object -> litres map. The map is what
-- separates a pallet that LEFT from litres the barn merely added, which a single scalar cannot do (see
-- the observe function below).
function SmartDistribution.husbandryPadState(p, ft)
    local total, byObj = 0, {}
    for _, pallet in ipairs(husbandryPalletObjects(p, ft)) do
        local idx = (pallet.spec_pallet ~= nil and pallet.spec_pallet.fillUnitIndex) or 1
        local lvl = (pallet.getFillUnitFillLevel ~= nil) and (pallet:getFillUnitFillLevel(idx) or 0) or 0
        total = total + lvl
        byObj[pallet] = lvl
    end
    return total, byObj
end

function SmartDistribution.husbandryPalletStock(p, ft)
    local pad = SmartDistribution.husbandryPadState(p, ft)
    return (SmartDistribution.palletPendingLiters(p, ft) or 0) + pad
end

-- The spec's declared output rate for a pallet fill type, or nil when it does not state one. Probed on a
-- sheep barn as litersPerHour=33.4 for WOOL. Used as the ceiling on how much of a RISE can be production.
function SmartDistribution.husbandryLitersPerHour(p, ft)
    local hs = p ~= nil and p.spec_husbandryPallets or nil
    local t  = hs ~= nil and hs.litersPerHour or nil
    local v  = type(t) == "table" and t[ft] or nil
    if type(v) == "number" and v > 0 then return v end
    return nil
end
-- Generous headroom on that rate before a rise is called a player load: the declared figure tracks animal
-- count and productivity, so it is a moving target, and misreading real production as a manual load is a
-- worse error than missing a load. A dropped-off pallet is ~1000 L against a 33 L/h rate, so the two are
-- nowhere near this boundary.
SmartDistribution.HUSB_RATE_SLACK = 1.5

-- Per-cycle husbandry PRODUCED tracker: the rise in an output's held level between the previous
-- cycle's end and this cycle's start is pure production (nothing is drained in between). Recorded
-- into the cycle ledger as "produced"; the end-of-cycle level is committed as next cycle's baseline.
--
-- PALLET outputs (eggs / wool / honey) are measured PER PALLET OBJECT, not from the stock total.
--
-- The stock total alone does not work, and this was measured in game: a wool pallet carried off read as
-- UNLOADED 897 against the 1000 L pallet actually taken. A husbandry spawns a pallet the moment it has any
-- product and then TRICKLES into it (~46 L/h observed), so within one cycle a removal and that hour's
-- production land in the same scalar and net against each other. A production never shows this -- its pad
-- moves in whole 1000 L steps between spawns, and 5.15 has an explicit spawner-drain term to separate the
-- two -- which is exactly why this needed its own treatment rather than a port.
--
-- So the pad is snapshotted as pallet OBJECT -> litres. A pallet present at the last commit and absent now
-- LEFT, and it left carrying the litres recorded against it, whatever the barn produced meanwhile. One
-- still present but LOWER was drained where it stands (a player pumping wool out of it), which is the same
-- event by a different route. Nothing else can remove one: DR's own draining happens inside the pass,
-- between observe and commit, so a DR-shipped pallet is already gone from the baseline snapshot; and a
-- forklifted pallet touches no Storage and raises no DR flow, so this is the only way to see it at all.
--
-- Production then falls out as the RESIDUAL: gained = (stockNow - stockPrev) + removed. Conservation makes
-- this exact -- every litre either sits in pending, sits on a pallet, or left on one.
-- Residual error, bounded and accepted: litres added to a pallet BETWEEN the snapshot and its removal go
-- with it uncounted, so taking the one still filling can under-read by up to a cycle's production (~46 L).
-- Taking a FULL pallet -- the normal case, and the one that read 897 -- is now exact, since a full pallet
-- cannot grow.
--
-- The rise is still split rather than trusted wholesale: production cannot exceed the spec's declared
-- litersPerHour in one cycle, so anything past that is a pallet the player PARKED on the pad and is
-- ledgered as `loaded`. Self-disabling -- with no declared rate the whole rise stays `produced`, which is
-- the previous behaviour.
SmartDistribution._husbProdLast   = {}   -- uid -> ft -> last end-of-cycle output level (assetHeld basis)
SmartDistribution._husbPalletLast = {}   -- uid -> ft -> last end-of-cycle (pending + pad) litres
SmartDistribution._husbPadSnap    = {}   -- uid -> ft -> { [palletObject] = litres } at last commit
-- All session-only, like _prodThruLast: a missing baseline reads the current state and yields a zero delta,
-- so an existing save starts measuring from the next cycle rather than inventing a flow.
-- _husbPadSnap holds STRONG references deliberately. A weak-keyed table would let a removed pallet be
-- collected before the comparison runs, which is precisely the event being detected -- it would vanish
-- from the snapshot and read as though it had never been there. They are held for one cycle only.
function SmartDistribution.observeHusbandryProduction()
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return end
    for _, p in ipairs(ps.placeables) do
        if getProductionPoint(p) == nil and isHusbandryBuilding(p) and isEnrolled(p) then
            local uid = getUid(p)
            local last    = SmartDistribution._husbProdLast[uid]
            local palLast = SmartDistribution._husbPalletLast[uid]
            local snapLast = SmartDistribution._husbPadSnap[uid]
            local outs, pal = husbandryOutputFillTypes(p), {}
            local pfts = palletSpawnerFillTypes(p)
            if pfts ~= nil then for _, ft in ipairs(pfts) do outs[ft] = true; pal[ft] = true end end
            for ft in pairs(outs) do
                if pal[ft] then
                    local padNow, objNow = SmartDistribution.husbandryPadState(p, ft)
                    local pend = SmartDistribution.palletPendingLiters(p, ft) or 0
                    local cur  = pend + padNow
                    local prev = (palLast ~= nil and palLast[ft]) or cur
                    -- what LEFT the pad, read off the pallets themselves rather than inferred from the total
                    local removed = 0
                    local objPrev = snapLast ~= nil and snapLast[ft] or nil
                    if objPrev ~= nil then
                        for obj, lvl in pairs(objPrev) do
                            local now = objNow[obj]
                            if now == nil then removed = removed + lvl              -- pallet gone entirely
                            elseif now < lvl then removed = removed + (lvl - now) end -- drained where it stands
                        end
                    end
                    -- production is the residual: whatever the stock did, plus whatever left it
                    local gained = (cur - prev) + removed
                    if removed > 0 then ledgerAdd(p, ft, "unloaded", removed) end
                    if gained > 0 then
                        local rate = SmartDistribution.husbandryLitersPerHour(p, ft)
                        local ceil = rate ~= nil and (rate * SmartDistribution.HUSB_RATE_SLACK) or nil
                        if ceil ~= nil and gained > ceil then
                            ledgerAdd(p, ft, "produced", ceil)
                            ledgerAdd(p, ft, "loaded", gained - ceil)
                        else
                            ledgerAdd(p, ft, "produced", gained)
                        end
                    end
                    if SmartDistribution._prodThruDebug and (removed > 0 or gained ~= 0) then
                        SmartDistribution.log("husbPad %s#%s [%s] prev=%d cur=%d (pending=%d pad=%d) removed=%d -> produced %d",
                            placeableName(p), tostring(uid), fillTypeName(ft), prev, cur,
                            pend, padNow, removed, math.max(gained, 0))
                    end
                else
                    -- milk / manure / slurry: Storage-backed, so they keep the assetHeld basis. They must
                    -- NOT take the signed path -- installManualTransferTracking already sees every Storage
                    -- write and ledgers their loaded/unloaded, and doing it here too would double count.
                    local cur  = SmartDistribution.assetHeld(p, ft)
                    local prev = (last ~= nil and last[ft]) or cur
                    if cur - prev > 0 then ledgerAdd(p, ft, "produced", cur - prev) end
                end
            end
        end
    end
end
function SmartDistribution.commitHusbandryProduction()
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return end
    for _, p in ipairs(ps.placeables) do
        if getProductionPoint(p) == nil and isHusbandryBuilding(p) and isEnrolled(p) then
            local uid = getUid(p)
            local rec = SmartDistribution._husbProdLast[uid]; if rec == nil then rec = {}; SmartDistribution._husbProdLast[uid] = rec end
            local pRec = SmartDistribution._husbPalletLast[uid]; if pRec == nil then pRec = {}; SmartDistribution._husbPalletLast[uid] = pRec end
            local sRec = SmartDistribution._husbPadSnap[uid]; if sRec == nil then sRec = {}; SmartDistribution._husbPadSnap[uid] = sRec end
            local outs, pal = husbandryOutputFillTypes(p), {}
            local pfts = palletSpawnerFillTypes(p)
            if pfts ~= nil then for _, ft in ipairs(pfts) do outs[ft] = true; pal[ft] = true end end
            -- baselined AFTER every phase has run, so whatever DR shipped this cycle is already gone from
            -- the pad and the next observe only ever sees production and player action. The per-pallet map
            -- is REPLACED, never merged, so references to shipped pallets are dropped each cycle.
            for ft in pairs(outs) do
                if pal[ft] then
                    local padNow, objNow = SmartDistribution.husbandryPadState(p, ft)
                    sRec[ft] = objNow
                    pRec[ft] = (SmartDistribution.palletPendingLiters(p, ft) or 0) + padNow
                else rec[ft] = SmartDistribution.assetHeld(p, ft) end
            end
        end
    end
end

-- Per-cycle husbandry CONSUMED tracker (feed / water / straw eaten by the animals). Same buffer-delta
-- idea as the production tracker: consumed = (prevLevel + received) - currentLevel, using THIS cycle's
-- flows (cycleAcc, passed in) so the windows align. Called once at end of runHourly.
--
-- COMPLICATION: animal food is a single SHARED pool (spec_husbandryFood) -- every food fill type
-- reports the SAME pool total via husbandryInputHeld, so a naive per-ft delta would count the whole
-- pool's drop once for EACH food type. We handle food specially: measure the pool drop ONCE, then
-- attribute it across the food types in proportion to what was delivered (received) this cycle. Water
-- and straw (and pit contents) are single fill types with their own levels, so they use the plain
-- per-ft formula.
SmartDistribution._husbConsumeLast = {}   -- uid -> ft -> last end-of-cycle input level (per-ft; food uses a shared key)
function SmartDistribution.recordHusbandryConsumption(flows)
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return end
    local function flow(uid, ft, field)
        local a = flows ~= nil and flows[uid] or nil
        local e = a ~= nil and a[ft] or nil
        return e ~= nil and (e[field] or 0) or 0
    end
    local water = waterFillType()
    for _, p in ipairs(ps.placeables) do
        if getProductionPoint(p) == nil and isHusbandryBuilding(p) and isEnrolled(p) then
            local uid = getUid(p)
            local last = SmartDistribution._husbConsumeLast[uid]
            local rec  = last; if rec == nil then rec = {}; SmartDistribution._husbConsumeLast[uid] = rec end
            local fs = p.spec_husbandryFood

            -- split inputs into shared-pool food vs standalone (water / straw / pit)
            local foodFts, soloFts = {}, {}
            for ft in pairs(SmartDistribution.husbandryInputFillTypes(p)) do
                if fs ~= nil and fs.supportedFillTypes ~= nil and fs.supportedFillTypes[ft] and ft ~= water then
                    foodFts[#foodFts + 1] = ft
                else
                    soloFts[#soloFts + 1] = ft
                end
            end

            -- standalone inputs: plain per-ft delta
            for _, ft in ipairs(soloFts) do
                local cur  = SmartDistribution.husbandryInputHeld(p, ft)
                local prev = (last ~= nil and last[ft]) or cur
                local consumed = (prev + flow(uid, ft, "received")) - cur
                if consumed > 0 then ledgerAdd(p, ft, "consumed", consumed) end
                rec[ft] = cur
            end

            -- shared food pool: measure the pool drop once, attribute by received-share
            if #foodFts > 0 then
                local pool = 0
                if fs ~= nil and fs.fillLevels ~= nil then for _, lvl in pairs(fs.fillLevels) do pool = pool + (lvl or 0) end end
                local prevPool = (last ~= nil and last["__foodPool"]) or pool
                local totalRecv = 0
                for _, ft in ipairs(foodFts) do totalRecv = totalRecv + flow(uid, ft, "received") end
                local poolConsumed = (prevPool + totalRecv) - pool
                if poolConsumed > 0 then
                    if totalRecv > 0 then
                        -- attribute proportional to what was delivered this cycle
                        for _, ft in ipairs(foodFts) do
                            local share = flow(uid, ft, "received") / totalRecv
                            local c = poolConsumed * share
                            if c > 0 then ledgerAdd(p, ft, "consumed", c) end
                        end
                    else
                        -- nothing delivered this cycle: attribute to the food type with the most on hand
                        local bigFt, bigLvl = nil, -1
                        if fs ~= nil and fs.fillLevels ~= nil then
                            for ft, lvl in pairs(fs.fillLevels) do
                                if (lvl or 0) > bigLvl then bigLvl = lvl or 0; bigFt = ft end
                            end
                        end
                        if bigFt ~= nil then ledgerAdd(p, bigFt, "consumed", poolConsumed) end
                    end
                end
                rec["__foodPool"] = pool
            end
        end
    end
end

-- Per-cycle production THROUGHPUT tracker (buffer deltas, mirrors the husbandry produced tracker).
-- A production point shares one pp.storage for inputs and outputs, so a raw level delta mixes
-- production with distribution flow. We isolate production by adjusting with the flows we ledgered
-- THIS cycle (cycleAcc, passed in), measured over the SAME window as the buffer delta:
--   consumed(input ft)  = (prevLevel + received) - currentLevel          -- fell despite deliveries in
--   produced(output ft) = (currentLevel - prevLevel) + (dist+sold+stored) -- rose despite draw-off
-- Both clamped >= 0. Called ONCE at end of runHourly (before cycleAcc is cleared): it snapshots the
-- new baseline AND records the deltas in one pass, so the delta window and the flow window align
-- exactly (both = this cycle). `flows` is cycleAcc.
-- uid -> { [inputFt] = last end-of-cycle pp.storage level, __out = { [outputFt] = last buffer+pallet pool } }
-- Session-only (never persisted): a reload just re-baselines on the first pass.
SmartDistribution._prodThruLast = {}
function SmartDistribution.recordProductionThroughput(flows)
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return end
    local function flow(uid, ft, field)
        local a = flows ~= nil and flows[uid] or nil
        local e = a ~= nil and a[ft] or nil
        return e ~= nil and (e[field] or 0) or 0
    end
    for _, p in ipairs(ps.placeables) do
        local pp = getProductionPoint(p)
        if pp ~= nil and pp.storage ~= nil and isEnrolled(p) then
            local uid = getUid(p)
            local last = SmartDistribution._prodThruLast[uid]
            local rec  = last; if rec == nil then rec = {}; SmartDistribution._prodThruLast[uid] = rec end
            local inFts, outFts = {}, {}
            for _, line in ipairs(SmartDistribution.productionLines(p) or {}) do
                for _, i in ipairs(line.inputs or {})  do inFts[i.ft]  = true end
                for _, o in ipairs(line.outputs or {}) do outFts[o.ft] = true end
            end
            -- inputs: consumed = (prev + received) - cur
            for ft in pairs(inFts) do
                local cur  = getLevel(pp.storage, ft)
                local prev = (last ~= nil and last[ft]) or cur
                local consumed = (prev + flow(uid, ft, "received")) - cur
                if SmartDistribution._prodThruDebug then
                    SmartDistribution.log("prodThru IN %s [%s] prev=%d recv=%d cur=%d -> consumed=%d", placeableName(p), fillTypeName(ft), prev, flow(uid, ft, "received"), cur, consumed)
                end
                if consumed > 0 then ledgerAdd(p, ft, "consumed", consumed) end
            end
            -- outputs: measured in LITRES OUT OF THE PRODUCTION'S OWN BUFFER, never from pallet counts.
            --   produced = (bufferNow - bufferPrev) + dist + sold + stored
            -- The buffer is the only place a production actually deposits what it makes, so this is the
            -- litres it really made. Pallets are downstream packaging: the spawner moves litres from the
            -- buffer into a pallet, and DR then ships that pallet and ledgers it as dist/sold/stored, so
            -- the amount comes back in via the flow term and nothing is lost.
            --
            -- palletFillLevel must NOT be part of this. It counts world pallets within an association
            -- RADIUS of the building, so a bakery whose bread pallets are deposited into a pallet shed
            -- standing nearby keeps counting them: the level never drops while `stored` is still added,
            -- and the >=0 clamp makes the error one-directional. Observed in-game as ~2x inflation
            -- (produced 19,736 against 11,000 actually shipped and 457 held).
            -- The old pallet-LEVEL-only branch this replaced had the opposite failure: it reported ZERO
            -- whenever a pallet spawned and was collected inside the same cycle.
            --
            -- Known gap: whole pallets a PLAYER carries off (never shipped by DR, so never ledgered as an
            -- outflow) leave the buffer without being counted as produced. DR-routed output is exact.
            -- Output baselines live in rec.__out so they can never collide with an input baseline for the
            -- same fill type (different measurement bases).
            -- A palletized output swings NEGATIVE on the cycle a pallet spawns: the spawner takes a whole
            -- 1000 L out of the buffer while only ~275 L was made, and the matching `stored` does not
            -- arrive until DR ships that pallet a cycle or two later. Simply clamping at zero is
            -- asymmetric -- the negative is discarded but the compensating positive keeps its full value,
            -- so every spawn-then-ship pair over-counts by the clamped amount (observed: a bakery
            -- reporting ~10,300/month against a true ~6,600). Carry the shortfall forward as a DEBT and
            -- net it off the next positive instead, which makes the window sum exact while keeping every
            -- per-cycle figure >= 0.
            -- PALLETIZED outputs take their outflow from the SPAWNER DRAIN, not from DR's flows: DR ships
            -- pallets, so its dist/sold/stored never came out of pp.storage, while the spawner's
            -- buffer->pallet move did. The manual tracker has already observed that drop (a non-DR fall on
            -- an output) and is about to discard it, so read it here first -- recordProductionThroughput
            -- runs before flushManualTransfers clears the table.
            -- This makes produced independent of what becomes of the pallet: shipped by DR, parked on the
            -- spawner, or driven away. A HOLD PALLETS building never generates a DR flow at all, so the
            -- flow-based form left its debt growing every spawn and its produced pinned at 0.
            local pal, isPal = palletSpawnerFillTypes(p), {}
            if pal ~= nil then for _, pf in ipairs(pal) do isPal[pf] = true end end
            -- AUTO vs MANUAL removal from the pallet pad (state 2 of the three pallet states).
            -- Over one cycle the pad balances exactly:
            --     padNow = padPrev + spawnDrain - shippedByDR - takenByHand
            -- Every term but the last is already measured -- padPrev/padNow from palletLitresOf (which
            -- only counts pallets actually ON the pad), spawnDrain from the manual tracker, shippedByDR
            -- from the flows DR ledgered this cycle -- so the hand-carried remainder falls out by
            -- subtraction. That is the only way to see it: a pallet a player forklifts away never touches
            -- Storage and never produces a DR flow, so nothing else in the engine observes it.
            -- AUTO needs no new figure: it is the existing dist/sold/stored the Overview already shows.
            -- Order matters -- this runs INSIDE the pass, after palletPhase has already drained whatever
            -- DR is taking this cycle, so padNow and the flow terms describe the same window.
            local padLast, padNow = rec.__pad, {}
            local pend = SmartDistribution._manualPending[uid]
            local outLast, outNow = rec.__out, {}
            local debtLast, debtNow = rec.__debt, {}
            for ft in pairs(outFts) do
                local cur = getLevel(pp.storage, ft)
                outNow[ft] = cur
                local prev = (outLast ~= nil and outLast[ft]) or cur
                local out
                if isPal[ft] then
                    local e = pend ~= nil and pend[ft] or nil
                    local spawnDrain = (e ~= nil and e.unloaded) or 0
                    -- Palletizable does NOT mean every litre left on a pallet. DR ships whatever is in the
                    -- BUFFER as bulk and only ships PALLETS once the spawner has made some, and the two
                    -- come out of different pools. Taking the outflow as the spawner drain ALONE zeroed
                    -- `produced` for anything shipped straight from the buffer -- observed in game as a
                    -- dairy with "out=0 (stored=201) -> produced=0" and a greenhouse the same on
                    -- strawberries, both plainly working. So the bulk part is added back: it is whatever
                    -- DR shipped that did NOT come off the pad.
                    local palOut  = SmartDistribution.palletOutOf(uid, ft)
                    local shipped = flow(uid, ft, "dist") + flow(uid, ft, "sold") + flow(uid, ft, "stored")
                    local bulkOut = shipped - palOut
                    if bulkOut < 0 then bulkOut = 0 end
                    out = spawnDrain + bulkOut
                    local padCur  = SmartDistribution.palletLitresOf(p, ft)
                    padNow[ft]    = padCur
                    local padPrev = (padLast ~= nil and padLast[ft]) or padCur
                    -- the pad balance must use ONLY what left the pad. Using every flow made a bulk
                    -- shipment look like a missing pallet, so byHand went negative every cycle and the
                    -- carried debt ran away (seen on the greenhouse: debt=8276 on STRAWBERRY).
                    -- litres RECLAIMED off the pad into the buffer left the pad without being shipped and
                    -- without a player touching them, so they must come out of this balance too
                    local reclaim = SmartDistribution.palletReclaimOf(uid, ft)
                    local byHand  = ((padPrev + spawnDrain) - padCur) - palOut - reclaim
                    -- A NEGATIVE remainder is not a player loading the pad. It is measurement skew: a
                    -- pallet DR has ledgered but not yet despawned, or a spawn landing between the drain
                    -- observation and this read. Carrying it as a debt keeps the window sum honest without
                    -- inventing a load, the same trick `produced` uses above. Known gap, accepted: a pallet
                    -- a player genuinely parks ON the pad reads as skew and suppresses the next pickup.
                    local padDebt = (debtLast ~= nil and debtLast["__pad" .. ft]) or 0
                    byHand = byHand - padDebt
                    if byHand >= 0 then
                        debtNow["__pad" .. ft] = 0
                        if byHand > 0 then ledgerAdd(p, ft, "unloaded", byHand) end
                    else
                        debtNow["__pad" .. ft] = -byHand
                    end
                    if SmartDistribution._prodThruDebug then
                        -- palletsOut is what left the PAD; bulkOut left the buffer directly. Printing both
                        -- is what makes a "shipped but produced=0" case readable at a glance.
                        SmartDistribution.log("prodThru PAD %s#%s [%s] padPrev=%d spawnDrain=%d padNow=%d palletsOut=%d bulkOut=%d debt=%d -> byHand=%d",
                            placeableName(p), tostring(uid), fillTypeName(ft),
                            padPrev, spawnDrain, padCur, palOut, bulkOut, padDebt, math.max(byHand, 0))
                    end
                else
                    out = flow(uid, ft, "dist") + flow(uid, ft, "sold") + flow(uid, ft, "stored")
                end
                -- ...and out of `produced` for the same reason: the buffer rose, but the building did not
                -- make it -- it came back off its own pad.
                local raw  = (cur - prev) + out - SmartDistribution.palletReclaimOf(uid, ft)
                local debt = (debtLast ~= nil and debtLast[ft]) or 0
                local net  = raw - debt
                local produced, carry = 0, 0
                if net >= 0 then produced = net else carry = -net end
                debtNow[ft] = carry
                if SmartDistribution._prodThruDebug then
                    -- log the outflow term ACTUALLY used (spawner drain for pallets, DR flows for bulk),
                    -- and the uid: several buildings can share a display name, which made two bakeries
                    -- indistinguishable in the log while chasing exactly this.
                    SmartDistribution.log("prodThru OUT %s#%s [%s] %s buffer prev=%d cur=%d out=%d (dist=%d sold=%d stored=%d) raw=%d debt=%d -> produced=%d carry=%d",
                        placeableName(p), tostring(uid), fillTypeName(ft),
                        isPal[ft] and "PALLET(spawnDrain)" or "bulk", prev, cur, out,
                        flow(uid, ft, "dist"), flow(uid, ft, "sold"), flow(uid, ft, "stored"),
                        raw, debt, produced, carry)
                end
                if produced > 0 then ledgerAdd(p, ft, "produced", produced) end
            end
            -- snapshot the new baselines: inputs off the buffer, outputs off the buffer + carried debt
            for ft in pairs(inFts) do rec[ft] = getLevel(pp.storage, ft) end
            rec.__out  = outNow
            rec.__debt = debtNow
            -- pad baseline for the next cycle. Only palletized outputs write into padNow, so a building
            -- with no spawner keeps an empty table rather than a row of zeroes.
            rec.__pad  = padNow
        end
    end
end

-- MONTHLY (rolling 24-cycle) consumed for (production, input ft). Mirror of monthlyProduced.
function SmartDistribution.monthlyConsumed(p, ft)
    if p == nil or ft == nil then return 0 end
    local uid = getUid(p)
    if clientMonthly ~= nil then
        local au = clientMonthly[uid]; local e = au ~= nil and au[ft] or nil
        return e ~= nil and (e.consumed or 0) or 0
    end
    local r = 0
    for i = 1, MONTHLY_CYCLES do
        local snap = monthlyRing[i]
        local a = snap ~= nil and snap[uid] or nil
        local e = a ~= nil and a[ft] or nil
        if e ~= nil then r = r + (e.consumed or 0) end
    end
    return r
end

-- ============================================================================
-- MANUAL (non-DR) load / unload tracking
-- "Received" only ever counted litres DR itself delivered, so a trailer tipped into a silo by hand was
-- invisible. This records the other half: every storage change that is NOT Distribution Redux's doing.
--
-- Mechanism: hook the base Storage class (setFillLevel / addFillLevel -- both take the fill type as
-- their SECOND positional argument, so the delta is measured from storage.fillLevels either way, with no
-- dependence on what the remaining arguments mean). DR's own writes are excluded by the _selfWrite guard
-- set in setLevel and around the whole hourly pass. Positive delta -> loaded, negative -> unloaded, so
-- one hook covers both directions and it does not matter which trigger produced the change: player
-- trailer, bale, AI helper or another mod all read as manual movement.
--
-- Server-side only, like every other ledger here. Deltas land in a pending buffer (they happen BETWEEN
-- hourly passes, when cycleAcc is nil) and are folded into the cycle ledger by flushManualTransfers.
-- ============================================================================
SmartDistribution._manualPending = {}      -- uid -> ft -> { loaded, unloaded }, drained each cycle
SmartDistribution._manualOwner   = {}      -- uid -> placeable, so the flush can classify inputs vs outputs

-- storage -> owning placeable. Rebuilt only when the placeable count changes; the lookup is on a
-- per-frame path while a trigger is filling, so it must not rescan. Weak keys: a demolished building's
-- storages must not be pinned in memory.
SmartDistribution._soMap   = nil
SmartDistribution._soCount = -1
function SmartDistribution.storageOwnerOf(storage)
    if storage == nil then return nil end
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil or ps.placeables == nil then return nil end
    local n = #ps.placeables
    if SmartDistribution._soMap == nil or SmartDistribution._soCount ~= n then
        local map = setmetatable({}, { __mode = "k" })
        for _, p in ipairs(ps.placeables) do
            for _, s in ipairs(getAllStorages(p)) do map[s] = p end
            local pp = getProductionPoint(p)                       -- getAllStorages does not cover pp.storage
            if pp ~= nil and pp.storage ~= nil then map[pp.storage] = p end
        end
        SmartDistribution._soMap   = map
        SmartDistribution._soCount = n
    end
    return SmartDistribution._soMap[storage]
end

function SmartDistribution.recordManualDelta(storage, ft, delta)
    if ft == nil or delta == nil or delta == 0 then return end
    if g_currentMission == nil or not g_currentMission:getIsServer() then return end
    local p = SmartDistribution.storageOwnerOf(storage)
    if p == nil or not isEnrolled(p) then return end
    local uid = getUid(p)
    if uid == nil then return end
    local a = SmartDistribution._manualPending[uid]
    if a == nil then a = {}; SmartDistribution._manualPending[uid] = a end
    SmartDistribution._manualOwner[uid] = p
    local e = a[ft]
    if e == nil then e = { loaded = 0, unloaded = 0 }; a[ft] = e end
    if delta > 0 then e.loaded = e.loaded + delta else e.unloaded = e.unloaded - delta end
end

-- The input / output fill types of a building whose OWN operation moves its storage levels -- i.e. a
-- production or a husbandry. Returns two sets, both empty for a silo / shed / pit / market, which have no
-- internal process and so need no filtering at all. See manualRoleFilter for what they are used for.
function SmartDistribution.internalProcessFillTypes(p)
    local outs, ins = {}, {}
    if p == nil then return outs, ins end
    local pp = getProductionPoint(p)
    if pp ~= nil then
        if type(pp.outputFillTypeIds) == "table" then for f in pairs(pp.outputFillTypeIds) do outs[f] = true end end
        if type(pp.inputFillTypeIds)  == "table" then for f in pairs(pp.inputFillTypeIds)  do ins[f]  = true end end
        for _, def in ipairs(pp.productions or {}) do          -- covers paused / inactive lines too
            for _, o in ipairs(def.outputs or {}) do if o.type ~= nil then outs[o.type] = true end end
            for _, i in ipairs(def.inputs  or {}) do if i.type ~= nil then ins[i.type]  = true end end
        end
        return outs, ins
    end
    if isHusbandryBuilding(p) then
        -- both are defined further down this file; they resolve at call time, long after load
        if SmartDistribution.husbandryOutputSet ~= nil then
            for f in pairs(SmartDistribution.husbandryOutputSet(p)) do outs[f] = true end
        end
        if SmartDistribution.husbandryInputFillTypes ~= nil then
            -- deliberately NOT receiverInputFillTypes: for a silo that returns everything the building can
            -- hold, which would filter out exactly the manual deliveries this feature is here to show
            for f in pairs(SmartDistribution.husbandryInputFillTypes(p)) do ins[f] = true end
        end
    end
    return outs, ins
end

-- Fold the pending manual deltas into this cycle's ledger, keeping only the directions that could
-- actually have been a person.
--
-- A production / husbandry moves its own storage as it works, and those writes are NOT DR's, so they
-- reach the hook looking exactly like a delivery. Netting them off against the cycle's produced /
-- consumed does NOT work: for a PALLETIZED output (flour, bread) DR measures "produced" from pallet
-- levels, not from the storage buffer the production actually fills -- different basis, nothing cancels,
-- and every loaf read as manually loaded into the bakery. So the rule is structural instead:
--   * output going UP              -> the building made it (you cannot tip bread into a bakery)
--   * input going DOWN             -> the building consumed it
--   * palletized output going DOWN -> the vanilla pallet spawner draining the buffer into pallets
-- Everything else survives: anything put IN, and any non-palletized product taken out (milk by tanker,
-- grain from a mill's loading station). Only "manually removing a production's raw input again" is lost,
-- which is rare and genuinely indistinguishable from consumption. A fill type that is both an input and
-- an output of the same building is filtered both ways. Silos / sheds / pits filter nothing -- they have
-- no internal process, so every delta there is real, which is the case this feature is really about.
function SmartDistribution.flushManualTransfers(acc)
    local pend, owner = SmartDistribution._manualPending, SmartDistribution._manualOwner
    SmartDistribution._manualPending, SmartDistribution._manualOwner = {}, {}
    if acc == nil then return end
    for uid, byFt in pairs(pend) do
        local p = owner[uid]
        local outs, ins = SmartDistribution.internalProcessFillTypes(p)     -- resolved once per building
        for ft, e in pairs(byFt) do
            local loaded, unloaded = e.loaded, e.unloaded
            if outs[ft] then
                loaded = 0
                if isPalletizedFillType(ft) then unloaded = 0 end
            end
            if ins[ft] then unloaded = 0 end
            if SmartDistribution.debug and (e.loaded > 0.5 or e.unloaded > 0.5) then
                log("manual %s [%s] raw in=%d out=%d  isOutput=%s isInput=%s pallet=%s -> loaded=%d unloaded=%d",
                    tostring(uid), fillTypeName(ft), e.loaded, e.unloaded,
                    tostring(outs[ft] == true), tostring(ins[ft] == true),
                    tostring(isPalletizedFillType(ft)), loaded, unloaded)
            end
            if loaded > 0.5 or unloaded > 0.5 then
                local a = acc[uid]; if a == nil then a = {}; acc[uid] = a end
                local t = a[ft]
                if t == nil then t = { dist = 0, sold = 0, stored = 0, received = 0 }; a[ft] = t end
                if loaded   > 0.5 then t.loaded   = (t.loaded   or 0) + loaded   end
                if unloaded > 0.5 then t.unloaded = (t.unloaded or 0) + unloaded end
            end
        end
    end
end

-- ---- POOLED OVERFILL CLAMP --------------------------------------------------------------------------
-- THE BASE GAME'S GATE AND ITS WRITE DISAGREE ABOUT A POOLED TANK, and the write wins.
--
--   Storage:getFreeCapacity  -- for a pooled tank (no capacities[ft], supportsMultipleFillTypes) sums
--                               EVERY level: `capacity - sum(fillLevels)`. Correct.
--   Storage:setFillLevel     -- `math.clamp(fillLevel, 0, self.capacities[fillType] or self.capacity)`.
--                               Clamps the incoming product against the WHOLE tank and never looks at
--                               what the others are holding.
--
-- So a fill trigger asks for room, is told the truth, and then writes more than it was granted. It
-- overshoots exactly ONCE per tank -- on the load that straddles the boundary -- and every load after
-- that is refused, because by then the pooled gate reads zero. Reproduced on two buildings 2026-08-20:
--   Farma 400 (400,000): 200k wheat + 400k barley = 600,000 held, third product refused
--   Hay loft  (250,000): 125k hay   + 250k straw  = 375,000 held
-- In both, the second load was written IN FULL rather than trimmed to the space actually left.
--
-- DR ITSELF NEVER DOES THIS -- transfer() clamps `moved` by getFree (the pooled figure) before writing,
-- so this is purely about product arriving from outside DR, i.e. the player's trailer.
--
-- SCOPED THREE WAYS, because this sits on a GLOBAL class hook and 5.62 is the precedent for what that
-- costs (an unscoped refusal there froze the game at a pallet shop):
--   * only a genuinely POOLED storage -- an explicit capacities[ft] means per-product IS the intended
--     rule, and supportsMultipleFillTypes == false is a different model again;
--   * only a DR-ENROLLED building, so nothing outside the farm's network is touched;
--   * only an INCREASE, so a withdrawal can never be blocked.
-- Returns the ceiling this fill type may be written to, or nil for "not our business".
function SmartDistribution.pooledWriteCap(storage, ft)
    if storage == nil or ft == nil then return nil end
    local levels = storage.fillLevels
    if type(levels) ~= "table" then return nil end
    if storage.capacities ~= nil and storage.capacities[ft] ~= nil then return nil end   -- per-ft by design
    if storage.supportsMultipleFillTypes == false then return nil end
    local cap = storage.capacity
    if type(cap) ~= "number" or cap <= 0 then return nil end
    local p = SmartDistribution.storageOwnerOf ~= nil and SmartDistribution.storageOwnerOf(storage) or nil
    if p == nil or not isEnrolled(p) then return nil end
    local others = 0
    for f, lvl in pairs(levels) do
        if f ~= ft then others = others + (lvl or 0) end
    end
    return math.max(0, cap - others)
end

function SmartDistribution.installManualTransferTracking()
    if SmartDistribution._manualTrackingInstalled then return end   -- installing twice would make the hook call itself
    SmartDistribution._manualTrackingInstalled = true
    if Storage == nil then
        log("manual transfer tracking: Storage class not found; Loaded / Unloaded will stay empty [VERIFY]")
        return
    end
    local hooked = {}
    for _, name in ipairs({ "setFillLevel", "addFillLevel" }) do
        if type(Storage[name]) == "function" then
            -- the original goes on SmartDistribution, never into a local (200-local ceiling)
            SmartDistribution["_origStorage" .. name] = Storage[name]
            Storage[name] = function(self, a1, a2, ...)
                local orig = SmartDistribution["_origStorage" .. name]
                -- skip DR's own writes, and measure only at the OUTERMOST hooked frame so a base-game
                -- method that internally calls the other one cannot double-count
                if (SmartDistribution._selfWrite or 0) > 0 or SmartDistribution._inManualHook
                   or self == nil or type(self.fillLevels) ~= "table" or type(a2) ~= "number" then
                    return orig(self, a1, a2, ...)
                end
                -- POOLED OVERFILL CLAMP -- setFillLevel ONLY. Its signature is confirmed from the base
                -- source (fillLevel, fillType, fillInfo), so a1 IS the absolute level and trimming it
                -- here is exact. addFillLevel is deliberately left alone: it does not exist on the base
                -- Storage class at all, so any implementation is a subclass's with an argument order
                -- this cannot read -- and guessing it would corrupt a write rather than bound one.
                -- Runs BEFORE `before` is captured so the tracking below still measures what really
                -- moved, not what was asked for.
                if name == "setFillLevel" and type(a1) == "number" then
                    local ceiling = SmartDistribution.pooledWriteCap(self, a2)
                    if ceiling ~= nil and a1 > ceiling and a1 > (self.fillLevels[a2] or 0) then
                        a1 = math.max(ceiling, self.fillLevels[a2] or 0)   -- never force a level DOWN
                    end
                end
                SmartDistribution._inManualHook = true
                local before = self.fillLevels[a2] or 0
                -- pcall so a throw from the base game still releases the guard (a stuck guard would
                -- silently disable tracking for the rest of the session); the error is re-raised after.
                local rets = { pcall(orig, self, a1, a2, ...) }
                SmartDistribution._inManualHook = false
                if not rets[1] then error(rets[2], 0) end
                pcall(SmartDistribution.recordManualDelta, self, a2, (self.fillLevels[a2] or 0) - before)
                return unpack(rets, 2)
            end
            hooked[#hooked + 1] = name
        end
    end
    if #hooked == 0 then
        log("manual transfer tracking: no Storage write method found; Loaded / Unloaded will stay empty [VERIFY]")
    else
        log("manual transfer tracking installed (Storage." .. table.concat(hooked, ", Storage.") .. ")")
    end
end

-- ---- Overview tab: one ledger accessor for all three timescales -------------
-- Everything the Overview tab shows is read through these three functions, so switching timescale is a
-- single string swap rather than three parallel sets of accessors.
--   window = "hour"  -- the last completed hourly cycle (S.lastCycle)
--          | "month" -- the rolling 24-cycle window (monthlyRing) -- what the /mo columns elsewhere show
--          | "year"  -- the rolling 12-month ring owned by DistributionStats.lua
-- On a multiplayer CLIENT the hourly pass never runs, so each window reads the matching server-pushed
-- aggregate instead; clientMonthly ~= nil remains the "am I a client" flag it has always been.
-- Fields, never top-level locals -- this file is at Lua's 200 main-chunk local ceiling.
function SmartDistribution.windowLedgers(window)
    local out = {}                                    -- array of (uid -> ft -> entry) tables to sum
    local function put(t) if type(t) == "table" then out[#out + 1] = t end end
    if window == "year" then
        if clientMonthly ~= nil then put(SmartDistribution._clientYear)
        elseif SmartDistribution.yearAggregate ~= nil then put(SmartDistribution.yearAggregate()) end
    elseif window == "hour" then
        put(clientMonthly ~= nil and SmartDistribution._clientHour or S.lastCycle)
    else
        if clientMonthly ~= nil then put(clientMonthly)
        else for i = 1, MONTHLY_CYCLES do put(monthlyRing[i]) end end
    end
    return out
end

-- One (asset, product) over one window, as a full entry table -- the per-row accessor the building tabs
-- use for their own Hour / Month / Year selector. Takes a PLACEABLE (the pages hold placeables) and
-- resolves the uid itself; see CLAUDE.md 1.5 on the uid-vs-placeable split in this file's API.
-- Cheap enough for a per-cell call: it sums only this uid+ft across the window's ledgers, rather than
-- flattening the whole ring the way windowAggregate does.
function SmartDistribution.assetWindowStats(p, ft, window)
    return SmartDistribution.uidWindowStats(p ~= nil and getUid(p) or nil, ft, window)
end

-- The same sum keyed by UID. inputLinkStatus only ever holds a uid, and resolving it back to a placeable
-- would walk placeableSystem per row -- exactly the per-row cross-building cost 5.52 removed.
function SmartDistribution.uidWindowStats(uid, ft, window)
    local out = {}
    local fields = SmartDistribution.WINDOW_FIELDS
    for _, f in ipairs(fields) do out[f] = 0 end
    if uid == nil or ft == nil then return out end
    for _, led in ipairs(SmartDistribution.windowLedgers(window)) do
        local a = led[uid]
        local e = a ~= nil and a[ft] or nil
        if type(e) == "table" then
            for _, f in ipairs(fields) do out[f] = out[f] + (e[f] or 0) end
        end
    end
    return out
end

-- The WHOLE window flattened in one pass: uid -> ft -> summed entry
-- { received, loaded, consumed, unloaded, produced, dist, sold, stored, money }. The Overview tab builds
-- a table of hundreds of rows at once, so it resolves the window here rather than re-summing the
-- 24-cycle ring per cell. The key set also tells the tab which (asset, product) pairs saw any activity.
-- `moved` is product that changed CONTAINER inside one building (a tank into its own attached pallet
-- store). Deliberately its own field and NOT folded into `stored`: the tabs sum dist + stored + sold for
-- DISTRIBUTED, and an internal move is not distribution -- counting it there is what reported "20k
-- distributed with no demand". It exists so a LINK STATUS can still see the movement over a window,
-- which the last-pass link log cannot answer beyond the current cycle.
SmartDistribution.WINDOW_FIELDS = { "received", "loaded", "consumed", "unloaded", "produced", "dist", "sold", "stored", "money", "cost", "moved" }

function SmartDistribution.windowAggregate(window)
    local out, fields = {}, SmartDistribution.WINDOW_FIELDS
    for _, led in ipairs(SmartDistribution.windowLedgers(window)) do
        for uid, byFt in pairs(led) do
            if type(byFt) == "table" then
                local au = out[uid]; if au == nil then au = {}; out[uid] = au end
                for ft, e in pairs(byFt) do
                    if type(e) == "table" then
                        local ae = au[ft]
                        if ae == nil then
                            ae = {}
                            for _, f in ipairs(fields) do ae[f] = 0 end
                            au[ft] = ae
                        end
                        for _, f in ipairs(fields) do ae[f] = ae[f] + (e[f] or 0) end
                    end
                end
            end
        end
    end
    return out
end

-- Public enrolment test: the UI holds placeables and isEnrolled is a main-chunk local.
function SmartDistribution.isAssetEnrolled(p)
    return isEnrolled(p)
end

-- a husbandry's full output set: milk / manure / slurry + egg / wool / honey pallets (for the tab).
function SmartDistribution.husbandryOutputSet(p)
    local outs = husbandryOutputFillTypes(p)
    local pfts = palletSpawnerFillTypes(p)
    if pfts ~= nil then for _, ft in ipairs(pfts) do outs[ft] = true end end
    -- husbandryOutputFillTypes() adds the whole manure family (MANURE / LIQUIDMANURE / SLURRY) to every
    -- asset, which is right for a barn but wrong for a pit: a Manure Pit was listing slurry and a Slurry
    -- Pit was listing manure. For the pits (non-barn HEAP assets) keep only what they actually hold.
    if not isHusbandryBuilding(p) then
        for ft in pairs(outputNamedSet()) do
            if outs[ft] and not SmartDistribution.assetHoldsFillType(p, ft) then outs[ft] = nil end
        end
    end
    return outs
end

-- every fill type currently "in the distribution network": an active output of an enrolled production
-- (regardless of current stock), produced by a pallet spawner (coop eggs / wool / honey), or currently
-- held in an enrolled silo / husbandry / shed storage. Used to decide which rows a market shows.
function SmartDistribution.networkFillTypes(farmId)
    local out = {}
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return out end
    for _, p in ipairs(ps.placeables) do
        if SmartDistribution._farmCanUse(p, farmId) and isEnrolled(p) and not SmartDistribution.isMarket(p) then
            local cls = getAssetClass(p)
            if cls == "PRODUCTION" then
                -- outputs of every ENABLED production line (shown even while a line is idle / waiting for input)
                local pp = getProductionPoint(p)
                if pp ~= nil then
                    for _, def in ipairs(getActiveProductionDefs(pp)) do
                        for _, o in ipairs(def.outputs or {}) do if o.type ~= nil then out[o.type] = true end end
                    end
                    -- ...PLUS anything it is actually HOLDING that a configured line outputs. A switched-off
                    -- line leaves real stock behind, and that stock is still distributable / storable /
                    -- sellable -- so a market has to be able to LIST it or there is no row to route it from.
                    --
                    -- Deliberately NOT the full configured-output set, which is the obvious symmetry with
                    -- storePhase / marketTransferPhase above: the Advanced Greenhouse declares TEN lines, so
                    -- that would put all ten crops on every market's tab whether or not the farm has ever
                    -- made one -- the wall-of-empty-rows problem 5.7 exists to avoid. Held stock is the
                    -- evidence that the product is genuinely in the network.
                    --
                    -- Gated on the OUTPUT set rather than sweeping pp.storage, because a production's buffer
                    -- holds its INPUTS too: a bakery stocking flour would otherwise advertise FLOUR as
                    -- something the network can supply a market with.
                    if pp.storage ~= nil then
                        for ft in pairs(SmartDistribution.configuredOutputFillTypes(pp)) do
                            if getLevel(pp.storage, ft) > 0 then out[ft] = true end
                        end
                    end
                end
            elseif cls == "HUSBANDRY" then
                -- husbandries always generate their outputs: milk / manure + egg / wool / honey pallets (shown regardless of stock)
                for ft in pairs(husbandryOutputFillTypes(p)) do out[ft] = true end
                local pfts = palletSpawnerFillTypes(p)
                if pfts ~= nil then for _, ft in ipairs(pfts) do out[ft] = true end end
            else
                -- SILO / SHED / HEAP / OTHER: only what is currently stored (grain in silos, pallets in the warehouse)
                for _, storage in ipairs(getAllStorages(p)) do
                    for ft in pairs(storageFillTypes(storage)) do
                        if getLevel(storage, ft) > 0 then out[ft] = true end
                    end
                end
                if p.spec_objectStorage ~= nil then
                    for ft in pairs(shedStoredFillTypes(p)) do out[ft] = true end
                end
            end
        end
    end
    return out
end

-- fill types a market's tab shows: currently buffered, active this month (received/sold), or in the
-- distribution network (produced or held) AND supported by this market.
function SmartDistribution.marketMenuFillTypes(market)
    local out = {}
    if market == nil then return out end
    local uid = getUid(market)
    local buf = SmartDistribution._marketBuffer[uid]
    if buf ~= nil then for ft, v in pairs(buf) do if v ~= nil and v > 0 then out[ft] = true end end end   -- stock the market is currently holding
    local farmId = (market.getOwnerFarmId and market:getOwnerFarmId()) or market.ownerFarmId
    for ft in pairs(SmartDistribution.networkFillTypes(farmId)) do
        if SmartDistribution.marketAccepts(market, ft) then out[ft] = true end
    end
    return out
end

function SmartDistribution.enumerateConfigurableAssets()
    local out = {}
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return out end
    local farmId = (g_currentMission.getFarmId ~= nil) and g_currentMission:getFarmId() or nil
    for _, p in ipairs(ps.placeables) do
        if p.rootNode ~= nil then
            -- ownership PLUS public map storage. This is the enumerator the four building tabs
            -- actually call -- enrolledAssets is a different list -- so gating only that one left
            -- the feature invisible in the UI however correct the engine side was.
            if SmartDistribution._farmCanUse(p, farmId) then
                -- ONE ROW PER ROLE. A building that does two jobs at once appears once per job, each
                -- with its own key, its own products and its own modes -- so a DriveIn is a silo on the
                -- Silos tab, a pallet store beside it, and a one-line production on Productions.
                -- `class` stays the role so every existing tab filter (allow[a.class],
                -- a.class == "PRODUCTION") keeps working untouched.
                --
                -- CONSUMERS THAT MUST NOT SEE THE EXTRA ROWS: the Overview builds its whole table from
                -- this list, and one row per BUILDING is what it wants -- roles do not change what
                -- flowed. It filters on isPrimaryRole; see enrolledAssetsWithUniqueNames.
                local roles = SmartDistribution.assetRoles(p)
                local base  = placeableName(p)
                local orig  = SmartDistribution.placeableRenamedFrom(p)
                local primary = roles[1]
                for _, cls in ipairs(roles) do
                    if cls == "SILO" or cls == "HUSBANDRY" or cls == "PRODUCTION" or cls == "SHED"
                       or cls == "HEAP" or cls == "MARKET" then
                        out[#out + 1] = {
                            placeable = p, class = cls, role = cls,
                            isPrimaryRole = (cls == primary),
                            roleUid  = SmartDistribution.roleUid(p, cls),
                            name     = SmartDistribution.roleDisplayName(p, cls, base, #roles),
                            baseName = base,
                            origName = orig,
                        }
                    end
                end
            end
        end
    end
    table.sort(out, function(a, b)
        if a.class ~= b.class then return a.class < b.class end
        return a.name < b.name
    end)
    return out
end

function SmartDistribution.onOpenManagerAction(self, actionName, inputValue)
    SmartDistribution.openMenu()
end

-- (the ] help keybind was removed; the User Guide is a tab in the consolidated menu)

-- ---- consolidated menu (TabbedMenu) ----------------------------------------
-- Registered once at mission load (installMenu). Loads the four page frames
-- first -- each under the name its FrameReference in DistributionMenu.xml
-- expects -- then the menu screen itself. Mirrors AutoDrive's ADSettings load.
function SmartDistribution.registerMenuGui()
    if SmartDistribution._menuRegistered then return end
    if g_gui == nil or TabbedMenu == nil or DistributionMenu == nil then
        log("registerMenuGui: g_gui/TabbedMenu/DistributionMenu missing [VERIFY]")
        return
    end
    local dir = SmartDistribution.modDir or ""
    -- Widen the layout on a display wider than 16:9 (6.15). The flag is set around THIS block
    -- only, so the hooks are inert for every other GUI in the game; it is cleared after the
    -- pcall so a load error cannot leave it stuck on and silently widen the base-game menus.
    SmartDistribution.installLayoutWidening()
    local widenF = SmartDistribution.layoutScaleX()
    SmartDistribution._layoutScaling = (widenF > 1)
    local ok, err = pcall(function()
        g_gui:loadProfiles(dir .. "gui/DistributionSiloProfiles.xml")
        local function loadPage(cls, guiName, xml)
            if cls == nil then return end
            local inst = cls.new()
            g_gui:loadGui(dir .. xml, guiName, inst, true)
        end
        loadPage(DistributionSettingsPage,    "distributionSettingsPage",    "gui/DistributionSettingsPage.xml")
        loadPage(DistributionStoragePage,         "distributionStoragePage",     "gui/DistributionStoragePage.xml")
        loadPage(DistributionAnimalHusbandryPage, "distributionHusbandryPage",   "gui/DistributionHusbandryPage.xml")
        loadPage(DistributionMarketsPage,         "distributionMarketsPage",     "gui/DistributionMarketsPage.xml")
        loadPage(DistributionProductionsPage, "distributionProductionsPage", "gui/DistributionProductionsPage.xml")
        loadPage(DistributionOverviewPage,    "distributionOverviewPage",    "gui/DistributionOverviewPage.xml")
        loadPage(DistributionHelpPage,        "distributionHelpPage",        "gui/DistributionHelpPage.xml")
        -- DistributionMenu.xml is pure CHROME -- the left tab strip, the footer button bar and the
        -- background -- and carries no DR table layout at all. Widening it stretched the tab icons
        -- (reported: the strip itself grew by exactly the widen factor) and wasted screen width on a
        -- sidebar that has a fixed job. Excluded wholesale, which is both simpler and more correct
        -- than blacklisting each icon profile inside it.
        SmartDistribution._layoutScaling = false
        SmartDistribution._menu = DistributionMenu.new()
        g_gui:loadGui(dir .. "gui/DistributionMenu.xml", "DistributionMenu", SmartDistribution._menu)
        -- ...but the DIALOGS are DR content and do want the extra width.
        SmartDistribution._layoutScaling = (widenF > 1)
        if DistributionSpawnDialog ~= nil then
            SmartDistribution._spawnDialog = DistributionSpawnDialog.new()
            g_gui:loadGui(dir .. "gui/DistributionSpawnDialog.xml", "DistributionSpawnDialog", SmartDistribution._spawnDialog)
        end
        if DistributionAdvancedDialog ~= nil then
            SmartDistribution._advDialog = DistributionAdvancedDialog.new()
            g_gui:loadGui(dir .. "gui/DistributionAdvancedDialog.xml", "DistributionAdvancedDialog", SmartDistribution._advDialog)
        end
        if DistributionInputsDialog ~= nil then
            SmartDistribution._inputsDialog = DistributionInputsDialog.new()
            g_gui:loadGui(dir .. "gui/DistributionInputsDialog.xml", "DistributionInputsDialog", SmartDistribution._inputsDialog)
        end
    end)
    SmartDistribution._layoutScaling = false
    if ok then
        SmartDistribution._menuRegistered = true
        log("consolidated menu registered")
        -- Let extension mods add their own tabs now the menu exists. Fired HERE
        -- rather than left to the mods themselves because a mod appending to
        -- loadMission00Finished may well run BEFORE this function does (mods load
        -- alphabetically), so it cannot know when the menu became available.
        -- pcall'd per callback inside fireMenuReady: a mod's tab must never take
        -- DR's own menu down with it.
        if SmartDistribution.fireMenuReady ~= nil then
            pcall(SmartDistribution.fireMenuReady, SmartDistribution._menu)
        end
        if widenF > 1 then
            print(string.format("[SmartDistribution] layout widened x%.3f for a %.2f:1 display (g_aspectScaleX=%.4f); widest table %.3f -> %.3f of screen width",
                widenF, (type(g_screenWidth) == "number" and type(g_screenHeight) == "number" and g_screenHeight > 0)
                        and (g_screenWidth / g_screenHeight) or 0, g_aspectScaleX or 1,
                ((SmartDistribution.LAYOUT_DESIGN_WIDTH or 1480) / 1920) * (g_aspectScaleX or 1),
                SmartDistribution.LAYOUT_TARGET_WIDTH or 0))
        end
    else
        log("registerMenuGui error: %s", tostring(err))
    end
end

-- Open the Advanced window (granular routing) for a building.
function SmartDistribution.openAdvancedDialog(asset, ft, role)
    if g_gui == nil or SmartDistribution._advDialog == nil or asset == nil or ft == nil then return false end
    SmartDistribution._advDialog:setup(asset, ft, role)
    g_gui:showDialog("DistributionAdvancedDialog")
    return true
end

-- Open the Advanced Inputs window (receiver-side block + per-product max %) for a building.
function SmartDistribution.openInputsDialog(asset, role)
    if g_gui == nil or asset == nil then return false end
    if SmartDistribution._inputsDialog == nil then
        log("openInputsDialog: dialog not registered (needs a full game restart after adding DistributionInputsDialog)")
        return false
    end
    SmartDistribution._inputsDialog:setup(asset, role)
    g_gui:showDialog("DistributionInputsDialog")
    return true
end

-- Rows for the Advanced Inputs dialog: one per input product the building can receive, carrying its
-- pooled/individual classification, block state, effective max %, and the live litre equivalent so the
-- UI can show "50%  (125,000 L)". Pooled products are grouped; the caller renders a pooled section and
-- an individual section.
-- `role` addresses ONE HALF of a building that does two jobs. Its blocks and caps are stored under that
-- half's own key, so blocking wheat on a DriveIn's pallet store no longer blocks it on the silo beside it.
function SmartDistribution.receiverInputRows(p, role)   -- role-scoped: see storageTypeLabel
    local rows = {}
    if p == nil then return rows end
    -- keyed per row below (settingUid), not once here: a LINKED product shares the silo's entry
    local pool = SmartDistribution.pooledInputCapacity(p, role)
    local poolSet = {}
    if pool ~= nil then for _, ft in ipairs(pool.fts) do poolSet[ft] = true end end
    -- WITH THE ROLE, or the dialog lists the wrong half's inputs: on the Mechet Fromage's PALLET STORE
    -- row this showed the production's three milk inputs instead of what the store accepts.
    for ft in pairs(SmartDistribution.receiverInputFillTypes(p, role)) do
        local pooled = poolSet[ft] == true
        local cap = SmartDistribution.inputProductCapacity(p, ft, role)
        local pct = SmartDistribution.inputCapPct(p, ft, role)
        rows[#rows + 1] = {
            ft = ft,
            -- LINKED: this product is one pool of stock the silo and the in-building production share,
            -- so its setting is a single setting seen from two tabs. Shown in the storage-type column
            -- so the sharing is visible rather than something the player has to deduce from behaviour.
            linked = SmartDistribution.sharedTankFillTypes(p)[ft] == true,
            name = fillTypeName(ft),   -- dialog re-resolves the display title from ft; this is a fallback
            pooled = pooled,
            blocked = (function()
                local u = SmartDistribution.settingUid(p, ft, role)
                return u ~= nil and SmartDistribution.isInputBlocked(u, ft) or false
            end)(),
            pct = pct,
            capLiters = cap,
            -- MAX IN: exactly what the percentage means -- that share of the building's total capacity.
            -- 50% of a 75,000 L silo is 37,500 L; 100% is 75,000 L. It used to carry
            -- inputEffectiveMaxLiters, the ELASTIC "what could still fit given what the others hold", which
            -- paired a cap percentage with a number that was not that percentage of anything: a 75,000 L
            -- silo holding 60,000 L of other crops displayed "100%  (15,000 L)" and read as broken.
            -- The elastic figure is still shown -- as its own AVAILABLE column below, where it is honest.
            maxLiters = cap * (pct / 100),
            -- AVAILABLE: how many more litres of this product the building will actually accept right now.
            -- This is the enforcement figure the allocator itself clamps every delivery to, so the column
            -- cannot disagree with what DR then does. It is the smaller of "this product's own ceiling minus
            -- what it already holds" and "the space the other products have left free" -- e.g. a 75,000 L
            -- silo with 25,000 L used shows 7,500 at Max 10%, and 50,000 at Max 100%.
            -- nil when unconstrained: inputAcceptableLiters returns INF for a building whose capacity
            -- cannot be resolved, and "inf L" in a column is worse than an honest dash.
            availLiters = (function()
                local a = SmartDistribution.inputAcceptableLiters(p, ft)
                if type(a) ~= "number" or a ~= a or a >= INF then return nil end
                return a
            end)(),
            held = SmartDistribution.inputHeldLevel(p, ft, role),   -- this half's held, not the placeable's
            explicit = (function()
                local u = SmartDistribution.settingUid(p, ft, role)
                return u ~= nil and SmartDistribution.hasExplicitInputCapPct(u, ft) or false
            end)(),
            -- `targetApplies` is what the dialog renders on: a push-only receiver gets a dash rather than
            -- "Off", because "Off" implies it could be switched ON. See fillTargetApplies.
            targetApplies = SmartDistribution.fillTargetApplies(p, ft, role),
            targetPct = (function()
                if not SmartDistribution.fillTargetApplies(p, ft, role) then return nil end
                local u = SmartDistribution.settingUid(p, ft, role)
                return u ~= nil and SmartDistribution.getInputTargetPct(u, ft) or nil
            end)(),
            targetLiters = SmartDistribution.fillTargetApplies(p, ft, role)
                and SmartDistribution.inputTargetLiters(p, ft, role) or nil,
        }
    end
    -- Feeding-robot barn: append a READ-ONLY row for the internal mixed-feed / food level (the robot mixes
    -- the bunkers into this and feeds the herd from it; shown for reference only, not settable).
    if SmartDistribution.feedingRobotOf(p) ~= nil and p.spec_husbandryFood ~= nil then
        local fs = p.spec_husbandryFood
        local held = 0
        if type(fs.fillLevels) == "table" then for _, lvl in pairs(fs.fillLevels) do held = held + (lvl or 0) end end
        rows[#rows + 1] = {
            ft = 0, name = "Mixed feed", readOnly = true, pooled = false, blocked = false,
            pct = 100, capLiters = fs.capacity or 0, maxLiters = fs.capacity or 0, held = held,
        }
    end
    table.sort(rows, function(a, b)
        if (a.readOnly or false) ~= (b.readOnly or false) then return not a.readOnly end   -- read-only rows last
        if a.pooled ~= b.pooled then return a.pooled end   -- then pooled products first
        return tostring(a.name) < tostring(b.name)
    end)
    return rows, (pool ~= nil and pool.liters or nil)
end

-- Which input products a building can receive (for the Advanced Inputs dialog). Productions use their
-- input fill types; husbandries use husbandryInputFillTypes; storage/sheds use their supported fts.
-- The fill types a building supports through its OWN storages -- excluding anything a folded EXTENSION
-- brings with it.
--
-- AN EXTENSION ADDS SPACE, NOT PRODUCTS (author's rule, 2026-08-06). The reported case: a valid 200,000 L
-- extension from a mod pack supports 113 fill types, so folding it into a 10-crop Farma 400 made the silo
-- advertise Cement Brick, Cheese, Chocolate and Clothes as things it could receive. The extra SPACE is
-- legitimate and is still counted; the extra PRODUCTS are not, because the silo itself cannot hold them and
-- DR would route them there.
--
-- This is also what makes the Advanced Inputs dialog agree with the building page again: the page has
-- always read the building's own storages (siloFillTypes), and now so does the dialog.
function SmartDistribution.ownStorageFillTypes(p)
    local out = {}
    if p == nil then return out end
    local silo = p.spec_silo
    if silo ~= nil and type(silo.storages) == "table" then
        for _, s in ipairs(silo.storages) do
            for ft in pairs(storageFillTypes(s)) do out[ft] = true end
        end
    end
    -- a pass-through store's tank is its OWN storage in every sense that matters here: it is what the
    -- building can hold, and what receiverInputFillTypes must offer once the production branch is skipped
    local ptStore = SmartDistribution.passThroughStorage(p)
    if ptStore ~= nil then
        for ft in pairs(storageFillTypes(ptStore)) do out[ft] = true end
    end
    -- a bulk hall bay lists only the crop currently piled there under fillTypes, so prefer its supported set
    for _, s in ipairs(SmartDistribution.bulkHallStorages(p)) do
        local sup = s.supportedFillTypes or storageFillTypes(s)
        for ft in pairs(sup) do out[ft] = true end
    end
    local h = p.spec_husbandry
    if h ~= nil then
        if h.storage ~= nil then for ft in pairs(storageFillTypes(h.storage)) do out[ft] = true end end
        if type(h.storages) == "table" then
            for _, s in ipairs(h.storages) do for ft in pairs(storageFillTypes(s)) do out[ft] = true end end
        end
    end
    local pp = getProductionPoint(p)
    if pp ~= nil and pp.storage ~= nil then
        for ft in pairs(storageFillTypes(pp.storage)) do out[ft] = true end
    end
    local heap = manureHeapStorage(p)
    if heap ~= nil then for ft in pairs(storageFillTypes(heap)) do out[ft] = true end end
    return out
end

-- Is `ft` reachable ONLY through a folded-in extension -- i.e. a product the silo itself cannot hold,
-- offered to it purely because a neighbouring extension placeable happens to support it?
--
-- This is the ENGINE half of 5.54. Filtering the Advanced Inputs list (ownStorageFillTypes, above) stops
-- DR ADVERTISING Cement Brick on a Farma 400, but on its own it leaves every routing path still willing
-- to PUT it there: canAccept (the distribute sink gate), getSinkStorages (Store), _bulkStorageFor
-- (Move To) and assetProducts (the tab + Overview product list) all sweep getAllStorages, which folds the
-- extension in by design. A display-only fix would have been the worst of both worlds -- product moving
-- somewhere the UI denies is even possible.
--
-- DELIBERATELY RESTRICTED TO `spec_silo`, and that restriction is load-bearing: 5.29c folds a
-- supplementary Water Tank into a GREENHOUSE, and a production's own WATER capacity may live entirely in
-- that tank rather than in pp.storage. A blanket rule would read WATER as "extension-only" and cut the
-- greenhouse off from its own water supply. Manure-heap extensions are untouched too -- they come through
-- parentPitExtensionStorages, which this never consults.
--
-- Returns false for any silo with no folded extension at all (the overwhelming majority), so it cannot
-- change behaviour on a farm this bug never affected.
-- MEMOISED per placeable, and it has to be: canAccept is on the allocator's per-candidate hot path and
-- sinksFor walks every placeable, while assetProducts asks once per fill type -- so the uncached form is
-- O(F) table building inside an O(A x F) loop, the exact shape 5.46 had to unpick. The memo returns a SET
-- so the per-ft question is one lookup.
--
-- Like the POOL memo (and unlike the pad / share ones) this deliberately does NOT take the memoReadable
-- guard, so it is live inside the hourly pass too -- where canAccept needs it. Same justification: what it
-- caches is STRUCTURE (which tanks are folded in, and which products each supports), not a LEVEL, so it
-- cannot go stale as a tank fills during a fast-forward. Extensions attaching or detaching bump the epoch.
function SmartDistribution.extensionOnlyFillTypes(p)
    if p == nil or p.spec_silo == nil then return nil end
    local now = SmartDistribution.memoNow()
    local m = SmartDistribution._extOnlyMemo[p]
    if m ~= nil and m.epoch == SmartDistribution._memoEpoch and (now - m.at) < SmartDistribution.MEMO_TTL then
        return m.set
    end
    local set = nil
    local ext = parentExtensionStorages(p)
    if #ext > 0 then
        -- storageSupports answers from fillTypes OR capacities OR fillLevels, so enumerate all three or
        -- the two would disagree about the same tank. Applied to BOTH sides on purpose, and the direction
        -- matters: a wider OWN set can only ever let a product through (the pre-fix behaviour), while a
        -- narrower one would BLOCK something the silo really holds -- much the worse failure.
        local function union(s, into)
            for _, k in ipairs({ "fillTypes", "capacities", "fillLevels" }) do
                local t = s[k]
                if type(t) == "table" then for ft in pairs(t) do into[ft] = true end end
            end
        end
        local own = {}
        for ft in pairs(SmartDistribution.ownStorageFillTypes(p)) do own[ft] = true end
        if type(p.spec_silo.storages) == "table" then
            for _, s in ipairs(p.spec_silo.storages) do union(s, own) end
        end
        for _, s in ipairs(SmartDistribution.bulkHallStorages(p)) do union(s, own) end
        local extFts = {}
        for _, s in ipairs(ext) do union(s, extFts) end
        for ft in pairs(extFts) do
            if own[ft] == nil then
                if set == nil then set = {} end
                set[ft] = true
            end
        end
    end
    SmartDistribution._extOnlyMemo[p] = { set = set, at = now, epoch = SmartDistribution._memoEpoch }
    return set
end

function SmartDistribution.isExtensionOnlyFillType(p, ft)
    if p == nil or ft == nil or p.spec_silo == nil then return false end
    local set = SmartDistribution.extensionOnlyFillTypes(p)
    return set ~= nil and set[ft] == true
end

function SmartDistribution.receiverInputFillTypes(p, role)
    local out = {}
    if p == nil then return out end
    -- The PRODUCTION half of a shared-tank building takes its OWN line inputs -- not the tank's whole
    -- crop list. The pass-through guard further down skips the production branch (it exists so the SILO
    -- half lists the tank), and without this the production's Advanced Inputs offered all 111 products.
    if role == "PRODUCTION" and SmartDistribution.treatPassThroughAsStore(p) then
        local pp = getProductionPoint(p)
        if pp ~= nil then
            for _, def in ipairs(SmartDistribution.configuredProductionLines(pp)) do
                for _, i in ipairs(def.inputs or {}) do if i.type ~= nil then out[i.type] = true end end
            end
            return out
        end
    end
    -- the SHED half of a dual building accepts what a pallet store accepts, not what its tank holds
    if role == "SHED" and p.spec_objectStorage ~= nil and SmartDistribution.shedSupportedFillTypes ~= nil then
        for ft in pairs(SmartDistribution.shedSupportedFillTypes(p)) do out[ft] = true end
        return out
    end
    -- A PASS-THROUGH STORE RECEIVES AS A SILO, not as a production. Taking the branch below would list
    -- only its surviving REAL line's inputs (SILAGE on the DriveIn), so Advanced Inputs would offer one
    -- row out of 111 and inputAcceptableLiters would answer for a building that supposedly accepts
    -- nothing else. Skipping it drops through to the ownStorageFillTypes sweep at the tail, which is the
    -- right answer for a store: everything it can hold, exactly as for any silo.
    local pp = getProductionPoint(p)
    if pp ~= nil and not SmartDistribution.treatPassThroughAsStore(p) then
        for _, def in ipairs(getActiveProductionDefs(pp)) do
            for _, i in ipairs(def.inputs or {}) do if i.type ~= nil then out[i.type] = true end end
        end
        -- include configured (not just active) lines so the player can pre-set caps
        for _, def in ipairs(SmartDistribution.configuredProductionLines(pp)) do
            for _, i in ipairs(def.inputs or {}) do if i.type ~= nil then out[i.type] = true end end
        end
        return out
    end
    if isHusbandryBuilding(p) and SmartDistribution.husbandryInputFillTypes ~= nil then
        for ft in pairs(SmartDistribution.husbandryInputFillTypes(p)) do out[ft] = true end
        return out
    end
    -- MARKET. It owns no Storage at all -- its stock is DR's virtual _marketBuffer (5.31) -- so the
    -- getAllStorages sweep below returned {}, the Advanced Inputs button self-hid, and there was no way to
    -- say which products a market may accept. A market is a PURE receiver (it never feeds the network back,
    -- 5.7), so this is the one advanced dialog it genuinely needs.
    if SmartDistribution.isMarket ~= nil and SmartDistribution.isMarket(p) then
        for ft in pairs(SmartDistribution.marketMenuFillTypes(p)) do out[ft] = true end
        return out
    end
    -- ONE ANSWER FOR A STORAGE ROLE, shared with the building tab.
    --
    -- This function and assetMenuFillTypes both mean "what products does this thing take in", and both
    -- had grown their own branch stack -- production / husbandry / market / shed / own-storage -- so
    -- every rule had to be added to BOTH and they drifted three times in two days: siloFillTypes not
    -- knowing about pass-throughs, the production-output exclusion, and the pallet store's cheeses
    -- appearing in the SILO's Advanced Inputs while its own table correctly showed none.
    --
    -- For a role backed by real storage the tab's answer IS the right answer, so take it rather than
    -- rebuild it. The branches above stay separate because they are genuinely different questions: a
    -- production RECEIVES its inputs and DISPLAYS its outputs, and a market has no storage at all.
    if role == "SILO" or role == "SHED" or role == "HEAP" then
        local fts = SmartDistribution.assetMenuFillTypes(p, role)
        if type(fts) == "table" then for ft in pairs(fts) do out[ft] = true end end
        return out
    end
    -- storage / sheds (no role named -- the allocator's union view): everything the building can hold
    if p.spec_objectStorage ~= nil and SmartDistribution.shedSupportedFillTypes ~= nil then
        for ft in pairs(SmartDistribution.shedSupportedFillTypes(p)) do out[ft] = true end
    end
    -- OWN storages only: a folded extension contributes SPACE, never new products (see ownStorageFillTypes).
    -- This used to sweep getAllStorages, which is why a silo with a 113-product extension attached listed
    -- 113 incoming products here while its building page correctly showed 10.
    for ft in pairs(SmartDistribution.ownStorageFillTypes(p)) do out[ft] = true end
    -- LAST, after every branch above has added its products: a genuine line's OUTPUT belongs to the
    -- production and is listed on its tab only. The tab rows already exclude it (assetMenuFillTypes);
    -- without the same rule here the SILO's Advanced Inputs dialog went on offering it, so the product
    -- was hidden in one place and configurable in another.
    if role ~= "PRODUCTION" and SmartDistribution.productionOwnedFillTypes ~= nil then
        for ft in pairs(SmartDistribution.productionOwnedFillTypes(p)) do out[ft] = nil end
    end
    return out
end

-- Should the Advanced button be offered for this (asset, ft)? Only when the output's mode routes
-- somewhere the player can configure -- i.e. it distributes, stores, or supplies a market (incl. combos).
-- Sell / Hold / Hold Internal / Market-less setups have nothing to arrange, so no button.
function SmartDistribution.modeConfigurable(asset, ft, role)
    if asset == nil or ft == nil then return false end
    -- A SEALED BUNKER HAS NO OUTPUT TO CONFIGURE: its mode cannot act until the heap is
    -- opened, so no Advanced Outputs route exists for it (a Distribute pre-set just waits).
    if SmartDistribution.isBunkerSiloPlaceable ~= nil and SmartDistribution.bunkerStage ~= nil
        and SmartDistribution.isBunkerSiloPlaceable(asset)
        and (SmartDistribution.bunkerStage(asset) == "filling"
        or SmartDistribution.bunkerStage(asset) == "fermenting"
        or SmartDistribution.bunkerStage(asset) == "fermented") then
            return false
    end

    local pp = getProductionPoint(asset)
    -- usesVMode, NOT `pp ~= nil` -- THE FIFTH SITE OF THAT FAULT, and the one with the worst symptom.
    -- On a pass-through store a TANK product has no v-mode, so this resolved a stale/derived one, decided
    -- the mode was not configurable, and HID the Advanced Outputs button. Because the tab writes the ASSET
    -- mode while this read the v-mode, no amount of changing the mode brought it back -- reported
    -- 2026-08-20 as "the button disappears and doesn't come back regardless of what i set the mode to".
    if pp ~= nil and role ~= "SHED" and SmartDistribution.usesVMode(asset, ft) then
        local v = SmartDistribution.productionOutputVMode ~= nil and SmartDistribution.productionOutputVMode(pp, ft) or nil
        return v == 1 or v == 3 or v == 4 or v == 5 or v == 6 or v == 7   -- dist / dist+sell / dist+store / store / market / dist+market
    end
    local m = SmartDistribution.resolvedAssetMode(asset, ft, role)
    local M = MODE
    if SmartDistribution.modeDistributes(m) then return true end
    return m == M.STORE or m == M.STORE_TO
        or m == M.TRANSFER_MARKET
end

-- Open the manual pallet-spawn pop-up for a production output. onConfirm(option, count) is invoked
-- when the player presses Spawn. Returns true if the dialog was shown.
function SmartDistribution.openSpawnDialog(placeable, ft, onConfirm)
    if g_gui == nil or SmartDistribution._spawnDialog == nil or ft == nil then return false end
    local pp = getProductionPoint(placeable)
    if pp ~= nil then
        local held = (pp.getFillLevel ~= nil and pp:getFillLevel(ft)) or 0
        SmartDistribution._spawnDialog:setup(pp, ft, held, onConfirm)
    elseif placeable ~= nil and placeable.spec_husbandryPallets ~= nil then
        local held = SmartDistribution.palletPendingLiters(placeable, ft)
        SmartDistribution._spawnDialog:setupHusbandry(placeable, ft, held, onConfirm)
    else
        return false
    end
    g_gui:showDialog("DistributionSpawnDialog")
    return true
end

-- open (or toggle) the consolidated menu; falls back to the old manager list if
-- the menu failed to register for any reason.
function SmartDistribution.openMenu()
    if SmartDistribution._menu == nil then
        SmartDistribution.notify("Distribution menu isn't ready yet")
        return
    end
    if SmartDistribution._menu.isOpen then
        pcall(function() SmartDistribution._menu:onClickBack() end)
    elseif g_gui ~= nil and not g_gui:getIsGuiVisible() then
        g_gui:showGui("DistributionMenu")
    end
end

-- ---------------------------------------------------------------------------
-- THE MENU KEY IN A VEHICLE. Requested 2026-08-26: players wanted the DR menu reachable without getting
-- out. It was never deliberately blocked -- installInteraction registers only into
-- PlayerInputComponent.INPUT_CONTEXT_NAME, so entering a vehicle switches context and DR's actions
-- simply are not part of it.
--
-- Vehicle:registerActionEvents is the mirror image of the player one and is appended to the same way.
-- Read from source, not assumed: it opens Vehicle.INPUT_CONTEXT_NAME itself and calls
-- endActionEventsModification BEFORE returning, so an appended call lands OUTSIDE that scope and has to
-- re-open it -- exactly the caveat installInteraction already documents for the player component.
--
-- ONLY THE MENU KEY (backslash). The other action, "Configure distribution" (left bracket), resolves the
-- building the player is LOOKING AT from the on-foot camera; in a vehicle that reference is not the
-- player's, so it would act on the wrong building or on nothing. It stays on foot until it is worth
-- giving it a vehicle-aware target.
--
-- NO KEYBIND CONFLICT, checked rather than assumed: the base game's own keyboard defaults
-- (profileTemplate/inputBindingDefault_KeyboardMouse.xml) bind NONE of the bracket or backslash keys, so
-- nothing in the vehicle context wants this one.
--
-- REGISTERED ONLY FOR THE VEHICLE THE PLAYER IS ACTUALLY OPERATING. This runs for every vehicle that
-- re-registers its events, so without the isActiveForInput gate every vehicle on the map would add its
-- own copy of the action.
-- A FIELD, not a `local function`: the main chunk sits at the 200-local ceiling and adding one here
-- tipped it straight over ("too many local variables (limit is 200) in main function"), which is a
-- FATAL compile error -- the whole mod fails to load (CLAUDE.md 1.1). luac -p caught it before a restart.
function SmartDistribution.installVehicleInteraction()
    if Vehicle == nil or Vehicle.registerActionEvents == nil then
        log("Vehicle.registerActionEvents not found [VERIFY]")
        return
    end
    Vehicle.registerActionEvents = Utils.appendedFunction(
        Vehicle.registerActionEvents,
        function(self, ...)
            if self == nil or g_inputBinding == nil or InputAction == nil then return end
            if InputAction.DISTREDUX_OPEN_MANAGER == nil then return end
            -- the controlled vehicle only; `true` ignores which implement is SELECTED, so the key works
            -- whatever the player currently has highlighted
            local okA, active = pcall(self.getIsActiveForInput, self, true)
            if not okA or not active then return end
            g_inputBinding:beginActionEventsModification(Vehicle.INPUT_CONTEXT_NAME)
            local ok, _, eventId = pcall(g_inputBinding.registerActionEvent, g_inputBinding,
                InputAction.DISTREDUX_OPEN_MANAGER, self, SmartDistribution.onOpenManagerAction,
                false, true, false, true, nil, true)
            if ok and eventId ~= nil then
                pcall(function()
                    g_inputBinding:setActionEventText(eventId,
                        SmartDistribution.l10n("dr_input_openManager", "Distribution menu"))
                    -- hidden in the vehicle's input help: that panel is already crowded with the
                    -- vehicle's own actions, and the key still works. Flip to true if players ask.
                    g_inputBinding:setActionEventTextVisibility(eventId, false)
                end)
            else
                print("[SmartDistribution] vehicle manager register FAILED [VERIFY]: " .. tostring(eventId))
            end
            g_inputBinding:endActionEventsModification()
        end)
    log("menu key installed for the vehicle context")
end

-- register the key in the player's on-foot context. registerActionEvents re-runs
-- on every context setup; target is the player component (self) so the event is
-- cleaned up with the player's own events on teardown - no duplicate/leak.
local function installInteraction()
    if PlayerInputComponent == nil or PlayerInputComponent.registerActionEvents == nil then
        log("PlayerInputComponent.registerActionEvents not found [VERIFY]")
        return
    end
    PlayerInputComponent.registerActionEvents = Utils.appendedFunction(
        PlayerInputComponent.registerActionEvents,
        function(self, ...)
            -- vanilla returns early for non-owning players; mirror that so we
            -- don't register a stray event for remote players in MP.
            if self == nil or self.player == nil or not self.player.isOwner then return end
            if g_inputBinding == nil or InputAction == nil then
                print("[SmartDistribution] input: g_inputBinding/InputAction missing [VERIFY]")
                return
            end
            -- CRITICAL: registerActionEvents() ends its own modification scope
            -- before returning, so an appended call lands OUTSIDE the player
            -- context. Re-open the SAME context for our registration, then end it.
            local ctx = PlayerInputComponent.INPUT_CONTEXT_NAME
            g_inputBinding:beginActionEventsModification(ctx)
            -- [ "Configure distribution": registered HIDDEN; the proximity watcher reveals it in the
            -- top-left input help only while a configurable asset is the current on-foot target.
            -- (The old right-bracket "cycle all" key is gone -- that lives on a dialog button now.)
            SmartDistribution._dialogEventId = nil
            if InputAction.DISTREDUX_OPEN_DIALOG ~= nil then
                local ok2, _, eventId2 = pcall(g_inputBinding.registerActionEvent, g_inputBinding,
                    InputAction.DISTREDUX_OPEN_DIALOG, self, SmartDistribution.onOpenDialogAction,
                    false, true, false, true, nil, true)
                if ok2 and eventId2 ~= nil then
                    SmartDistribution._dialogEventId = eventId2
                    pcall(function()
                        g_inputBinding:setActionEventText(eventId2, "Configure distribution")
                        g_inputBinding:setActionEventTextVisibility(eventId2, false)
                        g_inputBinding:setActionEventActive(eventId2, false)
                    end)
                    log("dialog action registered hidden (eventId=%s)", tostring(eventId2))
                else
                    print("[SmartDistribution] dialog register FAILED [VERIFY]: " .. tostring(eventId2))
                end
            end
            -- third key: open the authoritative manager list
            if InputAction.DISTREDUX_OPEN_MANAGER ~= nil then
                local ok3, _, eventId3 = pcall(g_inputBinding.registerActionEvent, g_inputBinding,
                    InputAction.DISTREDUX_OPEN_MANAGER, self, SmartDistribution.onOpenManagerAction,
                    false, true, false, true, nil, true)
                if ok3 and eventId3 ~= nil then
                    pcall(function()
                        g_inputBinding:setActionEventText(eventId3, SmartDistribution.l10n("dr_input_openManager", "Distribution menu"))
                        g_inputBinding:setActionEventTextVisibility(eventId3, true)
                    end)
                    log("manager action registered (eventId=%s)", tostring(eventId3))
                else
                    print("[SmartDistribution] manager register FAILED [VERIFY]: " .. tostring(eventId3))
                end
            end
            g_inputBinding:endActionEventsModification()
        end)
    log("cycle interaction installed (player on-foot context)")
end

-- ---- husbandry manure storage patch ----------------------------------------
-- Vanilla barns (spec_husbandry) ship with NO manure storage slot, so manure
-- has nowhere to accumulate. Add a MANURE capacity to each barn's storage so it
-- can be held, distributed and sold. Gated on cur==0 so it is idempotent and
-- coexists with any other mod doing the same (e.g. legacy PDNE).
local MANURE_STORAGE_CAPACITY = 50000

-- Register a grazing pasture's own <husbandry><storage> into its husbandry unloading/loading stations, so the
-- MANURE capacity patchHusbandryManureStorage put on it is actually seen by getHusbandryCapacity() and the
-- vanilla straw->manure conversion can deposit there. The FS25_GrazingPasture mod never registers this storage
-- (it wires the Animal Feeder in for straw instead), which is why a plain cap patch is invisible on a pasture
-- but works on a barn. We use the mod's own storageSystem:addStorageTo*Station API. Made MANURE-ONLY (every
-- other fill-type cap on the storage zeroed) so registering it cannot alter the mod's feeder-based straw math
-- -- only manure ever lands here. A SmartDistribution.* field, never a top-level local (200-local ceiling).
function SmartDistribution.registerPastureManureStorage(placeable, manureFT)
    local spec = placeable ~= nil and placeable.spec_husbandry or nil
    local storage = spec ~= nil and spec.storage or nil
    local ss = g_currentMission ~= nil and g_currentMission.storageSystem or nil
    if storage == nil or ss == nil or manureFT == nil then return end
    if ss.addStorageToUnloadingStation == nil or ss.addStorageToLoadingStation == nil then return end
    -- manure-only: drop every other fill type so this storage contributes nothing but manure to the husbandry
    if storage.capacities ~= nil then
        for ft in pairs(storage.capacities) do
            if ft ~= manureFT then storage.capacities[ft] = 0 end
        end
    end
    -- Mark it as the pasture's OWN manure sink so the extension-attach refusal (which blocks EXTERNAL manure
    -- heaps/pits from attaching to a pasture) lets this one through -- otherwise our own guard would refuse
    -- the very registration we are doing here, since the storage now holds manure and the owner is a pasture.
    storage._sdPastureManure = true
    local un = spec.unloadingStation
    if un ~= nil and not (un.targetStorages ~= nil and un.targetStorages[storage] ~= nil) then
        pcall(function() ss:addStorageToUnloadingStation(storage, un) end)
    end
    local ln = spec.loadingStation
    if ln ~= nil and not (ln.sourceStorages ~= nil and ln.sourceStorages[storage] ~= nil) then
        pcall(function() ss:addStorageToLoadingStation(storage, ln) end)
    end
end

local function patchHusbandryManureStorage(placeable)
    if placeable == nil or placeable.spec_husbandry == nil then return end
    if placeable.spec_manureHeap ~= nil then return end          -- already has a heap
    if not SmartDistribution.husbandryProducesManure(placeable) then return end   -- egg-only coops make no manure -> no slot
    -- A grazing pasture (FS25_GrazingPasture) declares MANURE capacity 0 exactly like a vanilla barn and
    -- converts straw bedding to manure, so it earns the storage slot on the normal path below -- no pasture
    -- special-case here. (Standalone manure heaps are still kept off the pasture by the extension-attach
    -- refusal in installExtensionBlock, so this slot only ever holds the pasture's own straw-derived manure.)
    local manureFT = g_fillTypeManager ~= nil and
        g_fillTypeManager:getFillTypeIndexByName("MANURE") or nil
    if manureFT == nil or manureFT <= 0 then return end
    local storages = {}
    if placeable.spec_silo ~= nil and placeable.spec_silo.storages ~= nil then
        for _, s in ipairs(placeable.spec_silo.storages) do storages[#storages + 1] = s end
    end
    if placeable.spec_husbandry.storage ~= nil then
        storages[#storages + 1] = placeable.spec_husbandry.storage
    end
    for _, storage in ipairs(storages) do
        local cur = (storage.capacities ~= nil and storage.capacities[manureFT]) or 0
        if cur == 0 then
            storage.capacities = storage.capacities or {}
            storage.capacities[manureFT] = MANURE_STORAGE_CAPACITY
            storage.fillLevels = storage.fillLevels or {}
            if storage.fillLevels[manureFT] == nil then storage.fillLevels[manureFT] = 0 end
            -- The base game initialises THREE tables in lockstep whenever a fill type joins a Storage
            -- (Storage.lua:124-126: fillLevels / fillLevelsLastSynced / fillLevelsLastPublished).
            -- Creating only fillLevels makes Storage:setFillLevel THROW on the server: its guard at
            -- line 423 tests fillLevels[ft] ~= nil and passes, then line 437 reads
            -- fillLevelsLastSynced[ft] unguarded -> "attempt to perform arithmetic (sub) on nil and
            -- number", every frame thereafter (nothing heals it -- writeStream/writeUpdateStream, the
            -- only other writers, iterate sortedFillTypes, which we do not touch).
            -- HARMLESS ON A BARN THAT DECLARES MANURE AT ALL, even at capacity="0": that declaration
            -- puts it in the storage's fillTypes set, so the base game already made all three. It only
            -- bites a manure-producing pen whose <storage> never mentions MANURE -- which is why it
            -- went unseen for months and then surfaced on a farm full of modded pasture pens.
            storage.fillLevelsLastSynced = storage.fillLevelsLastSynced or {}
            if storage.fillLevelsLastSynced[manureFT] == nil then storage.fillLevelsLastSynced[manureFT] = 0 end
            storage.fillLevelsLastPublished = storage.fillLevelsLastPublished or {}
            if storage.fillLevelsLastPublished[manureFT] == nil then storage.fillLevelsLastPublished[manureFT] = 0 end
            -- ...and into the SUPPORTED-TYPE set, or the patched manure never leaves this machine.
            -- All four Storage stream functions walk sortedFillTypes (Storage.lua:238 readStream,
            -- 254 writeStream, 272 readUpdateStream, 292 writeUpdateStream), so a fill type missing
            -- from it is simply never transmitted: a CLIENT's barn would read 0 manure for ever, and
            -- getIsFillTypeSupported (line 392, which answers from fillTypes) would deny it too.
            --
            -- SAFE IN MP BECAUSE BOTH ENDS COMPUTE THE SAME SET, and that is the load-bearing claim
            -- here -- sortedFillTypes is the WIRE LAYOUT, so a set that differed between server and
            -- client would desync the bit stream outright, not merely mis-report a number. This patch
            -- is appended to PlaceableHusbandry.onPostLoad / onFinalizePlacement with no isServer
            -- guard, and every input it reads (the husbandry specs; the storage's declared
            -- capacities) comes from the placeable XML -- identical on both machines -- so the two
            -- ends add MANURE to the same storages and sort it into the same position.
            --
            -- A barn that DECLARES MANURE (even at capacity="0") already has it in fillTypes, so this
            -- whole block is skipped and the common case is byte-for-byte unchanged.
            storage.fillTypes = storage.fillTypes or {}
            if storage.fillTypes[manureFT] ~= true then
                storage.fillTypes[manureFT] = true
                storage.sortedFillTypes = storage.sortedFillTypes or {}
                storage.sortedFillTypes[#storage.sortedFillTypes + 1] = manureFT
                table.sort(storage.sortedFillTypes)   -- the base game sorts this (Storage.lua:128);
                                                      -- both ends must agree on ORDER, not just membership
            end
            if storage._sdManurePatch == nil then
                storage._sdManurePatch = true
                if storage.capacity ~= nil then
                    storage.capacity = storage.capacity + MANURE_STORAGE_CAPACITY
                end
            end
        end
    end
    -- A grazing pasture (FS25_GrazingPasture) does NOT register its own <husbandry><storage> into its
    -- husbandry stations -- the mod routes fill types through external linked placeables (feeder for straw)
    -- instead -- so the MANURE capacity we just set above is invisible to getHusbandryCapacity() and the
    -- vanilla straw->manure conversion has nowhere to deposit (manure discarded). A barn, by contrast, DOES
    -- register its own storage, which is why the same patch works there. Register the pasture's own storage
    -- into its husbandry stations (the exact mechanism the pasture mod uses for feeders/troughs/heaps) so it
    -- becomes a real, self-contained manure sink -- no manure heap required. Manure-only: see the helper.
    if SmartDistribution.isGrazingPasture(placeable) then
        SmartDistribution.registerPastureManureStorage(placeable, manureFT)
    end
end

local function installHusbandryPatch()
    local function safePatch(self) pcall(patchHusbandryManureStorage, self) end
    if PlaceableHusbandry ~= nil and PlaceableHusbandry.onFinalizePlacement ~= nil then
        PlaceableHusbandry.onFinalizePlacement =
            Utils.appendedFunction(PlaceableHusbandry.onFinalizePlacement,
                function(self) safePatch(self) end)
        if PlaceableHusbandry.onPostLoad ~= nil then
            PlaceableHusbandry.onPostLoad =
                Utils.appendedFunction(PlaceableHusbandry.onPostLoad,
                    function(self) safePatch(self) end)
        end
        log("husbandry manure-storage patch installed")
    elseif Placeable ~= nil and Placeable.onFinalizePlacement ~= nil then
        Placeable.onFinalizePlacement =
            Utils.appendedFunction(Placeable.onFinalizePlacement,
                function(self) if self.spec_husbandry ~= nil then safePatch(self) end end)
        if Placeable.onPostLoad ~= nil then
            Placeable.onPostLoad =
                Utils.appendedFunction(Placeable.onPostLoad,
                    function(self) if self.spec_husbandry ~= nil then safePatch(self) end end)
        end
        log("husbandry manure-storage patch installed (Placeable fallback)")
    else
        print("[SmartDistribution] husbandry manure-storage patch SKIPPED [VERIFY]: no hook point")
    end
end

-- exposed for the per-asset dialog (Stage H2)
SmartDistribution.husbandryOutputFillTypes = husbandryOutputFillTypes

-- ---- in-world prompt visibility --------------------------------------------
-- The "[ Configure distribution" entry in the top-left input help is shown ONLY
-- while a configurable asset is the current on-foot target (recomputed a few times
-- a second). There is no separate HUD box -- the prompt lives in the standard input
-- help list like every other binding. We toggle the action event's text visibility +
-- active state on the id stashed by installInteraction; a context re-registration
-- (vehicle enter/exit, etc.) hands us a fresh id, so we re-assert on the next tick.
-- ============================================================================
--  PLACEMENT DEFAULTS -- the defaultOutputMode / defaultInputMode settings
--
--  These stamp an EXPLICIT per-product choice onto a building at the moment it is PLACED, and do
--  nothing else, ever. They are deliberately NOT resolver defaults, and the difference is the entire
--  requirement:
--    * changing either setting must never disturb a building that already exists;
--    * loading an existing savegame under a new version must change nothing whatsoever.
--  Both fall out of stamping rather than resolving -- there is no code path here by which an existing
--  building is ever revisited. It is also why defaultOutputMode is NOT wired to `S.global.mode`: every
--  unconfigured building in the world resolves through that (see resolveMode), so pointing the setting
--  at it would rewrite the whole farm the moment it was flipped. S.global.mode stays MODE.DISTRIBUTE.
--
--  TELLING A NEW BUILDING FROM A LOADED ONE is the only hard part, because both arrive through
--  finalizePlacement. The primary test is the placeable's OWN `isLoadedFromSavegame`, which the base
--  game sets immediately before calling finalizePlacement (Placeable.lua, verified) -- a per-placeable
--  fact that assumes nothing about ordering. `isPreplaced` covers the map's own buildings.
--
--  `_worldLoaded` is kept as a second, weaker guard, but it CANNOT be relied on alone and the claim it
--  used to carry here -- "every placeable in a savegame finalizes BEFORE that fires" -- was WRONG.
--  Placeable loading is asynchronous, so loadMission00Finished fires while buildings are still streaming
--  in, and everything that finalized afterwards was stamped as newly built. See queuePlacementStamp for
--  the reproduction; it cost a live farm every input block it had.
--
--  DEFERRED BY ONE TICK, DELIBERATELY. The stamp needs the building's fill types, and at finalize time
--  a modded production point's spec_* may not be populated yet -- the load-order hazard that
--  _uncachedProductionPoint exists for (5.29 / 5.54). Reading it a moment too early would stamp an
--  empty or partial product list, which is unrecoverable because the building then looks "already
--  stamped". So the placeable is queued and handled on the next proximityWatcher tick.
--
--  SERVER-ONLY, replicated through the EXISTING events (DistributionModeEvent via applyAssetMode,
--  DistributionControlEvent INPUT_BLOCK). A client must never stamp -- placeables stream in on join and
--  it would write its own copies over server state, the 5.49 failure shape. No new event type is
--  introduced and ACT_NUM_BITS is untouched.
-- ============================================================================
SmartDistribution._worldLoaded = false
SmartDistribution._stampQueue  = nil

-- Called from the placement hook. Cheap and allocation-free until something is actually placed.
function SmartDistribution.queuePlacementStamp(p)
    if p == nil then return end
    -- THE LATCH IS NOT ENOUGH, AND ITS STATED ASSUMPTION IS FALSE. The header below claimed "every
    -- placeable in a savegame finalizes BEFORE loadMission00Finished fires". Placeable loading is
    -- ASYNCHRONOUS, so that hook fires while buildings are still streaming in -- and every one that
    -- finalized after it was stamped as though the player had just built it.
    --
    -- Reported 2026-08-20 and reproduced exactly: set the input default to Block all, existing buildings
    -- correctly unchanged, place a new building and it is correctly blocked -- then SAVE, EXIT, RELOAD and
    -- "most buildings" came back with every input blocked. MOST, not all, is the async fingerprint: the
    -- ones that happened to finalize before the latch rose were spared. It showed up on the INPUT default
    -- and not the output one only because of the guards further down -- an already-configured output is
    -- skipped and most buildings have one, while almost nothing has an input block, so nearly every
    -- building was eligible.
    --
    -- THE FIX IS A PER-PLACEABLE FACT, not a global latch, so no ordering has to be assumed.
    -- Placeable.lua (34% blank = complete) sets the flag immediately BEFORE calling finalizePlacement:
    --     self.isLoadedFromSavegame = true
    --     ...
    --     if self.isLoadedFromSavegame then self:finalizePlacement() end
    -- so it is guaranteed true at the moment this hook runs for a loaded building, and it is initialised
    -- false (line 237) for a freshly placed one. isPreplaced covers the map's own buildings on a new game.
    if p.isLoadedFromSavegame or p.isPreplaced then return end
    if not SmartDistribution._worldLoaded then return end
    -- SERVER ONLY. NOTE this is deliberately NOT `S.master` -- that flag is initialised true and is
    -- never set false anywhere, so it means "the mod is active", not "I am the server". Using it here
    -- would let every CLIENT stamp its own copies as placeables stream in on join.
    if g_currentMission == nil or not g_currentMission:getIsServer() then return end
    local g = S.global or {}
    -- Nothing to do at the defaults, so do not even queue: with the output setting on Distribute an
    -- unstamped product already resolves to Distribute through S.global.mode, and with the input
    -- setting on Accept all an absent block already means "not blocked". Writing explicit entries for
    -- either would be behaviourally identical and would only bloat the savegame.
    local wantHold  = (g.defaultOutputMode == 1)
    local wantBlock = (g.defaultInputMode == 1)
    if not wantHold and not wantBlock then return end
    SmartDistribution._stampQueue = SmartDistribution._stampQueue or {}
    SmartDistribution._stampQueue[#SmartDistribution._stampQueue + 1] = p
end

-- Stamp ONE building. Safe to call twice: every write is guarded on the product being unconfigured,
-- so a queued placeable that somehow arrives here again cannot overwrite a choice the player has
-- since made.
function SmartDistribution.stampPlacementDefaults(p)
    if p == nil then return end
    if g_currentMission == nil or not g_currentMission:getIsServer() then return end   -- see queuePlacementStamp
    local uid = getUid(p)
    if uid == nil then return end
    local g = S.global or {}
    local modes, blocks = 0, 0

    if g.defaultOutputMode == 1 then
        -- MODE.HOLD, never MODE.HOLD_INTERNAL. One value covers every building because the LABEL
        -- adapts (holdLabelFlag): "Hold Pallets" on a pallet output, "Hold Internal" once pallet
        -- spawning is Never, plain "Hold" otherwise. Stamping HOLD_INTERNAL to get that third label
        -- would pin the building to a mode cycleNext DROPS from the ring in Never mode -- the player
        -- could cycle away from it but never back.
        local fts = SmartDistribution.assetMenuFillTypes(p)
        for ft in pairs(fts or {}) do
            if SmartDistribution.getAssetMode(uid, ft) == MODE.INHERIT then
                SmartDistribution.applyAssetMode(p, ft, MODE.HOLD)   -- sets + replicates
                modes = modes + 1
            end
        end
    end

    -- INPUTS. Only stamped while Advanced routing is ON, and that is not a limitation being papered
    -- over -- it is the honest behaviour. isInputBlocked returns false without it and
    -- clearAdvancedControl EMPTIES the whole input-block table whenever the switch goes off, so blocks
    -- written with Advanced off are guaranteed to be wiped at the next apply(). Writing them anyway
    -- would leave state that silently evaporates. The tooltip says so.
    if g.defaultInputMode == 1 and SmartDistribution.advancedEnabled() then
        local ins = SmartDistribution.receiverInputFillTypes(p)
        for ft in pairs(ins or {}) do
            if not SmartDistribution.isInputBlocked(uid, ft) then
                if DistributionControlEvent ~= nil and DistributionControlEvent.send ~= nil then
                    -- send() applies locally AND broadcasts, so this is the whole job in one call
                    DistributionControlEvent.send(DistributionControlEvent.ACT.INPUT_BLOCK, uid, ft, "", 0, true)
                else
                    SmartDistribution.setInputBlocked(uid, ft, true)   -- singleplayer fallback
                end
                blocks = blocks + 1
            end
        end
    end

    -- A PRODUCTION caches its v-mode in VTAB, and a DERIVED entry cached before this stamp would keep
    -- showing the old default (5.50). Dropping the provisional entries makes it re-derive and pick the
    -- explicit mode up; an entry the player set explicitly is untouched by this call, which is the
    -- distinction VSEED exists for.
    if modes > 0 and SmartDistribution.invalidateSeededVModes ~= nil then
        pcall(SmartDistribution.invalidateSeededVModes)
    end

    if (modes > 0 or blocks > 0) then
        log("placement defaults stamped on %s: %d output mode(s), %d input block(s)",
            tostring(placeableName(p)), modes, blocks)
    end
end

-- Hooks the GENERIC Placeable class, so every building kind is covered by one append -- silos, pens,
-- productions, sheds and anything modded alike. Appended (never overwritten), and the queue call is
-- itself latch-gated and server-gated, so during a load and on a client this costs one nil test.
--
-- IT IS `finalizePlacement`, NOT `onFinalizePlacement`, and the difference is not cosmetic.
-- `onFinalizePlacement` is a SPECIALIZATION EVENT: Placeable.lua registers it with
-- SpecializationUtil.registerEvent and RAISES it (line 754), so it exists on spec tables like
-- PlaceableHusbandry but is nil on the base Placeable class. Hooking it there installs nothing --
-- which is exactly what happened on the first build, and is why the husbandry patch further up this
-- file reaches for PlaceableHusbandry.onFinalizePlacement first and only falls back to Placeable
-- (a fallback that, on this evidence, has never actually run).
-- `Placeable:finalizePlacement()` is the real base method and runs for EVERY placeable, on a
-- savegame load as well as a fresh placement -- the latch is what separates those two.
-- Appending puts us after both raised events, so every specialization is initialised by then.
function SmartDistribution.installPlacementDefaults()
    if Placeable == nil or Placeable.finalizePlacement == nil then
        print("[SmartDistribution] placement defaults NOT installed -- Placeable.finalizePlacement missing")
        return
    end
    -- GUARD ON THE CLASS, not on SmartDistribution: the mod chunk re-runs on every mission load (two
    -- "hook installed" lines appear in a single launch's log), so a field on our own table resets with
    -- it and the append would stack -- one extra queue call per placement per load since launch.
    if Placeable._drPlacementHooked then
        print("[SmartDistribution] placement defaults hook already installed (re-load); not re-appending")
        return
    end
    Placeable._drPlacementHooked = true
    Placeable.finalizePlacement = Utils.appendedFunction(
        Placeable.finalizePlacement,
        function(self) pcall(SmartDistribution.queuePlacementStamp, self) end)
    -- print, not log(): log() is debug-gated and silent in a release build, so a SUCCESSFUL install
    -- left no trace at all. Only the failure was visible, which is half a diagnostic.
    print("[SmartDistribution] placement defaults hook installed (Placeable.finalizePlacement)")
end

-- Report any stored override whose building no longer exists -- genuine, silent data loss, and the thing
-- that distinguishes "the setting was lost" from "the routing is wrong" when a report comes in.
--
-- DEFERRED to the first update tick, because PLACEABLE LOADING IS ASYNCHRONOUS (6.19). Run inside
-- loadOverrides it fired while buildings were still streaming in, so the live map was short and EVERY
-- override was reported as lost -- on savegame4 all three, including uniqueIds demonstrably present in
-- placeables.xml. It only ever printed, so nothing was pruned, but the message is alarming and was wrong.
--
-- A bare print, not gated on debug: this IS data loss when it is real, and it prints nothing at all when
-- everything resolves. A role key (uid#shed) resolves through baseUidOf to the same building as its base.
function SmartDistribution.runOrphanCheck()
    if not SmartDistribution._pendingOrphanCheck then return end
    SmartDistribution._pendingOrphanCheck = nil
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return end
    local live = {}
    for _, p in ipairs(ps.placeables or {}) do
        if p.rootNode ~= nil then
            local u = getUid(p)
            if u ~= nil then live[u] = p end
        end
    end
    for uid, byFt in pairs(S.assets) do
        if live[SmartDistribution.baseUidOf(uid)] == nil then
            local names = {}
            for ft in pairs(byFt) do names[#names + 1] = tostring(fillTypeName(ft)) end
            print(string.format(
                "[SmartDistribution persist] ORPHANED override: uniqueId=%s matches no live building (%s) -- this setting cannot appear in game",
                tostring(uid), table.concat(names, ", ")))
        end
    end
end

-- Drained from proximityWatcher:update, one tick after placement.
function SmartDistribution.flushPlacementStamps()
    local q = SmartDistribution._stampQueue
    if q == nil then return end
    SmartDistribution._stampQueue = nil
    for _, p in ipairs(q) do pcall(SmartDistribution.stampPlacementDefaults, p) end
end

local proximityWatcher = { acc = 0, target = nil, lastNear = nil, lastEid = nil }

function proximityWatcher:update(dt)
    SmartDistribution.flushPendingSummary()      -- emit the slept-through summary the moment fast-forward stops
    -- One tick after a building was placed, stamp its default output mode / input blocks. Deferred to
    -- here (rather than done inside onFinalizePlacement) so the building's specs are fully populated
    -- before its fill types are read -- see the header above stampPlacementDefaults.
    if SmartDistribution._stampQueue ~= nil then SmartDistribution.flushPlacementStamps() end
    if SmartDistribution._pendingOrphanCheck then SmartDistribution.runOrphanCheck() end
    -- Same first-tick deferral, same reason (6.19): at load the GUI is not necessarily up, and a
    -- dialog raised into a half-built screen either does not appear or appears behind everything.
    if DistributionModWarning ~= nil and DistributionModWarning.showIfNeeded ~= nil then
        pcall(DistributionModWarning.showIfNeeded)
    end
    -- Run an hourly pass deferred from onHourChanged (normal play). We wait one update
    -- tick first, so the engine's hour-change processing -- including producers depositing
    -- this hour's batch in a listener that runs after ours -- has completed; the store pass
    -- then empties the source the instant the batch appears instead of a hour later.
    if SmartDistribution._pendingHourly ~= nil then
        if (SmartDistribution._pendingHourlyWait or 0) > 0 then
            SmartDistribution._pendingHourlyWait = SmartDistribution._pendingHourlyWait - 1
        else
            local pm = SmartDistribution._pendingHourly
            SmartDistribution._pendingHourly = nil
            local ok, err = pcall(SmartDistribution.runHourly, pm)
            if not ok and Logging ~= nil then
                Logging.error("[SmartDistribution] deferred hourly pass failed: %s", tostring(err))
            end
        end
    end

    dt = dt or 0
    self.acc = self.acc + dt
    if self.acc >= 300 then                     -- recompute target ~3 Hz (the scan is the costly part)
        self.acc = 0
        local ok, t = pcall(SmartDistribution.findNearestConfigurableAsset)
        self.target = ok and t or nil
        -- Keep each suppressed pen's own base-game figures live for its vanilla UI. Here rather than in the
        -- updatePallets override because DR's override is what stops that function running (see
        -- syncAllPenFillLevels); this tick is guaranteed, and 3 Hz is already the cadence for a costly scan.
        if SmartDistribution.syncAllPenFillLevels ~= nil then
            pcall(SmartDistribution.syncAllPenFillLevels)
        end
    end

    local eid = SmartDistribution._dialogEventId
    if eid == nil or g_inputBinding == nil then return end
    if eid ~= self.lastEid then self.lastEid = eid; self.lastNear = nil end   -- re-registered: re-assert
    local near = self.target ~= nil
    if near ~= self.lastNear then
        self.lastNear = near
        pcall(function()
            g_inputBinding:setActionEventTextVisibility(eid, near)
            g_inputBinding:setActionEventActive(eid, near)
        end)
    end
end

-- ---- detach manure heaps from barns (un-merge the shared manure pool) -------
-- A "Manure Heap Extension" registers its storage onto nearby barns' UNLOADING stations (base game,
-- from BOTH sides: the heap's onFinalizePlacement AND the barn's own in-range re-scan).
-- getHusbandryCapacity/FillLevel sum that unloading station's target storages, so the heap gets merged
-- into the barn's manure pool (the user saw cap 8.05M = barn 50k + two 4M heaps).  The Liquidmanure
-- Tank stays separate only because it isn't an extension.  To make each heap a SEPARATE storage like
-- the tank, remove the heap's storage from those barn unloading stations after placement/load.  A heap
-- has NO unloading station of its own (only a loadingStation for trailers), so heap.unloadingStations
-- holds only barn links -- removing them can't break the heap's own trailer loading.  Result: the barn's
-- 50k patch and the heap each store manure independently; the pen's storage/station/animals are untouched.
local function detachManureHeap(p)
    if p == nil or p.spec_manureHeap == nil then return end
    local heap = p.spec_manureHeap.manureHeap
    if heap == nil then return end
    local ss = g_currentMission ~= nil and g_currentMission.storageSystem or nil
    if ss == nil or ss.removeStorageFromUnloadingStations == nil then return end
    if type(heap.unloadingStations) == "table" and next(heap.unloadingStations) ~= nil then
        pcall(function() ss:removeStorageFromUnloadingStations(heap, heap.unloadingStations) end)
    end
end

local function detachAllManureHeaps()
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return end
    for _, p in ipairs(ps.placeables) do
        if p.spec_manureHeap ~= nil then detachManureHeap(p) end
    end
end
SmartDistribution._detachAllManureHeaps = detachAllManureHeaps  -- exposed for harness

-- Free the manure-heap EXTENSION from its needsBarn placement gate so it can be placed near a Manure
-- Pit (or anywhere) like the slurry extension, and remember it via sdManureExt so it folds into a Pit
-- rather than being treated as its own Pit.  Fires at load; idempotent across reloads (the XML re-supplies
-- needsBarn=true each time).  The standalone Pit (needsBarn=false) is left untouched.
local function neutralizeManureExtension(self)
    local spec = self ~= nil and self.spec_manureHeap or nil
    if spec == nil then return end
    if spec.needsBarn == true then
        spec.sdManureExt = true
        spec.needsBarn = false
    end
end
local function installManureExtensionPlaceable()
    if PlaceableManureHeap == nil then return end
    local hooked = false
    if PlaceableManureHeap.onLoad ~= nil then
        PlaceableManureHeap.onLoad = Utils.appendedFunction(PlaceableManureHeap.onLoad,
            function(self) pcall(neutralizeManureExtension, self) end)
        hooked = true
    end
    if PlaceableManureHeap.onPostLoad ~= nil then
        PlaceableManureHeap.onPostLoad = Utils.appendedFunction(PlaceableManureHeap.onPostLoad,
            function(self) pcall(neutralizeManureExtension, self) end)
        hooked = true
    end
    if hooked then print("[SmartDistribution] manure-extension freed from needsBarn") end
end

-- Hard placement gates via getCanBePlacedAt (the base placement-validity method both extension types
-- override).  Manure extension: must sit next to a Manure Heap (Pit) or placement is refused.  Slurry
-- extension: its "...next to a barn" message is reworded to "...next to a Slurry Pit".  Grain extension
-- is left alone (it already reads "...next to a silo").
local function installExtensionPlacementGates()
    if PlaceableManureHeap ~= nil and PlaceableManureHeap.getCanBePlacedAt ~= nil then
        PlaceableManureHeap.getCanBePlacedAt = Utils.overwrittenFunction(PlaceableManureHeap.getCanBePlacedAt,
            function(self, superFunc, ...)
                local canPlace, warning = superFunc(self, ...)
                local spec = self.spec_manureHeap
                if spec ~= nil and spec.sdManureExt == true and canPlace == true then
                    local x, y, z = ...
                    if type(x) ~= "number" or type(z) ~= "number" then
                        if self.rootNode ~= nil then x, y, z = getWorldTranslation(self.rootNode) end
                    end
                    if not manurePitInRange(x, z) then
                        return false, "A Manure Heap Extension needs to be placed near a manure heap."
                    end
                end
                return canPlace, warning
            end)
    end
    if PlaceableSiloExtension ~= nil and PlaceableSiloExtension.getCanBePlacedAt ~= nil then
        PlaceableSiloExtension.getCanBePlacedAt = Utils.overwrittenFunction(PlaceableSiloExtension.getCanBePlacedAt,
            function(self, superFunc, ...)
                local canPlace, warning = superFunc(self, ...)
                if canPlace == false and isSlurryExtension(self) then
                    return false, "A slurry pit extension needs to be placed near a slurry pit."
                end
                return canPlace, warning
            end)
    end
    log("extension placement gates installed")
end

local function installManureHeapDetach()
    -- a heap placed near a barn registers onto the barn's unloading station -> detach it, then re-map
    if PlaceableManureHeap ~= nil and PlaceableManureHeap.onFinalizePlacement ~= nil then
        PlaceableManureHeap.onFinalizePlacement = Utils.appendedFunction(
            PlaceableManureHeap.onFinalizePlacement, function(self) pcall(detachManureHeap, self); pcall(rebuildManureExtensionMap) end)
    end
    -- a barn placed near existing heaps re-scans + re-adds them -> sweep them back off
    if PlaceableHusbandry ~= nil and PlaceableHusbandry.onFinalizePlacement ~= nil then
        PlaceableHusbandry.onFinalizePlacement = Utils.appendedFunction(
            PlaceableHusbandry.onFinalizePlacement, function(self) pcall(detachAllManureHeaps) end)
    end
    -- savegame load: after every placeable is finalized, sweep all heaps off all barns + build the map
    if Mission00 ~= nil and Mission00.loadMission00Finished ~= nil then
        Mission00.loadMission00Finished = Utils.appendedFunction(
            Mission00.loadMission00Finished, function(...) pcall(detachAllManureHeaps); pcall(rebuildManureExtensionMap) end)
    end
    log("manure-heap detach installed")
end

local function installProximityWatcher()
    if Mission00 == nil or Mission00.loadMission00Finished == nil then return end
    Mission00.loadMission00Finished = Utils.appendedFunction(
        Mission00.loadMission00Finished,
        function()
            pcall(function()
                if g_currentMission ~= nil and g_currentMission.addUpdateable ~= nil then
                    g_currentMission:addUpdateable(proximityWatcher)
                    log("proximity watcher installed")
                end
            end)
        end)
end

-- Register the consolidated TabbedMenu once, after the mission has finished
-- loading (so g_gui and the base GUI classes are ready).
local function installMenu()
    if Mission00 == nil or Mission00.loadMission00Finished == nil then return end
    Mission00.loadMission00Finished = Utils.appendedFunction(
        Mission00.loadMission00Finished,
        function() pcall(SmartDistribution.registerMenuGui) end)
end

-- ---- rename unlock ---------------------------------------------------------
-- The base game only shows its rename option for placeables whose XML opts in with
-- <base><canBeRenamed>true</canBeRenamed></base> (greenhouses and husbandries do; bunker silos and most
-- storage do not). That flag is just a field on the placeable, so DR flips it on for every building in
-- its network: the player renames from the base-game construction menu, and the name flows back through
-- getName() into DR's lists. No custom rename UI, and the name saves + syncs like any other.
function SmartDistribution.isNetworkAsset(p)
    if p == nil or p.rootNode == nil then return false end
    return SmartDistribution.productionPointOf ~= nil and SmartDistribution.productionPointOf(p) ~= nil
        or p.spec_productionPoint ~= nil
        or p.spec_husbandry ~= nil
        or p.spec_silo ~= nil
        or p.spec_objectStorage ~= nil
        or p.spec_sellingStation ~= nil
end

function SmartDistribution.unlockRename(p)
    if p ~= nil and p.canBeRenamed ~= true and SmartDistribution.isNetworkAsset(p) then
        p.canBeRenamed = true
    end
end

if PlaceableSystem ~= nil and PlaceableSystem.addPlaceable ~= nil then
    PlaceableSystem.addPlaceable = Utils.appendedFunction(PlaceableSystem.addPlaceable, function(_, placeable)
        SmartDistribution.unlockRename(placeable)
    end)
else
    log("rename unlock: PlaceableSystem.addPlaceable not found; renaming left as the base game set it.")
end

-- ---- Hold Internal: suppress vanilla egg / wool / honey pallet spawning -----
-- A pallet-spawner husbandry (chicken coop, sheep barn) set to Hold Internal should keep its product in
-- the building's internal buffer (spec_husbandryPallets.pendingLiters -- NOT `fillLevels`, which this comment
-- used to name: that was vanilla's count of litres already on PALLETS, and DR now writes the full stock into
-- it for the pen's own UI, see syncSpecFillLevels), NOT spawn physical pallets. The base
-- game accumulates output in updateOutput / addPendingLiters and SPAWNS separately in
-- PlaceableHusbandryPallets.updatePallets (confirmed via sdPalletProbe). Overriding updatePallets to
-- no-op while EVERY spawner fill type is HOLD_INTERNAL stops the spawn but leaves accumulation intact --
-- switch the mode back and the accumulated buffer spawns as pallets again. Because the override re-checks
-- the resolved mode on every call it survives save/reload (the prior symptom, Open Item 6.1). The server
-- runs the pallet update, so this replicates in multiplayer. SmartDistribution.* fields, never top-level
-- locals, to respect the 200-local main-chunk ceiling.
--
-- PER-FILL-TYPE, not all-or-nothing. A coop spawns one product (EGG) so a whole-building skip was enough,
-- but a modded sheep barn declares <palletSpawner fillTypes="WOOL GOATMILK"> -- holding WOOL while GOATMILK
-- sells used to fail the "every ft held" test and vanilla spawned BOTH. Partial hold is done by hiding the
-- held fill types from the base function for the duration of one call: swap spec.fillTypes for a filtered
-- array (updatePallets iterates it) and zero the held pendingLiters (in case it works off that instead),
-- then restore. Nothing is discarded -- the buffer is put back exactly as found, plus anything the base
-- function added while it ran.
--
-- Returns held (array of HOLD_INTERNAL fts), remaining (array of the rest).
function SmartDistribution.heldPalletFillTypes(p)
    if p == nil or p.spec_husbandryPallets == nil or not isEnrolled(p) then return nil, nil end
    local fts = palletSpawnerFillTypes(p)
    if fts == nil or #fts == 0 then return nil, nil end
    local held, rest = {}, {}
    for _, ft in ipairs(fts) do
        if resolveMode(p, ft) == MODE.HOLD_INTERNAL then held[#held + 1] = ft else rest[#rest + 1] = ft end
    end
    if #held == 0 then return nil, nil end
    return held, rest
end
-- kept for callers/back-compat: true only when EVERY spawner output is held
function SmartDistribution.shouldHoldPalletsInternal(p)
    local held, rest = SmartDistribution.heldPalletFillTypes(p)
    return held ~= nil and #rest == 0
end

-- Fill types whose VANILLA auto-spawn must be blocked for this call, and the rest. There are now TWO
-- reasons to block, and the mechanics of hiding a fill type from updatePallets are identical for both:
--   * HOLD_INTERNAL      -- never release a pallet at all
--   * "Whole pallets from pens" -- vanilla spawns an EMPTY pallet the moment a pen has any product and
--     then trickles into it; DR releases a FULL one itself (spawnWholePallets) once the buffer holds a
--     pallet's worth, which is how productions already behave.
-- Kept separate from heldPalletFillTypes because that answers "what is the player holding", which the
-- Spawn Pallets button and the held display still need to mean only HOLD_INTERNAL.
function SmartDistribution.suppressedPalletFillTypes(p)
    if p == nil or p.spec_husbandryPallets == nil or not isEnrolled(p) then return nil, nil end
    local fts = palletSpawnerFillTypes(p)
    if fts == nil or #fts == 0 then return nil, nil end
    local whole = S.global.fullPalletSpawn and true or false
    local held, rest = {}, {}
    for _, ft in ipairs(fts) do
        if whole or resolveMode(p, ft) == MODE.HOLD_INTERNAL then held[#held + 1] = ft else rest[#rest + 1] = ft end
    end
    if #held == 0 then return nil, nil end
    return held, rest
end

-- "Whole pallets from pens": with vanilla auto-spawn blocked above, DR is what releases the pallet -- once
-- the internal buffer holds a full one. spawnPalletsFromHusbandry already refuses to spawn below a full
-- pallet's worth and debits pendingLiters in the spawn callback, so this is a threshold check over an
-- already-validated primitive rather than new spawn logic.
--
-- Runs BEFORE the slots are collected, so a pallet released this hour is a source for the same pass and
-- nothing waits an extra cycle to move.
--
-- HOLD_INTERNAL still means hold: DR must not release that buffer either, or the mode would do nothing.
-- The pen's own maxNumPallets limit still applies -- the base spawner refuses beyond it and the buffer
-- simply keeps growing, which is what vanilla does when a pad is full.
-- ---- internal buffer -> pallet shed, as whole pallets ----------------------
-- "Store" on a palletized output whose only destination is a pallet SHED could not move internal stock:
-- a shed holds pallet OBJECTS (depositPalletsToShed requires palletIsFull), so litres sitting in a
-- production's buffer or a pen's queue had no path in. Harmless while pallets spawned by themselves --
-- they became objects and went in -- but with pallet spawning set to NEVER (5.41) nothing ever does, so
-- the product simply accumulated.
--
-- **ALL of it in one cycle: 10,001 L internal with a 1,000 L pallet moves 10 pallets and leaves 1 L.**
-- The count is `floor(stock / capacity)`, bounded only by the shed's free slots -- not by the pad, and
-- not one per pass.
--
-- **A pallet is deposited inside its OWN spawn callback, then the next is requested.** That is what makes
-- the count independent of pad size: only ONE pad slot is ever occupied, for the moment between the
-- pallet loading and it being despawned into the shed. Spawning ten at once would need ten free slots,
-- and a bakery pad holds about five (5.14).
--   * The chain is serial for the same reason spawnPalletsFromProduction already chains serially: each
--     pallet must debit the buffer before the next reads it, or two pallets draw the same litres.
--   * The whole chain therefore completes over a handful of FRAMES (spawnPallet is async in three hops,
--     5.30), not instantly -- but well inside a second of real time, and the litres leave the source as
--     each pallet fills. From the player's side it is "the cycle moved it".
--
-- **Not built by synthesising an abstract stored object**, which would have avoided pallets entirely:
-- `addAbstactObjectToObjectStorage` exists and needs no pallet, and a savegame even names the class
-- ("Vehicle") and its persisted fields -- but every method of that class is stripped from the shipped
-- source (8.1), so the construction contract cannot be read, and a wrong guess would fail at RETRIEVAL,
-- when the player tries to take the pallets back out. See 6.11. Every step here is a path already proven
-- in game: the same spawn helpers the Spawn Pallets button uses, and depositPalletsToShed itself.
--
-- Only runs when pallet spawning is OFF: with it on, product reaches the pad by itself and this would be
-- a second, competing spawn request.
-- A pallet a STORE output cannot store is stranded forever once spawning is off: a pallet shed only takes
-- FULL pallets (depositPalletsToShed -> palletIsFull), and nothing will ever top a partial one up again.
-- So pull what is on it back into the building's own buffer and remove it -- the litres go straight back
-- into the pool the next insert draws from, and the pad clears. An EMPTY pallet is the same case with
-- nothing to reclaim: `drainPallets` only ever deletes what it drains to zero, so one that is already at
-- zero is immortal.
--
-- **STORE only, deliberately.** Distribute and Sell both work off a partial pallet perfectly well
-- (drainPallets takes any level), so reclaiming there would be churn -- and worse, it would fight the
-- 5.40 rule that a partial is drained FIRST.
--
-- Returns litres reclaimed. Nothing is reclaimed into a buffer that has no room for it; the pallet simply
-- stays until there is.
function SmartDistribution.reclaimPartialPallets(p, pp, ft, farmId)
    local reclaimed, toDelete = 0, {}
    for _, pallet in ipairs(husbandryPalletObjects(p, ft)) do
        local idx  = (pallet.spec_pallet ~= nil and pallet.spec_pallet.fillUnitIndex) or 1
        local lvl  = (pallet.getFillUnitFillLevel ~= nil and pallet:getFillUnitFillLevel(idx)) or 0
        if not palletIsFull(pallet, idx, ft) then
            local take = lvl
            if take > 0 then
                if pp ~= nil then take = math.min(take, getFree(pp.storage, ft) or 0) end
                if take > 0 and pallet.addFillUnitFillLevel ~= nil then
                    pallet:addFillUnitFillLevel(farmId, idx, -take, ft, ToolType ~= nil and ToolType.UNDEFINED or nil)
                    SmartDistribution.returnInternal(p, pp, ft, take, farmId)
                    SmartDistribution.noteReclaim(p, ft, take)
                    reclaimed = reclaimed + take
                else
                    take = 0
                end
            end
            if lvl - take <= 0 then toDelete[#toDelete + 1] = pallet end
        end
    end
    for _, pallet in ipairs(toDelete) do
        if pallet.delete ~= nil then pcall(function() pallet:delete() end) end
        local spec = p.spec_husbandryPallets
        if spec ~= nil and type(spec.pallets) == "table" then spec.pallets[pallet] = nil end
    end
    if reclaimed > 0 or #toDelete > 0 then
        if SmartDistribution.debug then
            log("reclaimPartial %s [%s]: %d L back to internal, %d pallet(s) removed",
                placeableName(p), tostring(fillTypeName(ft)), reclaimed, #toDelete)
        end
    end
    return reclaimed
end

function SmartDistribution.stagePalletsForShed(bill)
    if SmartDistribution.palletSpawnAllowed() then return end        -- normal spawning already does this
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return end
    for _, p in ipairs(ps.placeables) do
        local fts = palletSpawnerFillTypes(p)
        if fts ~= nil and isEnrolled(p) and p.rootNode ~= nil then
            local farmId = (p.getOwnerFarmId ~= nil and p:getOwnerFarmId()) or p.ownerFarmId
            for _, ft in ipairs(fts) do
                local m = resolveMode(p, ft)
                if (m == MODE.STORE or m == MODE.DISTRIBUTE_STORE) and not S.global.excludedFillTypes[ft] then
                    local pp = getProductionPoint(p)
                    -- FIRST: pull back any pallet this Store output can never store (partial, or an empty
                    -- one left by an older build). Before the stock read, so the reclaimed litres count
                    -- toward this cycle's pallets rather than waiting for the next.
                    SmartDistribution.reclaimPartialPallets(p, pp, ft, farmId)
                    -- internal stock + one pallet's capacity, per building kind
                    local cap, stock
                    if pp ~= nil then
                        cap   = SmartDistribution.palletCapacityFor(pp, ft) or 0
                        stock = getLevel(pp.storage, ft) or 0
                    elseif p.spec_husbandryPallets ~= nil then
                        cap   = SmartDistribution.palletCapacityForHusbandry(p, ft) or 0
                        stock = SmartDistribution.palletPendingLiters(p, ft) or 0
                    end
                    -- the output reserve is a floor on what may LEAVE, so it gates this too (5.10)
                    if cap ~= nil and cap > 0 and stock ~= nil then
                        stock = SmartDistribution.drawableLevel(p, ft, stock)
                        local want = math.floor(stock / cap)
                        if want > 0 then
                            local shed, d2 = SmartDistribution.shedSinkFor(p, ft, farmId)
                            if shed ~= nil then
                                local room = SmartDistribution.shedFreeSlots(shed)
                                if room > 0 then
                                    local n = math.min(want, room)
                                    if SmartDistribution.debug then
                                        log("stageForShed %s [%s] internal=%.0f cap=%.0f -> %d pallet(s) to %s (room %d)",
                                            placeableName(p), tostring(fillTypeName(ft)), stock, cap, n,
                                            placeableName(shed), room)
                                    end
                                    -- one billable haul for the link, exactly like any other store move
                                    recordBill(bill, farmId, p, shed, d2, ft, n * cap)
                                    -- DIRECT INSERT when enabled: writes the stored objects straight into
                                    -- the shed, so a BLOCKED or full spawn pad is irrelevant and the whole
                                    -- move lands inside this pass (ledger included, no deferral). Falls
                                    -- through to the spawn chain when it is off, or when it inserted
                                    -- nothing -- an empty farm has no stored object to clone from, and
                                    -- spawning one real pallet is the only way to seed the first.
                                    -- BUILT DIRECTLY (6.22). No pallet, no pad, no spawner, no async --
                                    -- so a blocked or full spawn pad is irrelevant and the whole move
                                    -- lands inside this pass, ledger included.
                                    local done = 0
                                    local drawn = SmartDistribution.drawInternal(p, pp, ft, n * cap, farmId)
                                    if drawn > 0 then
                                        local built = 0
                                        for _ = 1, math.floor(drawn / cap) do
                                            if SmartDistribution.shedFreeSlots(shed) <= 0 then break end
                                            if not SmartDistribution.createStoredPallet(shed, ft, cap, farmId) then break end
                                            built = built + 1
                                        end
                                        done = built * cap
                                        -- anything the shed would not take goes straight back; the draw
                                        -- happens FIRST so two consumers cannot claim the same litres
                                        if drawn > done then
                                            SmartDistribution.returnInternal(p, pp, ft, drawn - done, farmId)
                                        end
                                        if done > 0 then
                                            ledgerAdd(p, ft, "stored", done)
                                            ledgerAdd(shed, ft, "received", done)
                                            SmartDistribution.recordFeed(shed, ft, p, done)
                                        elseif SmartDistribution.debug then
                                            -- with the fallbacks gone this is the only sign of trouble,
                                            -- so it is worth a line: the class registry did not yield a
                                            -- usable object for this fill type.
                                            log("stageForShed %s [%s]: could not BUILD a stored pallet",
                                                placeableName(p), tostring(fillTypeName(ft)))
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
end

-- ============================================================================
-- DIRECT SHED INSERT -- put internal litres into a pallet shed with NO pallet, NO pad
--
-- The spawn-chain below works, but it needs one free pad slot at a time, so it CANNOT serve the case
-- this feature was most wanted for: a building whose spawn pad is BLOCKED or full. Observed in game
-- 2026-08-02 -- a greenhouse correctly decided "3 pallets to Bale & Pallet Storage" every cycle and moved
-- nothing, because `spawnPallet` returned RESULT_NO_SPACE. A Bakery and Spinnery beside it worked fine.
--
-- A shed's contents are ABSTRACT objects in `spec.storedObjects`, not live pallets, and DR has been
-- moving them between sheds for months in `transferShedPallets` -- `table.remove` from one, append to
-- the other, fix `numStoredObjects`, raise the dirty flag. So the object is an OPAQUE HANDLE DR can
-- already manipulate without understanding it. The only thing missing was one to insert.
--
-- CLONE FIRST, construct second, and that order is deliberate. `storedObjectAttrs` shows the fill data
-- lives in a NESTED table (`palletAttributes` / `baleAttributes`), while the savegame writes it FLAT
-- (`<object className="Vehicle" filename=... fillType="BREAD" fillLevel="1000"/>`) -- so the in-memory
-- shape is NOT the persisted shape, and building one from the XML field names would be guesswork.
-- Copying an object that already works and rewriting only the leaves DR demonstrably understands
-- (fillType, fillLevel, filename, farmId) assumes nothing about the rest of the structure.
--
-- ON by default since 2026-08-02, when insert AND retrieval were both confirmed in game (see 6.12 for
-- the probe that made it correct). `sdPalletHook insert` still toggles it, which is the one-key fallback
-- to the spawn chain if a modded shed ever misbehaves. Every insert is verified and rolled back on
-- failure regardless, because the failure that matters is at RETRIEVAL -- when the player tries to take
-- the pallets back OUT -- which is far too late to notice.

-- the pallet i3d this fill type spawns as, so a cross-product clone points at the right model
-- ---- PHASE 5: THE GLOBAL PALLET REGISTRY ----------------------------------------------------------
-- The pallet model + capacity for a fill type, WITHOUT needing a spawner on the source building.
--
-- READ FROM THE BASE SOURCE (PalletSpawner.lua:80-85, measured 23% blank = complete), and its own comment
-- says it outright -- "load default global pallets defined at fillTypes registration":
--     for fillTypeId, fillType in pairs(g_fillTypeManager.indexToFillType) do
--         if fillType.palletFilename then self:loadPalletFromFilename(fillType.palletFilename, fillTypeId) end
-- So EVERY PalletSpawner loads a pallet for EVERY fill type that declares one, which makes any single
-- spawner's fillTypeIdToPallet a GLOBAL registry -- the 114-entry table 5.14 noted and mistook for a
-- curiosity. It carries `filename` AND `capacity`, both already parsed, so this needs no XML loading.
--
-- WHY IT IS NEEDED: the clone-era resolver read the SOURCE's own spawner, and a pass-through store has none
-- (confirmed: neither driveIn.xml nor driveInProd.xml declares a palletSpawner). So a bulk source could
-- never name the pallet to build, and materialisation refused every product that was not already stored
-- somewhere on the farm.
--
-- Falls back to the fill type's own declaration, which is where the spawner got it from -- so a farm with
-- no pallet spawner at all still resolves a model, just without a parsed capacity.
function SmartDistribution.globalPalletFor(ft)
    if ft == nil then return nil end
    local memo = SmartDistribution._globalPalletMemo
    if memo == nil then memo = {}; SmartDistribution._globalPalletMemo = memo end
    local hit = memo[ft]
    if hit ~= nil then return hit end

    -- THE FILL TYPE'S OWN DECLARATION DECIDES, AND IT IS THE ONLY THING THAT MEANS "this product comes on
    -- pallets": EGG -> eggBoxPallet, BREAD -> bakeryBoxPallet. Wheat, barley and every other bulk crop
    -- declare NO pallet at all.
    --
    -- READING A SPAWNER'S REGISTRY FIRST WAS WRONG, and the log named it: WHEAT resolved
    -- `model=fillablePallet.xml`. That pallet declares `fillTypeCategories="BULK"`, and a spawner's
    -- <pallets> block loads it with NO limitFillTypeId (base source), so it registers itself against
    -- EVERY bulk fill type. So every crop on the farm read as palletisable and phase 5 offered a pallet
    -- store as a Store / Move To destination for the entire harvest -- reported 2026-08-20 as "why is it
    -- showing as an option if it is not supported".
    --
    -- A generic fillable pallet CAN physically hold wheat; that is not the question. The question is
    -- whether the product is one DR should package, and the fill type answers it.
    local mgr = g_fillTypeManager
    local def = (mgr ~= nil and mgr.getFillTypeByIndex ~= nil) and mgr:getFillTypeByIndex(ft) or nil
    local fn  = def ~= nil and def.palletFilename or nil
    if fn == nil or fn == "nope" then return nil end            -- not a pallet product: never cached

    -- Capacity is a convenience, taken from any spawner registry entry for the SAME model (already
    -- parsed by the base game). A mismatch means that spawner carries a different pallet for this
    -- product, so its capacity does not describe ours -- palletLitresFor falls back in that case.
    local capacity = nil
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    for _, p in ipairs(ps ~= nil and ps.placeables or {}) do
        local sp = nil
        local pp = getProductionPoint(p)
        if pp ~= nil then sp = pp.palletSpawner
        elseif p.spec_husbandryPallets ~= nil then sp = SmartDistribution.husbandryPalletSpawner(p, ft) end
        local entry = (sp ~= nil and type(sp.fillTypeIdToPallet) == "table") and sp.fillTypeIdToPallet[ft] or nil
        if entry ~= nil and entry.filename == fn and (entry.capacity or 0) > 0 then
            capacity = entry.capacity
            break
        end
    end
    local found = { filename = fn, capacity = capacity }
    -- CACHE A HIT ONLY. Memoising a miss is the 5.29 trap, and 6.19 proved placeable loading is async, so
    -- a call made mid-load would otherwise answer "never a pallet" for the whole session.
    memo[ft] = found
    return found
end

-- "Could this product physically exist as a pallet at all?" -- the capability gate for materialising bulk
-- litres into a pallet store. A product with no declared pallet model can never reach one, and offering
-- such a destination would be offering something nothing could move to.
-- A pallet model shared by MANY fill types is a GENERIC CONTAINER, not "this product's pallet".
--
-- Measured across the base game's 96 pallet-declaring fill types: 77 models are claimed by exactly ONE
-- fill type (eggBoxPallet -> EGG, woolPallet -> WOOL, silageAdditivePallet -> SILAGE_ADDITIVE), one by
-- THREE (vegetablesPallet -> beetroot/carrot/parsnip, still a produce pallet) and one by **SIXTEEN** --
-- `fillablePallet`, which every bulk crop declares. The distribution is bimodal with NOTHING between 3
-- and 16, so the threshold is taken from that empty band rather than fitted to a sample (the same way
-- SPAWN_PLACE_ACROSS_TOL was chosen).
--
-- WHY IT MATTERS: wheat, barley, oat and thirteen more genuinely DO declare a pallet, so "does the fill
-- type declare one" is true for them and offered a pallet store as a Store / Move To destination for the
-- entire harvest. A fillable pallet CAN hold wheat; it is not wheat's packaging.
SmartDistribution.GENERIC_PALLET_MIN = 4

function SmartDistribution.palletModelIsGeneric(filename)
    if filename == nil then return false end
    local memo = SmartDistribution._palletModelUse
    if memo == nil then
        memo = {}
        local mgr = g_fillTypeManager
        local all = (mgr ~= nil) and mgr.indexToFillType or nil
        if type(all) == "table" then
            for _, def in pairs(all) do
                local fn = def ~= nil and def.palletFilename or nil
                if fn ~= nil then memo[fn] = (memo[fn] or 0) + 1 end
            end
        end
        SmartDistribution._palletModelUse = memo
    end
    return (memo[filename] or 0) >= SmartDistribution.GENERIC_PALLET_MIN
end

function SmartDistribution.canMaterialisePallets(ft)
    local g = SmartDistribution.globalPalletFor(ft)
    if g == nil then return false end
    -- ...and that is the whole test. It USED to also require "some way to put one in a store" -- a stored
    -- object to clone, or a spawner to mint the first -- because the old insert could only CLONE.
    -- createStoredPallet builds through the game's own savegame path (6.22) and needs neither, so that
    -- gate now only hides pallet stores from a farm that could in fact use them: a fresh save with a silo
    -- and a pallet store and nothing else is exactly the case it wrongly refused.
    return not SmartDistribution.palletModelIsGeneric(g.filename)
end

-- Litres one pallet of ft holds. The registry's parsed capacity where a spawner exists, else the shed's
-- own per-slot figure, else a conservative default -- never nil, because the caller divides by it.
function SmartDistribution.palletLitresFor(ft, shed)
    local g = SmartDistribution.globalPalletFor(ft)
    if g ~= nil and (g.capacity or 0) > 0 then return g.capacity end
    if shed ~= nil and SmartDistribution._shedLitresPerSlot ~= nil then
        local s = SmartDistribution._shedLitresPerSlot(shed)
        if (s or 0) > 0 then return s end
    end
    return 1000
end



-- The field holding a stored object's attributes, and the attributes themselves. The KEY varies by class
-- (palletAttributes for a Vehicle, baleAttributes for a Bale), so a new object has to be populated under
-- whichever key its own class uses rather than a hardcoded one.
function SmartDistribution.storedAttrsKey(obj)
    if type(obj) ~= "table" then return nil end
    for k, v in pairs(obj) do
        if type(v) == "table" and type(v.fillType) == "number" and type(v.fillLevel) == "number" then
            return k, v
        end
    end
    for _, k in ipairs({ "palletAttributes", "baleAttributes" }) do
        if type(obj[k]) == "table" then return k, obj[k] end
    end
    return nil
end

-- Is this stored object a PALLET rather than a BALE?
--
-- REPORTED 2026-08-06: a Bale & Pallet Storage holding 24 straw round bales and no pallets ended up with
-- "Round bale (Noodle Soup 1,000 l)" and "Round bale (Carton Roll 3,000 l)" in it, and taking them out
-- produced STRAW BALES. The clone-era template search fell back to "the first stored object of any kind",
-- so with no pallet on the farm to model on it cloned a BALE and only rewrote fillType / fillLevel /
-- ownerFarmId. CLONING IS GONE (6.22 builds from the savegame contract instead, so nothing is inherited
-- from an unrelated object) -- but this test still earns its place: repairSheds uses it to tell a pallet
-- from a bale when stripping objects a shed cannot use.
--
-- IDENTIFIES A PALLET POSITIVELY, and returns false when it cannot tell.
function SmartDistribution.storedObjectIsPallet(obj)
    if type(obj) ~= "table" then return false end
    local key = SmartDistribution.storedAttrsKey(obj)
    if key == "baleAttributes" then return false end
    local cn = obj.REFERENCE_CLASS_NAME
    if cn == "Bale" or cn == "PackedBale" then return false end
    if key == "palletAttributes" then return true end
    return cn == "Vehicle"        -- probed 2026-08-02: a stored pallet's REFERENCE_CLASS_NAME is "Vehicle"
end


-- Every method the base game calls on a stored object. A clone that answers all of these behaves like the
-- real thing everywhere PlaceableObjectStorage touches it: updateObjectStorageObjectInfos groups by
-- getIsIdentical and sorts by getSpawnInfo, spawnNextObjectStorageObject asks getLimitedObjectId and then
-- removeFromStorage, and saveToXMLFile needs REFERENCE_CLASS_NAME + saveToXMLFile.
SmartDistribution.STORED_OBJECT_METHODS = {
    "getIsIdentical", "getSpawnInfo", "getLimitedObjectId", "removeFromStorage", "saveToXMLFile",
}
function SmartDistribution.storedObjectIsUsable(obj)
    if type(obj) ~= "table" then return false end
    for _, name in ipairs(SmartDistribution.STORED_OBJECT_METHODS) do
        if type(obj[name]) ~= "function" then return false end
    end
    return obj.REFERENCE_CLASS_NAME ~= nil
end

-- Remove any stored object a shed cannot actually use, farm-wide. Recovery for objects an earlier build
-- inserted that fail storedObjectIsUsable -- they make updateObjectStorageObjectInfos throw on EVERY
-- frame, so the shed is unusable until they are gone. Returns how many were removed.
function SmartDistribution.repairSheds()
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return 0 end
    local removed = 0
    for _, p in ipairs(ps.placeables) do
        local oss = p.spec_objectStorage
        if oss ~= nil and type(oss.storedObjects) == "table" then
            local n = 0
            for i = #oss.storedObjects, 1, -1 do
                if not SmartDistribution.storedObjectIsUsable(oss.storedObjects[i]) then
                    table.remove(oss.storedObjects, i); n = n + 1
                end
            end
            if n > 0 then
                oss.numStoredObjects = #oss.storedObjects
                removed = removed + n
                print(string.format("[SmartDistribution] shedRepair %s: removed %d unusable object(s), %d left",
                    placeableName(p), n, oss.numStoredObjects))
                if p.setObjectStorageObjectInfosDirty ~= nil then
                    pcall(function() p:setObjectStorageObjectInfosDirty() end)
                end
            end
        end
    end
    return removed
end
function SmartDistribution.cmdShedRepair(self)
    local n = SmartDistribution.repairSheds()
    return string.format("shedRepair: removed %d unusable stored object(s)", n)
end



-- Take `litres` out of the building's own internal store (production buffer or pen queue). Returns what
-- actually came out, so the caller only ever credits product that genuinely left.
--
-- Drawn BEFORE the shed insert, not after: the insert can be refused part-way (shed fills, a clone fails
-- verification), and taking first means the litres are never in two places at once. returnInternal puts
-- back whatever the shed would not take -- the same take-then-refund shape slotMove uses for a source
-- that may fall short (5.30's verifyDrain).
function SmartDistribution.drawInternal(p, pp, ft, litres, farmId)
    if litres <= 0 then return 0 end
    if pp ~= nil then
        local lvl  = getLevel(pp.storage, ft) or 0
        local take = math.min(litres, lvl)
        if take <= 0 then return 0 end
        setLevel(pp.storage, ft, lvl - take, farmId, -take)
        return take
    end
    return SmartDistribution.drawFromQueue(p, ft, litres) or 0
end
function SmartDistribution.returnInternal(p, pp, ft, litres, farmId)
    if litres <= 0 then return end
    if pp ~= nil then
        setLevel(pp.storage, ft, (getLevel(pp.storage, ft) or 0) + litres, farmId, litres)
    else
        SmartDistribution.returnToQueue(p, ft, litres)
    end
end


-- Deferred ledger: entries raised outside the hourly pass, folded in at the start of the next one.
SmartDistribution._pendingLedger = {}

-- free object slots left in a pallet shed
function SmartDistribution.shedFreeSlots(shed)
    local oss = shed ~= nil and shed.spec_objectStorage or nil
    if oss == nil then return 0 end
    local cap = oss.capacity or 0
    if cap <= 0 then return math.huge end
    local stored = (oss.storedObjects ~= nil and #oss.storedObjects) or (oss.numStoredObjects or 0)
    return math.max(0, cap - stored)
end

-- The pallet shed this source should push `ft` into: nearest / highest-ranked valid one. Mirrors the shed
-- half of _storeToPalletAmount's candidate filter (in range, same farm, not blocked) so the two cannot
-- disagree -- there is no point materialising a pallet for a shed that would refuse it. Returns
-- (shed placeable, d2) or nil.
function SmartDistribution.shedSinkFor(p, ft, farmId)
    if p == nil or p.rootNode == nil then return nil end
    local srcUid = getUid(p); if srcUid == nil then return nil end
    local x, _, z = getWorldTranslation(p.rootNode)
    local myFarm  = SmartDistribution._ownerFarmId(p)
    local cands = {}
    for _, sh in ipairs(gatherShedSinks(p, ft, x, z, farmId, resolveReach(p))) do
        -- Every entry here is a SHED sink by construction, so the destination is the SHED role -- which
        -- collapses to the bare uid on an ordinary pallet store and only mints a suffix on a building
        -- that also does something else. NOTE this caller deliberately does not pass includeSelf: see the
        -- header on gatherShedSinks.
        local du = sh.placeable ~= nil and SmartDistribution.storeRoleUid(sh.placeable, ft, "PALLET") or nil
        if du ~= nil and not SmartDistribution.isSelfDestination(srcUid, du) and SmartDistribution._farmCanUse(sh.placeable, myFarm)
           and not SmartDistribution.isDestBlocked(srcUid, ft, du) then
            sh.destRole = "SHED"
            sh.rank = SmartDistribution.destRank(srcUid, ft, du)
            cands[#cands + 1] = sh
        end
    end
    table.sort(cands, function(a, b)
        if (a.rank ~= nil) ~= (b.rank ~= nil) then return a.rank ~= nil end
        if a.rank ~= nil and b.rank ~= nil and a.rank ~= b.rank then return a.rank < b.rank end
        return (a.d2 or 0) < (b.d2 or 0)
    end)
    local best = cands[1]
    if best == nil then return nil end
    return best.shed or best.placeable, best.d2
end

function SmartDistribution.spawnWholePallets()
    -- fullPalletSpawn is true for BOTH whole-pallet and never (it means "vanilla auto-spawn is
    -- suppressed"), so NEVER has to be excluded explicitly here or DR would go on releasing the very
    -- pallets the setting exists to prevent.
    if not S.global.fullPalletSpawn then return end
    if not SmartDistribution.palletSpawnAllowed() then return end
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return end
    for _, p in ipairs(ps.placeables) do
        local hs = p.spec_husbandryPallets
        if hs ~= nil and type(hs.pendingLiters) == "table" and isEnrolled(p) then
            local fts = palletSpawnerFillTypes(p)
            if fts ~= nil then
                for _, ft in ipairs(fts) do
                    if resolveMode(p, ft) ~= MODE.HOLD_INTERNAL and not S.global.excludedFillTypes[ft] then
                        local cap  = SmartDistribution.palletCapacityForHusbandry(p, ft) or 0
                        local pend = hs.pendingLiters[ft] or 0
                        if cap > 0 and pend >= cap then
                            local n = math.floor(pend / cap)
                            if SmartDistribution.debug then
                                log("wholePallet %s [%s] buffer=%.0f cap=%.0f -> release %d pallet(s)",
                                    placeableName(p), tostring(fillTypeName(ft)), pend, cap, n)
                            end
                            SmartDistribution.spawnPalletsFromHusbandry(p, ft, n)
                        end
                    end
                end
            end
        end
    end
end

-- Clear EMPTY pallets off a pen's pad. Nothing else can: drainPallets only deletes a pallet it drains to
-- zero, so a pallet that reached 0 L by any other route stayed there forever.
--
-- Only reachable state now is a save that already had them -- an earlier build spawned pallets it could not
-- fill (see _fillSpawnedPalletFromHusbandry) and left them standing. Guarded two ways so a player's own
-- property is never touched: the pallet must be one the PEN spawned (still in the spec's own tracked set),
-- and vanilla auto-spawn must be suppressed for that fill type -- otherwise the base game's trickle-fill
-- owns the pad and an empty pallet there is simply one it is about to fill.
-- Pallets standing on this building's pad with NOTHING in them, found by geometry alone.
--
-- **It cannot go through husbandryPalletObjects, and that is the whole reason empty pallets survived.**
-- That function filters on `getFillUnitFillType(idx) == ft`, and an EMPTY pallet has no fill type -- it
-- reports UNKNOWN, never BREAD -- so a per-fill-type lookup can never return one. Every previous attempt
-- to clear empties looped it looking for `lvl <= 0` and was therefore searching a list that by
-- construction could not contain what it was looking for. Reported in game 2026-08-02: two empty pallets
-- per bakery survived a reclaim pass that correctly recovered the partial one beside them.
--
-- So: scan the vehicles directly, test the PAD geometry (5.17 -- on my pad => mine), and sum EVERY fill
-- unit rather than the one a fill type would have picked. Returns {} when the building has no resolvable
-- spawn places, so a modded spawner is never guessed at and a pallet merely parked nearby is never taken.
function SmartDistribution.emptyPadPallets(p)
    local out = {}
    local vs = g_currentMission ~= nil and g_currentMission.vehicleSystem or nil
    if p == nil or p.rootNode == nil or vs == nil or type(vs.vehicles) ~= "table" then return out end
    if #SmartDistribution.spawnPlacesOf(p) == 0 then return out end
    local hx, _, hz = getWorldTranslation(p.rootNode)
    local farmId = (p.getOwnerFarmId ~= nil and p:getOwnerFarmId()) or p.ownerFarmId
    local radius = (getProductionPoint(p) ~= nil) and PALLET_ASSOC_RADIUS_PROD or PALLET_ASSOC_RADIUS
    local r2 = radius * radius
    for _, v in ipairs(vs.vehicles) do
        if v ~= nil and v.isPallet and v.rootNode ~= nil then
            local vfarm = (v.getOwnerFarmId ~= nil and v:getOwnerFarmId()) or v.ownerFarmId
            if vfarm == nil or farmId == nil or vfarm == farmId then
                local vx, _, vz = getWorldTranslation(v.rootNode)
                local dx, dz = vx - hx, vz - hz
                if dx * dx + dz * dz <= r2 and SmartDistribution.palletOnSpawner(p, vx, vz) then
                    local total = 0
                    if v.getFillUnits ~= nil and v.getFillUnitFillLevel ~= nil then
                        local units = v:getFillUnits() or {}
                        for i = 1, #units do total = total + (v:getFillUnitFillLevel(i) or 0) end
                    elseif v.getFillUnitFillLevel ~= nil then
                        local idx = (v.spec_pallet ~= nil and v.spec_pallet.fillUnitIndex) or 1
                        total = v:getFillUnitFillLevel(idx) or 0
                    end
                    if total <= 0 then out[#out + 1] = v end
                end
            end
        end
    end
    return out
end

function SmartDistribution.sweepEmptyPadPallets()
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil then return end
    for _, p in ipairs(ps.placeables) do
        -- Only sweep a pad DR is responsible for, or a pallet the base game is merely about to fill would
        -- be taken out from under it.
        --   * PEN -- DR is suppressing its vanilla auto-spawn, so nothing else will ever fill this.
        --   * PRODUCTION -- pallet spawning is switched off entirely (5.41), same reasoning.
        -- Ownership within that is the PAD, never spec.pallets: probed in game, a DR-released pallet is
        -- never in that set, because the base game registers pallets inside the very function DR
        -- overrides. 5.17's rule applies -- on my pad => mine -- and emptyPadPallets tests exactly that,
        -- returning nothing when the building has no resolvable spawn geometry (5.18).
        local hs  = p.spec_husbandryPallets
        local pp  = getProductionPoint(p)
        local own = false
        if hs ~= nil then
            own = SmartDistribution.suppressedPalletFillTypes(p) ~= nil
        elseif pp ~= nil and pp.palletSpawner ~= nil then
            own = not SmartDistribution.palletSpawnAllowed()
        end
        if own then
            for _, pallet in ipairs(SmartDistribution.emptyPadPallets(p)) do
                if SmartDistribution.debug then
                    log("sweepEmptyPad %s: removing an empty pallet", placeableName(p))
                end
                if pallet.delete ~= nil then pcall(function() pallet:delete() end) end
                if hs ~= nil and type(hs.pallets) == "table" then hs.pallets[pallet] = nil end
            end
        end
    end
end
-- Keep the BASE GAME's own per-fill-type figure in step with reality for every fill type DR is suppressing.
--
-- Reported in game: a chicken coop holding one 1000 L pallet plus 430 L internally showed ZERO on the pen's
-- own vanilla UI. Cause: `spec_husbandryPallets.fillLevels[ft]` is the base game's record of the product it
-- holds, and vanilla maintains it inside `updatePallets` -- the very function DR overrides. On the
-- all-suppressed path that function is never called at all, and DR's own release path fills the pallet
-- directly (`_fillSpawnedPalletFromHusbandry` writes the pallet and debits `pendingLiters`) without ever
-- writing this field back. So it sat at whatever it was when DR took over: 0.
--
-- Written as the FULL stock, `pad + pendingLiters`, which is what the request asked for and also exactly what
-- `assetHeld` reports (5.21) -- so the pen's own UI and DR's tabs now state the same number instead of
-- disagreeing. RECOMPUTED from live state on every tick rather than adjusted incrementally, so it is
-- self-correcting: a pallet DR ships, one the player forklifts away, and one released from the queue all
-- land correctly with no bookkeeping to drift.
--
-- Only ever written for SUPPRESSED fill types. Where vanilla still drives the spawn it also still owns this
-- field, and DR must not fight it.
--
-- NOTE the base game's own denominator (`capacities[ft]`, probed at 6000 for WOOL) already accounts for the
-- pallet limit, while a HOLD_INTERNAL queue is unbounded -- so a long-held pen can read above its stated
-- capacity. Showing the true total is the point; clamping would hide product.
-- The two terms have VERY different costs, so they are refreshed at different rates.
--   * pendingLiters is a plain table read and changes continuously as the animals produce -> every call.
--   * the PAD total goes through husbandryPalletObjects, which walks the whole vehicleSystem list to find
--     loose pallets and then runs the spawn-place geometry on each candidate. updatePallets is a base-game
--     tick, so calling that unthrottled would put a full vehicle scan per pen on a hot path -- the same
--     mistake storageOwnerOf is cached to avoid. It also barely ever changes: only a spawn, a DR shipment
--     or a player moving a pallet can move it.
-- So the pad is cached per (pen, product) and re-read at most every SPEC_SYNC_SEC of REAL time (getTimeSec,
-- the established wall clock here -- real, so fast-forward does not multiply the work). Half a second is
-- imperceptible on a HUD, and a stale pad for that long cannot mislead anyone.
-- With no getTimeSec available it simply reads every call: correctness over speed.
SmartDistribution._specSyncPad  = {}   -- uid -> ft -> last pad litres read
SmartDistribution._specSyncAt   = {}   -- uid -> ft -> wall-clock seconds of that read
SmartDistribution.SPEC_SYNC_SEC = 0.5
function SmartDistribution.syncSpecFillLevels(p, fts)
    local hs = p ~= nil and p.spec_husbandryPallets or nil
    if hs == nil or fts == nil then return end
    local uid = getUid(p); if uid == nil then return end
    local now = (getTimeSec ~= nil) and getTimeSec() or nil
    local padRec = SmartDistribution._specSyncPad[uid]
    if padRec == nil then padRec = {}; SmartDistribution._specSyncPad[uid] = padRec end
    local atRec = SmartDistribution._specSyncAt[uid]
    if atRec == nil then atRec = {}; SmartDistribution._specSyncAt[uid] = atRec end
    for _, ft in ipairs(fts) do
        local at = atRec[ft]
        if padRec[ft] == nil or now == nil or at == nil or (now - at) >= SmartDistribution.SPEC_SYNC_SEC then
            local ok, total = pcall(SmartDistribution.husbandryPadState, p, ft)   -- returns (litres, byObject)
            if ok and type(total) == "number" then padRec[ft] = total end
            atRec[ft] = now
        end
        if type(hs.fillLevels) == "table" then
            hs.fillLevels[ft] = (padRec[ft] or 0) + (SmartDistribution.palletPendingLiters(p, ft) or 0)
        end
        -- capacities[ft] comes from the same suppressed computation and reads 0 too, which leaves the pen's
        -- UI with no denominator at all. husbandryPalletCapacity derives it when the field is empty.
        if type(hs.capacities) == "table" and (hs.capacities[ft] or 0) <= 0 then
            local cap = SmartDistribution.husbandryPalletCapacity(p, ft)
            if cap > 0 then hs.capacities[ft] = cap end
        end
    end
end

-- Drive the above for every pen DR is suppressing.
--
-- This does NOT hang off `updatePallets` alone, and that was the first attempt's mistake: hooking the
-- function whose bookkeeping went missing looks like the natural home, but DR's override is also what stops
-- it being CALLED, and its base-game cadence is unknown and unreadable (dataS.gar). Measured result: with the
-- sync only in that wrapper the coop still read 0 sixty seconds after load. So it is driven from DR's own
-- updateable instead, which is guaranteed to run and already has a throttle idiom for exactly this reason.
-- The wrapper still calls it too, harmlessly, so the figure is also refreshed at the moment vanilla would
-- have done it.
function SmartDistribution.syncAllPenFillLevels()
    local ps = g_currentMission ~= nil and g_currentMission.placeableSystem or nil
    if ps == nil or ps.placeables == nil then return end
    for _, p in ipairs(ps.placeables) do
        if p.spec_husbandryPallets ~= nil then
            -- suppressedPalletFillTypes is the exact gate: a pen DR is not suppressing still has vanilla
            -- maintaining these fields, and DR must not fight it.
            local held = SmartDistribution.suppressedPalletFillTypes(p)
            if held ~= nil then SmartDistribution.syncSpecFillLevels(p, held) end
        end
    end
end

function SmartDistribution.installHoldInternalPalletSuppression()
    if PlaceableHusbandryPallets == nil or PlaceableHusbandryPallets.updatePallets == nil then
        log("hold-internal pallet suppression: PlaceableHusbandryPallets.updatePallets not found [VERIFY]")
        return
    end
    PlaceableHusbandryPallets.updatePallets = Utils.overwrittenFunction(
        PlaceableHusbandryPallets.updatePallets,
        function(self, superFunc, ...)
            local held, rest = SmartDistribution.suppressedPalletFillTypes(self)
            if held == nil then return superFunc(self, ...) end          -- nothing suppressed -> vanilla
            -- Vanilla maintains its own fillLevels inside the call we are about to skip or narrow, so take
            -- that over for the suppressed types. Runs at the base game's own cadence, which is what keeps
            -- the pen's UI live rather than updating once an hour.
            SmartDistribution.syncSpecFillLevels(self, held)
            if #rest == 0 then return end                                -- all suppressed -> skip the whole pass
            -- partial: hide just the held fill types for this one call
            local spec = self.spec_husbandryPallets
            local savedFts, savedPending = spec.fillTypes, nil
            if type(spec.pendingLiters) == "table" then
                savedPending = {}
                for _, ft in ipairs(held) do
                    savedPending[ft] = spec.pendingLiters[ft] or 0
                    spec.pendingLiters[ft] = 0
                end
            end
            spec.fillTypes = rest
            local ok, err = pcall(superFunc, self, ...)
            spec.fillTypes = savedFts
            if savedPending ~= nil then
                for ft, v in pairs(savedPending) do
                    spec.pendingLiters[ft] = v + (spec.pendingLiters[ft] or 0)
                end
            end
            if not ok then log("hold-internal pallet suppression: updatePallets error: " .. tostring(err)) end
        end)
    log("hold-internal pallet suppression installed")
end

install()
installPersistence()
